['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <libconfig.h>

#define BUFFER_SIZE 4096

int main(int argc, char *argv[]) {
    int opt;
    const char *input_file = NULL;
    const char *output_file = NULL;
    int byte_count = BUFFER_SIZE;
    int verbose = 0;

    while ((opt = getopt(argc, argv, "cs:o:v")) != -1) {
        switch (opt) {
            case 'c':
                byte_count = atoi(optarg);
                break;
            case 's':
                output_file = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'v':
                verbose = 1;
                break;
            default:
                printf("Usage: %s [-c <byte_count>] [-s <output_file>] [-o <output_file>] [-v] <input_file>\n", argv[0]);
                return 1;
        }
    }

    if (argc - optind > 1) {
        input_file = argv[optind];
    } else {
        printf("Usage: %s [-c <byte_count>] [-s <output_file>] [-o <output_file>] [-v] <input_file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        perror("Error opening file");
        return 1;
    }

    int line_count = 0;

    char *buffer = malloc(BUFFER_SIZE);
    if (!buffer) {
        perror("Error allocating memory");
        fclose(fp);
        return 1;
    }

    while (fgets(buffer, BUFFER_SIZE, fp)) {
        line_count++;
    }

    fclose(fp);

    printf("%d lines in file %s\n", line_count, input_file);

    if (output_file) {
        FILE *fo = fopen(output_file, "w");
        if (!fo) {
            perror("Error opening output file");
        } else {
            fwrite(buffer, byte_count, 1, fo);
            fclose(fo);
        }
    }

    free(buffer);

    return 0;
}
