package com.example.fileuploadservice;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.multipart.MultipartFile;

public class FileUploadController {

  @Autowired
  private CloudStorageService cloudStorageService;

  @PostMapping("/upload")
  public ResponseEntity<String> handleFileUpload(@RequestParam("file") MultipartFile file) throws IOException {
    try {
      // Validate and process the file upload
      List<String> fileNames = new ArrayList<>();
      for (MultipartFile multipartFile : file.getFiles()) {
        String fileName = cloudStorageService.storeFile(multipartFile);
        fileNames.add(fileName);
      }
      return ResponseEntity.ok(fileNames);
    } catch (Exception e) {
      // Handle transient errors and retries
      int retryCount = 0;
      while (retryCount < 3 && !cloudStorageService.uploadCompleted()) {
        try {
          Thread.sleep(500); // wait for 500ms before retrying
        } catch (InterruptedException ie) {}
        retryCount++;
      }
      if (!cloudStorageService.uploadCompleted()) {
        throw new RuntimeException("Upload failed after retries", e);
      }
    }
    return ResponseEntity.ok("File uploaded successfully");
  }

}

