#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>

#define MAX_INPUT_SIZE 1000000
#define MIN_INT_VALUE -2147483648
#define MAX_INT_VALUE 2147483647

// Function to handle API request and store data in a dynamically allocated array
int* fetchIntegers(char* apiUrl, int* size) {
    CURL *curl;
    CURLcode res;
    char errorbuf[CURL_ERROR_SIZE];
    struct json_object *json_data = NULL;

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        // Set API URL and other options
        curl_easy_setopt(curl, CURLOPT_URL, apiUrl);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &json_data);

        // Perform the request
        res = curl_easy_perform(NULL);

        // Check for errors
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return NULL;
        }

        // Parse JSON data
        json_object* integers_json = json_object_object_get(json_data, "integers");
        int num_integers = json_object_array_length(integers_json);

        if(num_integers > 0) {
            *size = num_integers;

            // Dynamically allocate memory for the array
            int* integers = (int*)malloc((num_integers)*sizeof(int));

            if(integers == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                return NULL;
            }

            // Validate and store each integer in the array
            for(int i = 0; i < num_integers; i++) {
                int value = json_object_get_int(json_object_array_get_index(integers_json, i));
                if(value >= MIN_INT_VALUE && value <= MAX_INT_VALUE) {
                    integers[i] = value;
                } else {
                    // Log invalid integer values
                    fprintf(stderr, "Invalid integer value: %d\n", value);
                    return NULL;
                }
            }

            free(json_data);
            curl_easy_cleanup(curl);
            curl_global_cleanup();

            return integers;
        } else {
            // Log error if no data is retrieved
            fprintf(stderr, "No data retrieved from API\n");
            return NULL;
        }
    } else {
        // Log error if libcurl initialization fails
        fprintf(stderr, "Libcurl initialization failed\n");
        return NULL;
    }
}
