#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

typedef struct {
    LogLevel level;
    char* message;
} LogMessage;

// Thread-safe logger structure
typedef struct {
    pthread_mutex_t mutex;
    FILE* log_file;
    LogLevel log_level;
} SafeLogger;

void safe_logger_init(SafeLogger* logger, const char* log_file_path) {
    // Initialize the mutex
    pthread_mutex_init(&logger->mutex, NULL);

    // Open the log file
    logger->log_file = fopen(log_file_path, "a");
    if (logger->log_file == NULL) {
        printf("Error opening log file: %s\n", log_file_path);
        exit(1);
    }
}

void safe_logger_log(SafeLogger* logger, LogMessage message) {
    pthread_mutex_lock(&logger->mutex);

    // Check the log level and only log if it's at or above the threshold
    if (message.level >= logger->log_level) {
        // Write the log message to the file
        fprintf(logger->log_file, "[%s] %s\n", get_log_level_name(message.level), message.message);
    }

    pthread_mutex_unlock(&logger->mutex);
}

void safe_logger_shutdown(SafeLogger* logger) {
    // Close the log file
    fclose(logger->log_file);

    // Release the mutex
    pthread_mutex_destroy(&logger->mutex);
}
