#define SEM_MAX_VAL 100
#define SEM_NAME "semaphore"
#define SEM_LOG_FILE "semaphore.log"

typedef struct {
    pthread_mutex_t mutex;
    int value;
} semaphore_t;

semaphore_t* sem_create(int init_val) {
    if (init_val > SEM_MAX_VAL || init_val < 1) {
        perror("Invalid initial value");
        return NULL;
    }

    semaphore_t* sem = malloc(sizeof(semaphore_t));
    sem->value = init_val;
    pthread_mutex_init(&sem->mutex, NULL);
    return sem;
}

void sem_acquire(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    if (sem->value > 0) {
        --sem->value;
    } else {
        perror("Semaphore unavailable");
    }
    pthread_mutex_unlock(&sem->mutex);
}

void sem_release(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    ++sem->value;
    pthread_mutex_unlock(&sem->mutex);

    if (sem->value == 0) {
        // Semaphore is available, signal cleanup
        pthread_cleanup_push(cleanup_sem, sem);
    }
}

void cleanup_sem(void* arg) {
    semaphore_t* sem = (semaphore_t*)arg;
    pthread_mutex_lock(&sem->mutex);
    free(sem);
    pthread_mutex_unlock(&sem->mutex);
}

int main() {
    // Example usage
    int init_val = 5;
    semaphore_t* sem = sem_create(init_val);

    if (!sem) {
        return -1;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, sem);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_release(sem);

    return 0;
}

void* thread_func(void* arg) {
    semaphore_t* sem = (semaphore_t*)arg;

    // Simulate work
    for (int i = 0; i < 100000; i++) {
        sem_acquire(sem);
        usleep(10000); // simulate some work
        sem_release(sem);
    }

    return NULL;
}

