#include <forward_list>
#include <string>
#include <va_list.h>

void insertOrAppend(std::forward_list<std::string>& list,
                     const std::string& target,
                     const std::string& item) {
    bool found = false;
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        // Append the item
        list.append(item);
        return;
    }

    // Insert the item after the target string
    it = list.insert_after(it, item);

    // Log an error message in case of insertion failure
    if (list.end() != it) {
        va_list args;
        va_start(args, "error");
        const char* fmt = "Error inserting '%s' at position %zu: %s";
        snprintf(nullptr, 0, fmt, item.c_str(), std::distance(list.begin(), it), va_arg(args, char*));
        va_end(args);
        // Log the error message using a centralized logging service
    }
}
