public:
    explicit CloudSeededRandomGenerator(uint32_t seed) : seed_(seed), mt_(seed) {}

    void reseedingHandler() {
        while (true) {
            try {
                // Attempt reseeding from external API
                auto newSeed = getNewSeedFromAPI();
                if (newSeed != seed_) {
                    seed_ = newSeed;
                    mt_.reset(seed_);
                    std::cout << "Reseeded with new value: " << seed_ << std::endl;
                }
            } catch (...) {
                // Handle API failures and retries
                std::this_thread::sleep_for(std::chrono::seconds(10));
            }
        }
    }

    static void initializeGlobalState(uint32_t seed) {
        // Reset the global state of the Mersenne Twister to a new seed for all instances
        mt_.reset(seed_);
    }

    double generateUniformDouble() {
        return (mt_ >> 5);
    }

    int generateInRange(int min, int max) {
        uint32_t randInt = static_cast<uint32_t>(generateUniformDouble() * (max - min + 1)) + min;
        return static_cast<int>(randInt);
    }

private:
    std::mutex mtx_;
    uint32_t seed_;
    MT mt_;

    // Define the Mersenne Twister algorithm
    struct MT {
        inline uint32_t next(uint32_t y) const {
            y = (y ^ ((y << 11) & 0xfffffffff8000000)) & 0x7ff;
            return y * 9908 + 1;
        }
        void reset(uint32_t seed) { x_ = y_ = 196911;
          m_ = 3972197739; z_ = 182);
          for (int i = 0; i < 4; i++) {
            x_ ^= ((x_ >> 15) | (x_ << 17)) * 2102279;
            y_ ^= ((y_ >> 13) | (y_ << 7)) * 12393351;
          }
        }

        uint32_t operator>>(int n) const {
            return (x_ >> n) + (y_ >> n);
        }
    };
};

