using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;

namespace DatabaseConnectionPooling
{
    public class ConnectionPool
    {
        private readonly Dictionary<string, SqlConnection> _connections = new();
        private readonly List<int> _connectionSizes = new();
        private readonly object _lock = new();

        public void Initialize(string connectionString, int initialSize)
        {
            for (int i = 0; i < initialSize; i++)
            {
                _connections.Add(i.ToString(), new SqlConnection(connectionString));
            }
        }

        public void AddConnection(int size)
        {
            lock (_lock)
            {
                _connectionSizes.Add(size);
                _connections.Add(_connectionSizes.Count.ToString(), new SqlConnection(connectionString));
            }
        }

        public void RemoveConnection(int size)
        {
            lock (_lock)
            {
                var connection = _connections.FirstOrDefault(x => int.Parse(x.Key) == size).Value;
                if (connection != null)
                {
                    connection.Dispose();
                    _connections.Remove(size.ToString());
                    _connectionSizes.Remove(size);
                }
            }
        }

        public void ExecuteQuery(string query)
        {
            lock (_lock)
            {
                foreach (var connection in _connections.Values)
                {
                    try
                    {
                        connection.Open();
                        var command = new SqlCommand(query, connection);
                        command.ExecuteNonQuery();
                        connection.Close();
                        return;
                    }
                    catch (SqlException ex) when (ex.ErrorCode == 18456)
                    {
                        continue; // Pool exhausted, wait for more connections to be added
                    }
                }
            }
        }

        public void MonitorLoad(string monitoringAPIConnectionString)
        {
            while (true)
            {
                try
                {
                    using var connection = new SqlConnection(monitoringAPIConnectionString);
                    connection.Open();
                    var loadMetrics = new SqlCommand("SELECT * FROM LoadMetrics", connection).ExecuteScalar();
                    int newSize = int.Parse(loadMetrics.ToString());
                    AddConnection(newSize);
                    RemoveConnection(_connectionSizes.Min());
                    connection.Close();
                }
                catch (SqlException ex) when (ex.ErrorCode == 18456)
                {
                    // Network latency or monitoring API downtime, wait for a few seconds and retry
                    Thread.Sleep(5000);
                }
            }
        }

        public void LogStatistics()
        {
            foreach (var connection in _connections.Values)
            {
                var statistics = new SqlCommand("SELECT * FROM Statistics", connection).ExecuteScalar();
                Console.WriteLine(statistics.ToString());
            }
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var pool = new ConnectionPool();
            pool.Initialize("Data Source=database;Initial Catalog=mydb;User ID=myuser;Password=mypassword", 5);
            pool.MonitorLoad("Data Source=monitoring-api;Initial Catalog=myloadmetrics;User ID=myuser;Password=mypassword");
        }
    }
