using System;
using System.Xml.Linq;
using System.Threading.Tasks;

public class XmlParser
{
    public async Task<XElement> GetLatestElementAsync(XDocument doc, string elementName)
    {
        var query = doc.XPathSelectElements($"//{elementName}[last()]");
        if (query.Count() == 0)
        {
            System.Diagnostics.Debug.WriteLine("Warning: No matching elements found.");
            return null;
        }
        else
        {
            return query.Last();
        }
    }

    public async Task<XElement> GetLatestElementAsync(string url, string elementName)
    {
        using (var webClient = new System.Net.WebClient())
        {
            try
            {
                var xmlContent = await webClient.DownloadStringTaskAsync(url);
                var doc = XDocument.Parse(xmlContent);
                return await GetLatestElementAsync(doc, elementName);
            }
            catch (System.Net.WebException ex)
            {
                if ((ex.Status == System.Net.WebExceptionStatus.SendFailure || ex.Status == System.Net.WebExceptionStatus.ReceiveFailure) && int.TryParse(System.Environment.GetEnvironmentVariable("RETRY_ATTEMPTS"), out var retryAttempts))
                {
                    await Task.Delay(int.Parse(System.Environment.GetEnvironmentVariable("RETRY_DELAY")));
                    return await GetLatestElementAsync(url, elementName);
                }
                else
                {
                    throw;
                }
            }
        }
    }
}
