        [ProducesResponseType(StatusCodes.Status500InternalServerError)]
        public async Task<IActionResult> UpdatePageSection([FromRoute] string sectionId, [FromBody] PageSectionUpdateRequest request)
        {
            try
            {
                // Sanitize the incoming HTML content using the external service
                var sanitizedHtml = await _htmlSanitizer.SanitizeAsync(request.HtmlContent);

                // Store the updated page section in memory cache for efficient retrieval
                _memoryCache.Set(sectionId, sanitizedHtml);

                return Ok();
            }
            catch (Exception ex) when (IsTransientError(ex))
            {
                // Implement retry logic and fallback strategies if the external service is unavailable
                await RetrySanitizationAsync(request);
                return Ok();
            }
        }

        private async Task RetrySanitizationAsync(PageSectionUpdateRequest request)
        {
            // Implement a retry mechanism with exponential backoff to handle transient errors
            for (int i = 1; i <= 3; i++)
            {
                try
                {
                    var sanitizedHtml = await _htmlSanitizer.SanitizeAsync(request.HtmlContent);
                    // Store the updated page section in memory cache
                    _memoryCache.Set(request.SectionId, sanitizedHtml);
                    return;
                }
                catch (HttpRequestException)
                {
                    // Fallback to a local caching strategy if the external service is unavailable
                    _memoryCache.Set(request.SectionId, request.HtmlContent);
                    return;
                }
            }

            // Log and handle permanent errors or failures
            await LoggingAsync(request, ex);
        }

        private async Task LoggingAsync(PageSectionUpdateRequest request, Exception ex)
        {
            // Implement comprehensive logging that captures detailed information about failed requests
            await _logger.LogErrorAsync(ex, $"Failed to update page section '{request.SectionId}' with user action '{request.UserAction}' and environment variables {request.EnvironmentVariables}");
        }

        private bool IsTransientError(Exception ex) => ex is HttpRequestException || ex.IsTransient();
    }
}
