const fs = require('fs');
const path = require('path');
const axios = require('axios');
const { promisify } = require('util');
const { mkdir, writeFile, readFile } = promisify(fs);
const { join } = promisify(path);

class FileProcessor {
  constructor(options) {
    this.options = options;
    this.cache = {};
    this.transformer = this.options.transformer;
    this.apiClient = axios.create({
      baseURL: this.options.apiUrl,
      timeout: this.options.apiTimeout
    });
  }

  async processFiles(directory) {
    const files = await fs.readdir(directory);
    for (const file of files) {
      if (!file.endsWith('.json')) continue;
      const filePath = join(directory, file);
      try {
        const contents = await readFile(filePath);
        const data = JSON.parse(contents);
        const transformedData = this.transformer(data);
        // Cache the processed data
        this.cache[filePath] = transformedData;

        // Fetch metadata from API and cache it if not already present
        const metadataPath = filePath.replace('.json', '-metadata.json');
        if (!this.cache[metadataPath]) {
          try {
            const metadata = await this.fetchMetadata(metadataPath);
            this.cache[metadataPath] = metadata;
          } catch (error) {
            console.error(`Error fetching metadata for ${file}:`, error);
          }
        }
      } catch (error) {
        console.error(`Error processing file ${file}:`, error);
      }
    }
  }

  async fetchMetadata(metadataPath) {
    try {
      const response = await this.apiClient.get(metadataPath);
      return JSON.parse(response.data);
    } catch (error) {
      if (error.response.status === 429) {
        // Handle API throttling
        console.log(`API rate limit exceeded. Retrying in ${this.options.apiRetryTimeout}ms.`);
        await new Promise((resolve) => setTimeout(resolve, this.options.apiRetryTimeout));
        return this.fetchMetadata(metadataPath);
      }
      throw error;
    }
  }

  async writeCacheToFile(cacheFilePath) {
    try {
      await writeFile(cacheFilePath, JSON.stringify(this.cache));
    } catch (error) {
      console.error(`Error writing cache to file ${cacheFilePath}:`, error);
    }
  }

  async loadCacheFromFile(cacheFilePath) {
    try {
      const contents = await readFile(cacheFilePath);
      this.cache = JSON.parse(contents);
    } catch (error) {
      console.error(`Error loading cache from file ${cacheFilePath}:`, error);
    }
  }

  async start() {
    await mkdir(this.options.cacheDirectory, { recursive: true });
    await this.processFiles(this.options.inputDirectory);

    // Write the cache to a file for persistence
    await this.writeCacheToFile(join(this.options.cacheDirectory, 'file-cache.json'));

    console.log('File processing complete. Cache written to file.');
  }
}

module.exports = FileProcessor;
