function executeModuleTests(moduleName) {
  const log = require('third-party-logging-service');
  const tests = require(`./${moduleName}/tests`);
  const dependencies = require(`./${moduleName}/dependencies`);

  async function runTest(test) {
    try {
      await test();
    } catch (error) {
      log.error(`Test "${test.name}" failed: ${error.message}`);
    }
  }

  async function executeTests() {
    let testCount = 0;
    let successfulTests = 0;

    for (const test of Object.values(tests)) {
      if (!dependencies.includes(test.dependency)) {
        await runTest(test);
        if (!test.error) {
          successfulTests++;
        }
      } else {
        log.info(`Skipping test "${test.name}" due to unmet dependency`);
      }

      testCount++;
    }

    log.info(`${successfulTests}/${testCount} tests passed.`);
  }

  async function retryFailedTests(maxRetries = 3, timeout = 5000) {
    for (const test of Object.values(tests)) {
      if (!test.error && test.retryable) {
        let retries = 0;
        while (retries < maxRetries) {
          try {
            await runTest(test);
            break;
          } catch (error) {
            if (retries >= maxRetries) {
              log.error(`Test "${test.name}" failed after ${maxRetries} retries: ${error.message}`);
            }
            retries++;
            await new Promise(resolve => setTimeout(resolve, timeout));
          }
        }
      }
    }
  }

  async function execute() {
    try {
      await executeTests();
      await retryFailedTests();
    } catch (error) {
      log.error('Error executing tests:', error);
    }
  }

  return { execute };
}

module.exports = executeModuleTests;
