async function renderFooterScripts(scripts) {
  const footer = document.createElement('footer');

  // Implement caching to handle large arrays of script objects
  const metadataCache = {};
  const apiEndpoint = 'https://api.example.com/script-metadata';

  for (const script of scripts) {
    if (!script.scriptId || !script.scriptContent) {
      console.error(`Invalid script object: ${JSON.stringify(script)}`);
      continue;
    }

    try {
      // Fetch metadata and retry on failure
      let metadata = await fetchMetadata(apiEndpoint, script.scriptId);
      if (!metadata) {
        metadata = await fetchMetadata(apiEndpoint, script.scriptId); // Retry once
        if (!metadata) {
          console.error(`Failed to retrieve metadata for script ${script.scriptId}`);
          continue;
        }
      }

      // Validate fetched metadata fields
      if (!metadata.version || !metadata.author || !metadata.dependencies) {
        console.error(`Invalid metadata for script ${script.scriptId}`);
        continue;
      }

      const scriptTag = document.createElement('script');
      scriptTag.type = 'text/javascript';
      scriptTag.key = script.scriptId;
      scriptTag.dataset.version = metadata.version;
      scriptTag.dataset.author = metadata.author;
      scriptTag.dataset.dependencies = metadata.dependencies;
      scriptTag.innerHTML = script.scriptContent;

      footer.appendChild(scriptTag);
    } catch (error) {
      console.error('Error rendering script:', error);
    }
  }

  // Clear existing scripts and re-render
  if (document.getElementById('footerScripts')) {
    document.getElementById('footerScripts').remove();
  }
  document.body.appendChild(footer);
}

async function fetchMetadata(apiEndpoint, scriptId) {
  try {
    const response = await fetch(`${apiEndpoint}/${scriptId}`);
    const metadata = await response.json();
    return metadata;
  } catch (error) {
    if (error.status === 404) {
      // Script not found
      return null;
    }

    // Retry once on failure
    await wait(1000); // Wait for 1 second
    return await fetchMetadata(apiEndpoint, scriptId);
  }
}

// Helper function to simulate a delay
async function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
