void *load_bundle_from_external_data_source(void *ptr) {
    // Load the resource bundle from external data source
    FILE *fp = fopen("bundle.txt", "r");
    if (fp == NULL) return NULL;

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    rewind(fp);
    char *data = malloc(size + 1);
    fread(data, 1, size, fp);
    fclose(fp);
    data[size] = '\0';

    Bundle *bundle = malloc(sizeof(Bundle));
    bundle->id = bundle_count;
    bundle->data = data;
    bundle_count++;

    if (bundle_count >= bundle_capacity) {
        bundle_capacity *= 2;
        bundles = realloc(bundles, sizeof(Bundle *) * bundle_capacity);
    }
    bundles[bundle_count - 1] = bundle;

    return NULL;
}

