// dom-traversal.service.ts
import { Injectable } from '@nestjs/common';
import * as cheerio from 'cheerio';
import axios from 'axios';

@Injectable()
export class DomTraversalService {
  private readonly apiEndpoint = 'https://api.example.com/metadata';
  private readonly rateLimit = 10; // requests per minute
  private readonly cacheTtl = 60 * 1000; // seconds
  private readonly cache: any;
  private readonly concurrency = 5;

  constructor() {
    this.cache = new Map();
  }

  async traverseDomTree(domTree: string): Promise<any[]> {
    const $ = cheerio.load(domTree);
    const elements = [];

    $('*').each((index, element) => {
      const selector = $(element).attr('selector');
      if (selector) {
        const metadata = this.getMetadata(selector);
        if (metadata) {
          elements.push(metadata);
        }
      }
    });

    return elements;
  }

  private async getMetadata(selector: string): Promise<any> {
    const cachedResponse = this.cache.get(selector);
    if (cachedResponse) {
      return cachedResponse;
    }

    try {
      const response = await axios.get(`${this.apiEndpoint}/${selector}`, {
        headers: { 'X-RateLimit-Reset': Date.now() / 1000 },
        rateLimit: {
          max: this.rateLimit,
          windowMs: 60 * 1000, // 1 minute
          delayMs: 2000, // 2 seconds
        },
      });

      const metadata = response.data;
      this.cache.set(selector, metadata);
      setTimeout(() => this.cache.delete(selector), this.cacheTtl);

      return metadata;
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  private async processElements(elements: any[], concurrency: number): Promise<any[]> {
    const promises = elements.map((element) =>
      axios.post('process-element', element, {
        maxRedirects: 5,
        timeout: 30000,
      })
    );

    return await Promise.all(promises);
  }
}

// dom-traversal.module.ts
import { Module } from '@nestjs/common';
import { DomTraversalService } from './dom-traversal.service';

@Module({
  providers: [DomTraversalService],
})
export class DomTraversalModule {}

