import java.util.ArrayList;
import java.util.List;

class UnionFind {
    private List<Integer> parent;
    private int size;

    public UnionFind(int n) {
        this.parent = new ArrayList<>(n);
        this.size = n;
        for (int i = 0; i < n; i++) {
            parent.add(i);
        }
    }

    public void union(int x, int y) {
        if (find(x) == find(y)) return;

        parent.set(find(x), find(y));
        size--;
    }

    public int find(int x) {
        while (parent.get(x) != x) {
            x = parent.get(x);
        }
        return x;
    }
}

import java.util.Random;
import java.util.stream.IntStream;

public class DisjointPairService {

    private UnionFind unionFind;

    public DisjointPairService() {
        this.unionFind = new UnionFind(10_0000); // Initialize with a reasonable size
    }

    public int[] processArray(int[] array) {
        if (array == null || array.length == 0) return new int[0];

        IntStream.range(0, array.length).forEach(i -> unionFind.union(array[i], i));

        int count = 0;
        for (int i = 0; i < array.length - 1; i++) {
            if (unionFind.find(array[i]) != unionFind.find(array[i + 1])) {
                count++;
            }
        }

        return new int[]{count};
    }

    public static void main(String[] args) {
        DisjointPairService service = new DisjointPairService();
        // Example usage:
        int[] array = {1, 2, 3, 4, 5, 6}; // Input array
        int[] result = service.processArray(array);
        System.out.println("Disjoint pair count: " + result[0]);
    }
}
```

