import hashlib
import time
from flask import session, request, g
from flask_sqlalchemy import SQLAlchemy
from flask_caching import Cache
from requests.exceptions import RequestException
from celery import Celery, shared_task

# Initialize Flask-SQLAlchemy and Flask-Cache
db = SQLAlchemy()
cache = Cache()

# Define the session management system with Celery for distributed tasks
celery_app = Celery(__name__, broker='amqp://guest:guest@localhost')

# Session model
class Session(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, nullable=False)
    expires_at = db.Column(db.DateTime, nullable=False)

# Session utility functions
def generate_session_token(user_id):
    return hashlib.sha256(f"{user_id}{time.time()}".encode()).hexdigest()

def validate_session(session_token):
    session_data = Session.query.get(session_token)
    if not session_data:
        return False
    if time.time() > session_data.expires_at:
        return False
    return True

# Celery task for persisting sessions to distributed database
@celery_app.task
def persist_sessions():
    try:
        # Fetch all active sessions from the cache
        active_sessions = cache.get('active_sessions')

        if not active_sessions:
            return

        # Persist each session to the distributed database
        for session_id, user_id in active_sessions.items():
            session_data = Session.query.get(session_id)
            if session_data:
                db.session.commit()

    except RequestException as e:
        print(f"Error persisting sessions: {e}")

# Flask route for creating new sessions
@app.route('/login', methods=['POST'])
def create_session():
    user_id = request.form['user_id']
    session_token = generate_session_token(user_id)
    session_data = Session(user_id=user_id, expires_at=datetime.utcnow() + timedelta(days=1))
    db.session.add(session_data)
    db.session.commit()
    return {'session_token': session_token}

# Flask route for validating existing sessions
@app.route('/validate-session', methods=['POST'])
def validate_session():
    session_token = request.form['session_token']
    if not validate_session(session_token):
        return 'Invalid or expired session', 401

    # Update the session expiration time
    session_data = Session.query.get(session_token)
    session_data.expires_at = datetime.utcnow() + timedelta(days=1)
    db.session.commit()

    return {'message': 'Session validated'}

# Flask route for deleting sessions
@app.route('/logout', methods=['POST'])
def delete_session():
    session_token = request.form['session_token']
    Session.query.get(session_token).delete()
    db.session.commit()
    return {'message': 'Session deleted'}
