package com.example.backgroundservice;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionHandler;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.collect.Maps;

public class BackgroundService {
    private static final Logger LOGGER = LoggerFactory.getLogger(BackgroundService.class);
    private final ExecutorService executorService;
    private final LoadingCache<String, Adapter> adapterCache;
    private final LoadingCache<String, DataSource> dataSourceCache;

    public BackgroundService() {
        this.executorService = Executors.newCachedThreadPool(
                new RejectedExecutionHandler() {
                    @Override
                    public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                        LOGGER.warn("Rejected execution: {}", r);
                    }
                });
        this.adapterCache = CacheBuilder.newBuilder()
                .maximumSize(10000)
                .build(CacheLoader.from(Adapter::load));
        this.dataSourceCache = CacheBuilder.newBuilder()
                .maximumSize(10000)
                .build(CacheLoader.from(DataSource::load));
    }

    public void start() {
        executorService.submit(() -> {
            while (true) {
                try {
                    updateDataSources();
                    Thread.sleep(1000); // adjust the sleep duration as needed
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    private void updateDataSources() {
        Map<String, DataSource> dataSources = Maps.newHashMap();

        try {
            adapterCache.asMap().forEach((adapterId, adapter) -> {
                adapter.update(dataSources);
                dataSources.putAll(adapter.getUpdatedData());
            });

            dataSources.forEach((dataSourceId, dataSource) -> {
                executorService.submit(() -> {
                    try {
                        dataSource.process();
                    } catch (Exception e) {
                        LOGGER.error("Error processing {}: {}", dataSourceId, e.getMessage(), e);
                    }
                });
            });
        } catch (Exception e) {
            LOGGER.error("Error updating data sources: {}", e.getMessage(), e);
        }
    }

    public static class Adapter {
        private final String id;
        private final LoadingCache<String, DataSource> dataSources;

        public Adapter(String id, LoadingCache<String, DataSource> dataSources) {
            this.id = id;
            this.dataSources = dataSources;
        }

        public void update(Map<String, DataSource> dataSources) throws Exception {
            // implement adapter-specific logic for updating data sources
        }

        public Map<String, DataSource> getUpdatedData() {
            return Maps.newHashMap();
        }
    }

    public static class DataSource {
        private final String id;

        public DataSource(String id) {
            this.id = id;
        }

        public void process() throws Exception {
            // implement data source-specific logic for processing updates
        }
    }
}
