CREATE PROCEDURE sp_GetEmployeeInfo
    @supervisorID INT,
    @startDate DATE,
    @endDate DATE
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        -- Caching frequently accessed data to improve performance
        DECLARE @cachedSupervisors TABLE (id INT, name VARCHAR(50));
        IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'supervisor_cache')
            CREATE TABLE supervisor_cache (id INT, name VARCHAR(50));

        MERGE supervisor_cache AS target
        USING (
            SELECT id, name
            FROM [HR_Sys].dbo.employees
            WHERE is_supervisor = 1
        ) AS source
        ON target.id = source.id
        WHEN MATCHED THEN
            UPDATE SET target.name = source.name
        WHEN NOT MATCHED BY TARGET THEN
            INSERT (id, name)
            VALUES (source.id, source.name);

        -- Retrieving detailed employee information based on supervisor ID, start date, and end date
        SELECT e.id, e.name, c.city, a.address, d.department, s.salary
        FROM [HR_Sys].dbo.employees AS e
        INNER JOIN supervisor_cache AS sc ON e.supervisor_id = sc.id AND sc.name = @supervisorID
        INNER JOIN cities AS c ON e.city_id = c.id
        INNER JOIN addresses AS a ON e.address_id = a.id
        INNER JOIN departments AS d ON e.department_id = d.id
        INNER JOIN salaries AS s ON e.salary_id = s.id
        WHERE e.hire_date BETWEEN @startDate AND @endDate
        ORDER BY e.name;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000), @ErrorSeverity INT;
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @ErrorSeverity = ERROR_SEVERITY();

        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        RAISERROR (@ErrorMessage, @ErrorSeverity, 1);
    END CATCH;
END;

