['Here is the C-based module for managing a dynamically expanding linked list of states derived from a finite state automaton (FSA), integrated with an external database for persistence:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a state in the FSA
typedef struct State {
    int id;
    char* name;
    struct State* next;
} State;

// Define the structure for the linked list of states
typedef struct States {
    State* head;
    pthread_mutex_t lock;
} States;

// Function to create a new state
State* createState(int id, char* name) {
    State* state = (State*) malloc(sizeof(State));
    if (!state) return NULL;
    state->id = id;
    state->name = strdup(name);
    state->next = NULL;
    return state;
}

// Function to add a new state to the linked list
void addState(States* states, State* state) {
    pthread_mutex_lock(&states->lock);
    if (!states->head) states->head = state;
    else {
        State* current = states->head;
        while (current->next) current = current->next;
        current->next = state;
    }
    pthread_mutex_unlock(&states->lock);
}

// Function to remove a state from the linked list
void removeState(States* states, int id) {
    pthread_mutex_lock(&states->lock);
    State* current = states->head;
    State* previous = NULL;
    while (current && current->id != id) {
        previous = current;
        current = current->next;
    }
    if (!current) pthread_mutex_unlock(&states->lock); // Not found
    else {
        if (previous) previous->next = current->next;
        else states->head = current->next;
        free(current->name);
        free(current);
    }
    pthread_mutex_unlock(&states->lock);
}

// Function to export the linked list of states in JSON format
void exportStates(States* states, FILE* file) {
    fprintf(file, "[");
    State* current = states->head;
    while (current) {
        fprintf(file, "{\"id\": %d, \"name\": \"%s\"},", current->id, current->name);
        current = current->next;
    }
    if (states->head) {
        fprintf(file, "]");
    } else {
        fprintf(file, "null");
    }
}

// Function to import the linked list of states from JSON format
States* importStates(FILE* file) {
    States* states = (States*) malloc(sizeof(States));
    states->head = NULL;
    pthread_mutex_init(&states->lock, NULL);
    char line[1024];
    int stateCount = 0;
    while (fgets(line, sizeof(line), file)) {
        if (!strncasecmp(line, "{\"id\": ", 9)) {
            char* end = strchr(line + 10, ',');
            *end = '\0';
            states->head = createState(atoi(line + 11), line + 12);
            stateCount++;
        }
    }
    return states;
}

// Function to integrate with the external REST API for database operations
int dbOperation(int id) {
    // Implement API call logic here
    printf("Database operation performed for state %d\n", id);
    return 0; // Return success or failure code
}

int main() {
    States* states = (States*) malloc(sizeof(States));
    pthread_mutex_init(&states->lock, NULL);

    // Add some sample states
    addState(states, createState(1, "State 1"));
    addState(states, createState(2, "State 2"));
    addState(states, createState(3, "State 3"));

    // Export the linked list of states in JSON format
    FILE* file = fopen("states.json", "w");
    exportStates(states, file);
    fclose(file);

    // Import the linked list of states from JSON format
    file = fopen("states.json", "r");
    States* importedStates = importStates(file);
    fclose(file);

    // Remove a state from the linked list
    removeState(states, 2);

    // Perform some database operations using the external REST API
    dbOperation(1);
    dbOperation(3);

    return 0;
}

