#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>
#include <queue>
#include <chrono>

std::map<std::string, struct Attack> attacks;
std::mutex mtx;
std::condition_variable cv;
bool attackAvailable = true;

struct Attack {
    std::string name;
    int cooldownTime;
};

void executeRandomAttack(const std::string& characterName) {
    if (!attackAvailable) {
        std::this_thread::sleep_for(std::chrono::seconds(9));
        return;
    }

    std::unique_lock<std::mutex> lock(mtx);

    cv.wait(lock, [&] { return attackAvailable; });

    // Fetch random available attacks
    std::priority_queue<Attack*, std::vector<Attack*>> priorityQueue;

    for (const auto& [attackName, attack] : attacks) {
        if (attack.cooldownTime <= 0) {
            priorityQueue.push(&attack);
        }
    }

    if (priorityQueue.empty()) {
        // No available attacks
        return;
    }

    Attack* selectedAttack = priorityQueue.top();
    priorityQueue.pop();

    lock.unlock();

    // Execute the attack
    std::cout << characterName << " uses " << selectedAttack->name << ".\n";

    // Update cooldown time for the selected attack
    std::this_thread::sleep_for(std::chrono::seconds(selectedAttack->cooldownTime));
    selectedAttack->cooldownTime = 0;

    lock.lock();
    cv.notify_one();

    // Release the lock to allow other threads to access shared resources
    lock.unlock();
}

void updateAttackCooldown(const std::string& attackName) {
    auto it = attacks.find(attackName);
    if (it != attacks.end()) {
        it->second.cooldownTime -= 1;
    }
}

int main() {
    // Initialize the attack database
    attacks["Attack1"] = { "Attack1", 9 };
    attacks["Attack2"] = { "Attack2", 12 };
    attacks["Attack3"] = { "Attack3", 6 };

    // Start a separate thread to simulate attacks
    std::thread t([&] {
        for (int i = 0; i < 10; ++i) {
            executeRandomAttack("Character1");
            updateAttackCooldown("Attack1");
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
    });

    // Main thread executes other tasks...
    return 0;
}

