typedef enum {
    ZIP,
    TAR,
    GZIP,
    UNKNOWN_FORMAT
} CompressionFormat;

typedef struct {
    char* path;
    CompressionFormat format;
    int size;
} ArchiveInfo;

void loadArchive(char* filePath, void (*callback)(ArchiveInfo*)) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        printf("Error opening file: %s\n", filePath);
        return;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    ArchiveInfo info;
    info.path = filePath;

    // Determine compression format based on file headers or metadata
    if (fileSize < 100) { // assuming ZIP/TAR files are smaller than this
        info.format = ZIP;
    } else {
        info.format = GZIP; // assuming most archives are GZip
    }

    size_t readBytes = fread(info.path, 1, fileSize, file);
    fclose(file);

    if (readBytes != fileSize) {
        printf("Error reading file: %s\n", filePath);
        return;
    }

    callback(info);
}

void processArchive(ArchiveInfo info) {
    // Process the archive contents here
    printf("Processing archive: %s\n", info.path);
}

int main() {
    loadArchive("path/to/your/archive.zip", &processArchive);

    return 0;
}
