char* truncAndLog(char* input, int sizeLimit, int* maxLength, void (*logError)(const char*)) {
    if (input == NULL || strlen(input) <= *maxLength) {
        return strdup(input);
    }

    char* output = (char*)malloc(strlen(input) + 4); // +4 for ellipsis and null terminator
    int i;
    for (i = 0; i < sizeLimit && input[i]; i++) {
        *(output + i) = input[i];
    }
    if (i == sizeLimit || !input[i]) {
        strcpy(output + i, "...");
    } else {
        *maxLength = sizeLimit;
        logError("String truncated due to exceeding maximum allowed length.");
    }
    output[strlen(input < sizeLimit ? input : output) + strlen(output > input ? output : "...")] = '\0';
    return output;
}
