#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_THREADS 1000
#define MAX_COMMANDS 10000
#define RETRIES 5

typedef struct {
    pid_t pid;
    char *command;
} command_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
command_t commands[MAX_COMMANDS];
int command_count = 0;
int running_commands = 0;
int retries = RETRIES;

void sighandler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pthread_mutex_lock(&lock);
    for (int i = 0; i < command_count; i++) {
        if (kill(commands[i].pid, SIGTERM)) {
            perror("Error killing process");
        }
    }
    pthread_mutex_unlock(&lock);
}

void* execute_command(void* arg) {
    command_t* cmd = (command_t*)arg;
    pid_t pid = fork();
    if (pid < 0) {
        perror("Fork failed");
        return NULL;
    } else if (pid == 0) {
        // Child process
        if (execvp(cmd->command, NULL)) {
            perror("Error executing command");
            exit(1);
        }
    } else {
        // Parent process
        commands[command_count].pid = pid;
        commands[command_count].command = cmd->command;
        command_count++;
        running_commands++;
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    int i;

    for (i = 0; i < MAX_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, execute_command, NULL)) {
            perror("Error creating thread");
            return 1;
        }
    }

    // Wait for all commands to finish
    for (int j = 0; j < command_count; j++) {
        int status;
        waitpid(commands[j].pid, &status, 0);
        if (WEXITSTATUS(status)) {
            printf("Command '%s' failed with exit code %d\n", commands[j].command, WEXITSTATUS(status));
        }
    }

    return 0;
}
