        private readonly object _syncRoot = new();
        private readonly Monitor _monitor = new();

        public void AddApplication(string directoryPath)
        {
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException("The specified path cannot be found.");

            var configFilePath = Path.Combine(directoryPath, "web.config");

            if (!File.Exists(configFilePath))
                throw new FileNotFoundException("No web.config file exists in the specified directory.", configFilePath);

            try
            {
                using (var configFileStream = File.OpenRead(configFilePath))
                {
                    var config = ConfigurationManager.OpenWebConfiguration(configFileStream);
                    if (!config.HasFile)
                        throw new ConfigurationErrorsException("Invalid configuration file.");

                    _applications.Add(directoryPath, new Application(directoryPath, config));
                }
            }
            catch (Exception ex)
            {
                // Log the error and return null
                _monitor.Enter();
                try
                {
                    Console.WriteLine($"Error adding application: {ex.Message}");
                    _monitor.Exit();
                }
                finally
                {
                    Monitor.Pulse(_monitor);
                }
            }
        }

        public void RemoveApplication(string directoryPath)
        {
            if (!_applications.ContainsKey(directoryPath))
                throw new KeyNotFoundException("The specified application does not exist.");

            _applications.Remove(directoryPath);

