#define MAX_LOG_LEVEL 5

typedef struct {
    char api_key[MAX_API_KEY_LENGTH];
    int log_level;
} config_t;

// Function to load configuration from a JSON file
int loadConfiguration(const char *config_file, config_t *config) {
    json_object *config_json = json_object_from_file(config_file);
    if (!config_json) {
        printf("Error loading configuration: %s\n", strerror(errno));
        return -1;
    }

    // Get API key from the JSON object
    json_object *api_key_obj = json_object_object_get(config_json, "api_key");
    if (api_key_obj && api_key_obj->type == json_type_string) {
        strncpy(config->api_key, api_key_obj->value->str, MAX_API_KEY_LENGTH);
        config->api_key[MAX_API_KEY_LENGTH - 1] = '\0';
    } else {
        printf("Error: API key is missing or malformed.\n");
        return -2;
    }

    // Get log level from the JSON object
    json_object *log_level_obj = json_object_object_get(config_json, "log_level");
    if (log_level_obj && log_level_obj->type == json_type_int) {
        config->log_level = log_level_obj->value->int_value;
    } else {
        printf("Error: Log level is missing or malformed.\n");
        return -3;
    }

    // Free the JSON object
    json_object_free(config_json);
    return 0;
}

// Function to validate configuration
int validateConfiguration(config_t *config) {
    if (strlen(config->api_key) == 0 || strlen(config->api_key) > MAX_API_KEY_LENGTH) {
        printf("Error: API key is invalid.\n");
        return -1;
    }

    // Validate log level
    if (config->log_level < 0 || config->log_level > MAX_LOG_LEVEL) {
        printf("Warning: Log level out of range. Adjusting to %d.\n", MAX_LOG_LEVEL);
        config->log_level = MAX_LOG_LEVEL;
    }
}

// Function to handle errors and log details
void reportError(const char *error_message, int error_code) {
    // Implement logging mechanism here
    printf("Error: %s (Code %d)\n", error_message, error_code);
}
