#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#include "json-parser/json-parser.h"
#include "log/log.h"

#define MAX_REQUESTS 100
#define MAX_TOKEN_LENGTH 1024

typedef struct {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
} Token;

void validate_token(const char* json) {
    JSONParser* parser = json_parser_new();
    JSONNode* root = json_parser_parse(parser, json);

    if (!root || !json_node_is_object(root)) {
        log_error("Invalid JSON: %s", json);
        return;
    }

    Token token = {0};
    JSONNode* access_token_node = json_node_object_get(root, "access_token");
    if (access_token_node && json_node_string_get(access_token_node) != NULL) {
        token.access_token = strdup(json_node_string_get(access_token_node));
    } else {
        log_error("Missing or invalid 'access_token'");
        return;
    }

    JSONNode* expires_in_node = json_node_object_get(root, "expires_in");
    if (expires_in_node && json_node_number_get(expires_in_node) > 0) {
        token.expires_in = json_node_number_get(expires_in_node);
    } else {
        log_error("Invalid or missing 'expires_in'");
        return;
    }

    JSONNode* token_type_node = json_node_object_get(root, "token_type");
    if (token_type_node && json_node_string_get(token_type_node) != NULL) {
        char* token_type = strdup(json_node_string_get(token_type_node));
        if (strcasecmp(token_type, "bearer") == 0) {
            token.token_type = token_type;
        } else {
            log_error("Invalid 'token_type' ('Bearer' expected)");
            return;
        }
    } else {
        log_error("Missing or invalid 'token_type'");
        return;
    }

    JSONNode* refresh_token_node = json_node_object_get(root, "refresh_token");
    if (refresh_token_node && json_node_string_get(refresh_token_node) != NULL) {
        token.refresh_token = strdup(json_node_string_get(refresh_token_node));
    } else {
        log_error("Missing or invalid 'refresh_token'");
        return;
    }

    // Perform additional validation rules based on the environment variable
    if (getenv("VALIDATION_RULES")) {
        // Implement custom validation logic using JSONNode API
    }
}

int main() {
    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    if (bind(listen_fd, (struct sockaddr*) &addr, sizeof(addr)) < 0) {
        log_error("Failed to bind socket: %s", strerror(errno));
        return -1;
    }

    listen(listen_fd, MAX_REQUESTS);

    while (1) {
        int client_fd = accept(listen_fd, NULL, NULL);
        if (client_fd < 0) {
            log_error("Failed to accept connection: %s", strerror(errno));
            continue;
        }

        char buffer[MAX_TOKEN_LENGTH];
        read(client_fd, buffer, MAX_TOKEN_LENGTH);

        validate_token(buffer);
    }

    return 0;
}
