using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace Md5HashGeneratorService
{
    public class Md5HashGenerator : IDisposable
    {
        private readonly IExternalApi _externalApi;
        private readonly ILogger _logger;
        private readonly int _timeoutInMilliseconds = 10000; // default timeout

        public Md5HashGenerator(IExternalApi externalApi, ILogger logger)
        {
            _externalApi = externalApi;
            _logger = logger;
        }

        public async Task<string> GenerateMd5HashAsync(string input)
        {
            if (string.IsNullOrEmpty(input) || input.Length > 1024)
            {
                throw new ArgumentException("Input cannot be null, empty or exceed 1024 characters.");
            }

            try
            {
                using var md5 = MD5.Create();
                using var stream = new MemoryStream(Encoding.UTF8.GetBytes(input));
                var hash = md5.ComputeHash(stream);

                await StoreHashAsync(hash, input);
            }
            catch (Exception ex)
            {
                await LogErrorAndRetryAsync(ex);
            }

            return null;
        }

        private async Task StoreHashAsync(byte[] hash, string input)
        {
            try
            {
                await _externalApi.StoreHashAsync(input, hash);
            }
            catch (Exception ex)
            {
                await LogErrorAndRetryAsync(ex);
            }
        }

        private async Task LogErrorAndRetryAsync(Exception ex)
        {
            _logger.LogError(ex.Message, ex);

            // Implement retry policy with exponential backoff
            for (int i = 0; i < 5; i++)
            {
                try
                {
                    await StoreHashAsync(null, null);
                    return;
                }
                catch (Exception innerEx)
                {
                    _logger.LogError(innerEx.Message, innerEx);

                    // Wait before retrying
                    await Task.Delay(TimeSpan.FromMilliseconds(Math.Pow(2, i) * 500));
                }
            }

            // If all retries fail, log a final error and rethrow the exception
            _logger.LogError("All retries failed.");
            throw;
        }

        public void Dispose()
        {
            // Implement proper cleanup of temporary resources post-operation
        }
    }
}
