public static object DecryptAndDeserialize(byte[] ciphertext, string key, byte[] iv)
{
    try
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = Encoding.ASCII.GetBytes(key);
            aes.IV = iv;
            ICryptoTransform decryptor = aes.CreateDecryptor();

            using (MemoryStream ms = new MemoryStream(ciphertext))
            {
                CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

                byte[] plaintextBytes = new byte[ciphertext.Length];
                int bytesRead = cs.Read(plaintextBytes, 0, plaintextBytes.Length);
                cs.Close();
                ms.Close();

                using (MemoryStream ms2 = new MemoryStream())
                {
                    BinaryWriter bw = new BinaryWriter(ms2);
                    bw.Write(plaintextBytes.Take(bytesRead).ToArray());
                    bw.Flush();
                    bw.Close();
                    ms2.Close();

                    return ms2.ToArray();
                }
            }
        }
    }
    catch (CryptographicException ex)
    {
        _logger.LogError(ex, "Failed to decrypt data");
        return "Error: Decryption failed";
    }
    catch (FormatException ex)
    {
        _logger.LogError(ex, "Failed to deserialize data");
        return "Error: Deserialization failed";
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "Unknown error occurred during decryption and deserialization");
        return "Error: Unknown error occurred";
    }
