    private ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

    public interface DeserializationCallback<T> {
        void onDeserialized(T obj) throws Exception;
    }

    public <T> T deserialize(byte[] bytes, Class<T> clazz, DeserializationCallback<T> callback) {
        try (InputStream is = new ByteArrayInputStream(bytes)) {
            return deserialize(is, clazz, callback);
        } catch (IOException e) {
            // Log error and propagate it
            System.out.println("Error deserializing: " + e.getMessage());
            return null;
        }
