    private <T> T deserialize(InputStream is, Class<T> clazz, DeserializationCallback<T> callback) throws IOException, ClassNotFoundException {
        try (is) {
            byte[] metadataBytes = getMetadata(is);
            String serializationFormatVersion = readSerializationFormatVersion(metadataBytes);
            Class<? extends T> deserializationClazz = loadDeserializationClass(serializationFormatVersion);

            // Deserialize object
            Object obj = deserializeObject(is, deserializationClazz);

            // Check if the deserialized object implements the specified interface
            if (!clazz.isAssignableFrom(obj.getClass())) {
                callback.onDeserialized(null);
                return null; // Return null to indicate non-compliance with the interface
            }

            callback.onDeserialized((T) obj);
            return (T) obj;
        } catch (InvocationTargetException | ExecutionException e) {
            System.out.println("Error deserializing: " + e.getMessage());
            return null;
        }
