const fs = require('fs');
const crypto = require('crypto');
const json2yaml = require('json2yaml');
const yaml = require('js-yaml');
const axios = require('axios');

class ConfigurationManager {
  constructor(configFile, externalServiceUrl) {
    this.configFile = configFile;
    this.externalServiceUrl = externalServiceUrl;
  }

  async updateConfig(newConfig) {
    try {
      const response = await axios.put(`${this.externalServiceUrl}/config`, newConfig);
      if (response.status === 200) {
        console.log('Configuration updated successfully');
      } else {
        throw new Error(`Failed to update configuration: ${response.statusText}`);
      }
    } catch (error) {
      console.error(`Error updating configuration: ${error.message}`);
    }

    try {
      const encryptedPassword = await this.encryptPassword(newConfig.password);
      fs.writeFileSync(this.configFile, yaml.safeDump({ ...newConfig, password: encryptedPassword }));
    } catch (error) {
      console.error(`Error writing config file: ${error.message}`);
    }
  }

  async encryptPassword(password) {
    try {
      const iv = crypto.randomBytes(16);
      const cipher = crypto.createCipheriv('aes-256-cbc', process.env.ENCRYPTION_KEY, iv);
      const encryptedPassword = Buffer.concat([cipher.update(password), cipher.final()]).toString('base64');
      return `${Buffer.from(iv).toString('hex')}.${encryptedPassword}`;
    } catch (error) {
      console.error(`Error encrypting password: ${error.message}`);
      throw error;
    }
  }

  async validateConfig(config) {
    try {
      const placeholderRegex = /\$\{([a-zA-Z_][a-zA-Z0-9_]*)\}/g;
      if (!placeholderRegex.test(config)) {
        throw new Error('Invalid configuration format');
      }
    } catch (error) {
      console.error(`Error validating config: ${error.message}`);
    }
  }

  async readConfig() {
    try {
      const fileContent = fs.readFileSync(this.configFile, 'utf8');
      return yaml.safeLoad(fileContent);
    } catch (error) {
      console.error(`Error reading config file: ${error.message}`);
      throw error;
    }
  }
}

