use std::fs::{self, DirEntry};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::error::Error;
use std::collections::HashSet;

pub struct Workspace {
    dir: Arc<Mutex<PathBuf>>,
    config: Arc<Mutex<Config>>,
    lock: Arc<Mutex<HashSet<String>>>,
}

impl Workspace {
    pub fn new() -> Self {
        let dir = Arc::new(Mutex::new(PathBuf::from("/tmp")));
        let config = Arc::new(Mutex::new(Config::default()));
        let lock = Arc::new(Mutex::new(HashSet::new()));

        Self { dir, config, lock }
    }

    pub fn create(&self) -> Result<(), Box<dyn Error>> {
        let path = self.dir.lock().clone();
        fs::create_dir_all(path.as_path())?;

        Ok(())
    }

    pub fn delete(&self) -> Result<(), Box<dyn Error>> {
        let path = self.dir.lock().clone();
        fs::remove_dir_all(path.as_path())?;

        Ok(())
    }

    pub fn set_config(&mut self, config: &Config) -> Result<(), Box<dyn Error>> {
        *self.config.lock() = config.clone();

        Ok(())
    }
}

pub struct Config {
    base_dir: PathBuf,
    // Other configuration options...
}

impl Default for Config {
    fn default() -> Self {
        Config {
            base_dir: PathBuf::from("/tmp"),
            // Default values for other configuration options...
        }
    }
}
