from functools import wraps

class RealtimeJSONProcessor:
    def __init__(self):
        self.registry = defaultdict(dict)
        self.lock = threading.Lock()

    def add_factory(self, id: str, factory_func):
        with self.lock:
            self.registry[id] = {"factory": factory_func}

    def get_processor(self, json_data):
        try:
            processor_id = json_data["processor"]
            return self.registry[processor_id]["factory"](json_data)
        except KeyError:
            raise ValueError("Invalid JSON data")

