['```
function validate_oauth2_access_token($access_token_json) {
    $token_data = json_decode($access_token_json, true);

    if (!isset($token_data['access_token'])) {
        error_log("OAuth2 access token missing 'access_token' field");
        return false;
    }

    if (strlen($token_data['access_token']) < 1) {
        error_log("OAuth2 access token 'access_token' field is empty");
        return false;
    }

    if (!isset($token_data['expires_in'])) {
        error_log("OAuth2 access token missing 'expires_in' field");
        return false;
    }

    if (!is_int($token_data['expires_in']) || $token_data['expires_in'] <= 0) {
        error_log("OAuth2 access token 'expires_in' field is invalid or zero");
        return false;
    }

    if (!isset($token_data['token_type'])) {
        error_log("OAuth2 access token missing 'token_type' field");
        return false;
    }

    if (strtolower($token_data['token_type']) !== 'bearer') {
        error_log("OAuth2 access token 'token_type' is not 'Bearer'");
        return false;
    }

    // Optional fields
    if (isset($token_data['refresh_token'])) {
        if (!strlen($token_data['refresh_token'])) {
            error_log("OAuth2 access token 'refresh_token' field is empty");
            return false;
        }
    } else {
        $token_data += ['refresh_token' => ''];
    }

    // All checks pass
    return true;
}
