#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* data;
    size_t length;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0};

void logError(const char* message) {
    printf("Error: %s\n", message);
}

char* truncateAndLog(char* input, int sizeLimit, int* maxLength, void (*logError)(const char*)) {
    if (input == NULL || strlen(input) <= sizeLimit) {
        return input;
    }

    size_t maxLengthBytes = *maxLength;

    char* truncatedInput = memoryPoolAllocate(sizeLimit + 4); // allocate space for truncated string and ellipsis
    char* tempStr = truncatedInput; // temporary pointer for writing

    if (strlen(input) > maxLengthBytes) {
        logError("String length exceeds maximum allowed length.");
    }

    size_t i;
    for (i = 0; i < sizeLimit && input[i] != '\0'; i++) {
        *tempStr++ = input[i];
    }
    *tempStr++ = '.';
    *tempStr++ = '.';
    *tempStr++ = ' ';
    tempStr[0] = '\0';

    if (strlen(input) > maxLengthBytes) {
        logError("Memory allocation failure.");
    }

    return truncatedInput;
}

char* memoryPoolAllocate(size_t size) {
    char* block = malloc(size);
    if (block == NULL) {
        logError("Memory allocation failed.");
        exit(1); // handle error and terminate program
    }
    return block;
}
