```php
<?php

use GuzzleHttp\Client;
use League\OAuth2\Client\Provider\AbstractProvider;
use League\OAuth2\Client\Provider\Facebook;
use League\OAuth2\Client\Provider\Google;
use League\OAuth2\Client\Provider\OpenIdConnect;

require 'vendor/autoload.php';

class SessionManager {
    private $sessionStore;
    private $providerConfig;

    public function __construct($sessionStore, array $providerConfig) {
        $this->sessionStore = $sessionStore;
        $this->providerConfig = $providerConfig;
    }

    public function createSession(array $data): ?string {
        // Determine the external authentication provider
        $provider = $this->getProvider();

        // Create a session with the chosen provider
        try {
            $response = $provider->getAccessToken($data);
            if (isset($response['access_token'])) {
                // Store the session token
                $token = $response['access_token'];
                $this->sessionStore->setToken($token, $data);

                return $token;
            }
        } catch (\Exception $e) {
            // Handle errors from the provider
            error_log('Error creating session: ' . $e->getMessage());
            return null;
        }
    }

    public function validateSession(string $token): bool {
        try {
            // Validate the session with the chosen provider
            $provider = $this->getProvider();
            $response = $provider->validateToken($token);

            if ($response) {
                return true;
            }
        } catch (\Exception $e) {
            // Handle errors from the provider
            error_log('Error validating session: ' . $e->getMessage());
        }

        return false;
    }

    public function revokeSession(string $token): void {
        try {
            // Revoke the session with the chosen provider
            $provider = $this->getProvider();
            $provider->revokeToken($token);
        } catch (\Exception $e) {
            // Handle errors from the provider
            error_log('Error revoking session: ' . $e->getMessage());
        }
    }

    private function getProvider(): AbstractProvider {
        // Determine which provider to use based on configuration
        // or some other logic...
        if ($this->providerConfig['facebook']) {
            return new Facebook($this->providerConfig['facebook_client_id'], $this->providerConfig['facebook_client_secret']);
        } elseif ($this->providerConfig['google']) {
            return new Google($this->providerConfig['google_client_id'], $this->providerConfig['google_client_secret']);
        } else {
            return new OpenIdConnect($this->providerConfig['openid_connect_client_id'], $this->providerConfig['openid_connect_client_secret']);
        }
    }
}

// Example usage:
$sessionManager = new SessionManager(new \SessionStore(), array(
    'facebook' => [
        'client_id' => 'YOUR_FACEBOOK_CLIENT_ID',
        'client_secret' => 'YOUR_FACEBOOK_CLIENT_SECRET'
    ],
    'google' => [
        'client_id' => 'YOUR_GOOGLE_CLIENT_ID',
        'client_secret' => 'YOUR_GOOGLE_CLIENT_SECRET'
    ]
));

$token = $sessionManager->createSession(['username' => 'john', 'email' => 'john@example.com']);
if ($token) {
    // Validate the session
    if ($sessionManager->validateSession($token)) {
        // Use the session...
    } else {
        // Session is invalid or expired, handle accordingly...
    }
} else {
    // Unable to create a session, handle accordingly...
}

// Revoke the session
$sessionManager->revokeSession($token);

```

