    if (input_fd < 0) {
        printf("Error opening input file.\n");
        return -1;
    }

    off_t offset = lseek(input_fd, 0, SEEK_END);
    char buffer[BUFFER_SIZE];
    int lines = 0;

    while (offset > 0) {
        ssize_t read_size = pread(input_fd, buffer, BUFFER_SIZE, offset-1);
        if (read_size < 0) {
            printf("Error reading file.\n");
            return -1;
        }

        char* line = strtok(buffer, "\n");
        while (line != NULL) {
            lines++;
            line = strtok(NULL, "\n");
        }

        offset -= read_size;
    }

    close(input_fd);

    printf("Total number of lines: %d\n", lines);
}

