CryptoAlgorithm* load_module(const char* filename) {
    // Load the dynamic library
    void* handle = dlopen(filename, RTLD_LAZY);
    if (!handle) {
        printf("Failed to load library: %s\n", dlerror());
        return NULL;
    }

    // Get the symbol for the algorithm list function
    void (*get_algorithms)(void*, CryptoAlgorithm**) = dlsym(handle, "get_algorithms");
    if (!get_algorithms) {
        printf("Failed to get algorithms function: %s\n", dlerror());
        dlclose(handle);
        return NULL;
    }

    // Call the algorithm list function
    int num_algorithms;
    CryptoAlgorithm* algorithms = (*get_algorithms)(handle, &num_algorithms);

    // Register each algorithm
    for (int i = 0; i < num_algorithms; i++) {
        algorithms[i].name = strdup(algorithms[i].name);
        // Add the function to a lookup table
