using System;
using System.Data.SqlClient;
using System.Threading.Tasks;

namespace DataAccessLayer
{
    public class DatabaseContext : IDisposable
    {
        private readonly SqlConnection _connection;
        private readonly SqlTransaction _transaction;

        public DatabaseContext(string connectionString)
        {
            _connection = new SqlConnection(connectionString);
            _connection.Open();
            _transaction = _connection.BeginTransaction();
        }

        public async Task<int> ExecuteAsync(string query, params SqlParameter[] parameters)
        {
            using (var command = new SqlCommand(query, _connection))
            {
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }
                return await command.ExecuteNonQueryAsync();
            }
        }

        public async Task<T> ExecuteScalarAsync<T>(string query, params SqlParameter[] parameters)
        {
            using (var command = new SqlCommand(query, _connection))
            {
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }
                return await (T)command.ExecuteScalarAsync();
            }
        }

        public async Task<T> ExecuteReaderAsync<T>(string query, params SqlParameter[] parameters)
        {
            using (var command = new SqlCommand(query, _connection))
            {
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }
                using (var reader = await command.ExecuteReaderAsync())
                {
                    return await ReadDataAsync<T>(reader);
                }
            }
        }

        private async Task<T> ReadDataAsync<T>(SqlDataReader reader)
        {
            // implement logic to read data
            // for example, using Dapper
            var list = new List<T>();
            while (await reader.ReadAsync())
            {
                list.Add(reader.GetValues());
            }
            return list;
        }

        public void Dispose()
        {
            _transaction.Rollback();
            _connection.Close();
        }
    }
}
```']

