using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicConnectionPool
{
    public interface IDatabase
    {
        Task ExecuteQueryAsync(string query);
    }

    public class DatabaseConnection : IDatabase
    {
        private readonly string _connectionString;

        public DatabaseConnection(string connectionString)
        {
            _connectionString = connectionString;
        }

        public async Task ExecuteQueryAsync(string query)
        {
            // Your implementation to execute the query
            await Task.Delay(100);
        }
    }

    public class ConnectionPool : IDisposable
    {
        private readonly Dictionary<string, Queue<IDatabase>> _pools;
        private readonly SemaphoreSlim _semaphore;
        private readonly CancellationTokenSource _cts;

        public ConnectionPool(int capacity)
        {
            _pools = new Dictionary<string, Queue<IDatabase>>();
            _semaphore = new SemaphoreSlim(capacity);
            _cts = new CancellationTokenSource();
        }

        public async Task<IDatabase> GetConnectionAsync(string connectionString)
        {
            if (!_pools.TryGetValue(connectionString, out var queue))
                throw new Exception("No pool found");

            while (queue.Count == 0 || !await queue.TryTake(out var connection, TimeSpan.FromMilliseconds(500), _cts.Token))
            {
                await TryAcquireSemaphore();
                try
                {
                    // Acquire a new connection from the database
                    queue.Enqueue(new DatabaseConnection(connectionString));
                }
                catch (Exception ex)
                {
                    // Log the exception and return null if acquiring a new connection fails
                    Console.WriteLine($"Error acquiring new connection: {ex.Message}");
                    return null;
                }
            }

            return connection;
        }

        private async Task TryAcquireSemaphore()
        {
            while (_semaphore.Wait(0))
                await Task.Delay(100);
        }

        public void Dispose()
        {
            _cts.Cancel();
            foreach (var pool in _pools.Values)
                pool.Clear();
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var connectionPool = new ConnectionPool(10);

            while (true)
            {
                try
                {
                    // Acquire a connection and execute a query
                    using (var connection = await connectionPool.GetConnectionAsync("mydb"))
                    {
                        await connection.ExecuteQueryAsync("SELECT * FROM mytable");
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error: {ex.Message}");
                }

                await Task.Delay(1000);
            }
        }
    }
}
