        {
            _logger = logger;
            _xmlDoc = xmlDoc;
            _xpathNav = xmlDoc.CreateNavigator();
        }

        public async Task ProcessXmlAsync()
        {
            try
            {
                // Validate XML against dynamic schema using XPath
                await ValidateXmlAgainstSchema();

                // Stream XML content to process large files efficiently
                using (var reader = _xmlDoc.CreateReader())
                {
                    while (reader.Read())
                    {
                        if (reader.NodeType == XmlNodeType.Element)
                        {
                            var elementName = reader.Name;
                            var timestampAttr = reader.GetAttribute("timestamp");

                            // Validate and retrieve elements based on timestamp attributes
                            await ProcessElementAsync(elementName, timestampAttr);
