import java.io.*;
import java.util.*;
import java.nio.file.Files;
import java.nio.file.Paths;

public class StateService {
    private static final String STATE_FILE_NAME = "state.dat";
    private static final int MAX_STALE_THRESHOLD_MINS = 30; // 30 minutes
    private static final long REFRESH_INTERVAL_MINS = 5; // 5 minutes

    private Map<String, State> stateCache;
    private Map<String, Long> stateTimestamps;
    private ExecutorService executor;

    public StateService() {
        this.stateCache = new ConcurrentHashMap<>();
        this.stateTimestamps = new HashMap<>();
        this.executor = Executors.newCachedThreadPool();
    }

    public void start() {
        new Thread(() -> {
            while (true) {
                refreshState();
                try {
                    Thread.sleep(REFRESH_INTERVAL_MINS * 60 * 1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
        }).start();

        new Thread(() -> {
            while (true) {
                checkAndFlushStaleStates();
                try {
                    Thread.sleep(MAX_STALE_THRESHOLD_MINS * 60 * 1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
        }).start();
    }

    private void refreshState() {
        for (Map.Entry<String, State> entry : stateCache.entrySet()) {
            String key = entry.getKey();
            State state = entry.getValue();

            if (!state.isValid()) {
                continue; // Skip invalid states
            }

            long timestamp = System.currentTimeMillis();
            if (timestamp - state.getTimestamp() > REFRESH_INTERVAL_MINS * 60 * 1000) {
                stateCache.remove(key);
                stateTimestamps.remove(key);
            } else {
                try {
                    byte[] data = Files.readAllBytes(Paths.get(state.getFile()));
                    State newState = deserializeState(data);
                    if (newState != null && !state.equals(newState)) {
                        stateCache.put(key, newState);
                        stateTimestamps.put(key, timestamp);
                    }
                } catch (IOException e) {
                    logError("Failed to read state file", e);
                } catch (Exception e) {
                    logError("Deserialization failed", e);
                }
            }
        }

        executor.submit(() -> {
            try {
                List<String> staleKeys = new ArrayList<>();
                for (Map.Entry<String, Long> entry : stateTimestamps.entrySet()) {
                    String key = entry.getKey();
                    long timestamp = entry.getValue();
                    if (System.currentTimeMillis() - timestamp > MAX_STALE_THRESHOLD_MINS * 60 * 1000) {
                        staleKeys.add(key);
                    }
                }

                for (String key : staleKeys) {
                    stateCache.remove(key);
                    stateTimestamps.remove(key);
                }
            } catch (Exception e) {
                logError("Failed to check and flush stale states", e);
            }
        });
    }

    private State deserializeState(byte[] data) throws Exception {
        // Your deserialization logic goes here
    }

    private void checkAndFlushStaleStates() {
        executor.submit(() -> {
            try {
                // Your metadata store integration and stale state handling logic goes here
            } catch (Exception e) {
                logError("Failed to check and flush stale states", e);
            }
        });
    }

    public static void main(String[] args) {
        StateService service = new StateService();
        service.start();
    }

    private static void logError(String message, Throwable t) {
        // Your logging mechanism goes here
    }
}
