      for (const service of this.processingServices) {
        if (!data[service]) {
          continue;
        }
        const processedData = await processImage(data[service]);
        data[service] = processedData;
      }
    }
  }

  async pauseStreaming() {
    this.activeRequests = 0;
    for (const service of this.processingServices) {
      await fetch(`https://api.${service}.com/pauseThemeStreaming/${this.themeDirectory}`);
    }
  }

  async resumeStreaming() {
    this.activeRequests = 0;
    for (const service of this.processingServices) {
      await fetch(`https://api.${service}.com/resumeThemeStreaming/${this.themeDirectory}`);
    }
  }

  async switchService(themeName, newService) {
