use std::process;
use log::info;

fn measure_compilation_time_and_rss() -> i32 {
    let mut child = process::Command::new("rustc")
        .arg("-Zgenerate-pic")
        .arg("--crate-type=lib")
        .arg("example.rs")
        .spawn()
        .unwrap();

    let output = child.wait().unwrap();
    if !output.success() {
        info!("Compilation failed with exit code: {}", output.code());
        return output.code();
    }

    let rss = child.get_rss_memory_info().unwrap().rss;
    let compilation_time = child.get_compilation_time().unwrap().total_duration().as_millis();

    info!("Compilation time: {}ms, RSS: {} bytes", compilation_time, rss);

    0
}

fn main() {
    if let Err(e) = measure_compilation_time_and_rss() {
        eprintln!("Error: {}", e);
        process::exit(1);
    }
}
