struct UserAccount {
    id: u32,
    name: String,
    email: String,
    password: String,
}

impl UserAccount {
    fn new(id: u32, name: &str, email: &str, password: &str) -> Self {
        UserAccount { id, name: name.to_string(), email: email.to_string(), password: password.to_string() }
    }

    fn save(&self, file_path: &Path) {
        let mut file = File::create(file_path).unwrap();
        let writer = BufWriter::new(&mut file);
        writer.write_all(format!("{}:{}:{}\n", self.id, self.name, self.email).as_bytes()).unwrap();
        writer.write_all(self.password.as_bytes()).unwrap();
    }

    fn load(file_path: &Path) -> Option<Self> {
        let mut file = File::open(file_path).unwrap();
        let reader = BufReader::new(&mut file);
        for line in reader.lines() {
            let line = line.unwrap();
            if let Some(parts) = line.split_whitespace().collect::<Vec<_>>().as_slice() {
                if parts.len() >= 3 {
                    let id = parts[0].parse().unwrap();
                    let name = parts[1].to_string();
                    let email = parts[2].to_string();
                    // Load password
                    Some(UserAccount::new(id, &name, &email, /* Password */))
                } else {
                    None
                }
            } else {
                None
            }
        }
    }
}

