// Function to update clinic status and handle concurrent updates
void* updateClinicStatus(void* arg) {
    // Extract the clinic ID from the argument
    Clinic* clinic = (Clinic*)arg;

    // Initialize mutex lock and semaphore
    pthread_mutex_t mutex;
    pthread_semaphore_t semaphore;
    pthread_mutex_init(&mutex, NULL);
    pthread_semaphore_init(&semaphore, 1);

    try {
        // Fetch the latest clinic metadata from external API
        ApiResponse response = fetchClnicMetadata(clinic->id);
        if (response.status_code != 200) {
            // Handle API errors with exponential backoff
            int attempts = 0;
            while (attempts < 5 && response.status_code != 200) {
                sleep(pow(2, attempts));
                response = fetchClnicMetadata(clinic->id);
                attempts++;
            }
        }

        // Update the clinic status in local database
        if (response.status_code == 200) {
            updateClinicStatusInDatabase(clinic, response.message);

            // Log the last modified IP address and timestamp
            logLastModifiedIPandTimestamp();
        }
    } catch (const std::exception& e) {
        // Handle errors with detailed feedback
        fprintf(stderr, "Error updating clinic status: %s\n", e.what());
    }

    // Release mutex lock and semaphore
    pthread_mutex_destroy(&mutex);
    pthread_semaphore_destroy(&semaphore);

    return NULL;
}

int main() {
    // Create a thread pool to handle concurrent updates
    int numThreads = 10;
    pthread_t threads[numThreads];
    for (int i = 0; i < numThreads; i++) {
        Clinic* clinic = getClinicMetadata(i);
        pthread_create(&threads[i], NULL, updateClinicStatus, (void*)clinic);
    }

    // Wait for all threads to complete
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

