class Octree {
public:
    using Node = std::shared_ptr<Node>;

    Octree(size_t capacity, size_t pageSize) : 
        capacity_(capacity), pageSize_(pageSize),
        root_(std::make_shared<Node>(0, 0, 0)), 
        dirty_(false), lock_() {}

    void insert(const std::pair<int, int>& key, const void* data, size_t size) {
        auto node = root_.get();
        while (node->isLeaf()) {
            if (!insertRecursive(node, key, data, size)) {
                return; // failed to insert
            }
        }
    }

    void retrieve(const std::pair<int, int>& key, void* outData, size_t outSize) {
        auto node = root_.get();
        while (node->isLeaf()) {
            if (!retrieveRecursive(node, key, outData, outSize)) {
                return; // failed to retrieve
            }
        }
    }

    template<typename Callback>
    void registerCallback(Callback cb) {
        callback_ = cb;
    }

private:
    struct Node {
        Node(size_t x, size_t y, size_t z)
            : x_(x), y_(y), z_(z),
              children_(nullptr, nullptr, nullptr) {}

        bool isLeaf() const { return x_ == y_ && y_ == z_; }
        void setDirty(bool dirty) { dirty_ = dirty; }

        std::tuple<Node*, Node*, Node*> children_;
    };

    Octree(size_t capacity, size_t pageSize);

    void insertRecursive(Node* node, const std::pair<int, int>& key, const void* data, size_t size);
    bool retrieveRecursive(Node* node, const std::pair<int, int>& key, void* outData, size_t outSize);

    boost::unordered_map<void*, Node*> cache_;
    std::shared_ptr<Node> root_;
    mutable std::atomic<bool> dirty_;
    mutable std::mutex lock_;
};

