import ctypes
import time

octree_module = ctypes.CDLL('./octree.so')

def query_octree(octree, key, timeout):
    start_time = time.time()
    while True:
        try:
            data_ptr = octree_module.insert_or_query(key)
            if not data_ptr:
                raise Exception("Timeout reached")
            break
        except:
            pass
    end_time = time.time()
    if end_time - start_time > timeout:
        raise Exception("Timeout reached")

    return octree_module.get_data(data_ptr)

if __name__ == "__main__":
