typedef struct {
    int count;
    double weighted_sum;
} sliding_window_t;

sliding_window_t *sw_head = NULL;
sliding_window_t *sw_tail = NULL;

void add_transaction(double weight) {
    // Add transaction to sliding window
    sliding_window_t *new_sw = (sliding_window_t *)malloc(sizeof(sliding_window_t));
    new_sw->count = 1;
    new_sw->weighted_sum = weight;

    if (sw_head == NULL) {
        sw_head = new_sw;
        sw_tail = new_sw;
    } else {
        sw_tail->next = new_sw;
        sw_tail = new_sw;
    }
}

void process_transactions() {
