	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/go-redis/redis/v8"
)

var (
	// Config
	config = struct {
		APIs []struct {
			Name        string
			BaseURL     string
			AuthType    string
			APIVersion  int
			SchemaEvolve bool
		}
	}{}

	// Redis Client
	client *redis.Client

	// Worker Pools
	workerPools = struct {
		CRM   chan context.Context
		ERP    chan context.Context
		Custom chan context.Context
		Legacy chan context.Context
		SaaS   chan context.Context
	}{
		CRM:   make(chan context.Context),
		ERP:    make(chan context.Context),
		Custom: make(chan context.Context),
		Legacy: make(chan context.Context),
		SaaS:   make(chan context.Context),
	}

	// Error Handler
	errHandler = log.New(log.Writer(), "ERROR", 0)

	// Request Throttler
	throttle = time.Now()
)

func main() {
	// Initialize Redis Client
	client = redis.NewClient(&redis.Options{
		Addr:     "localhost:6379",
		Password: "",
		DB:       0,
	})

	go func() {
		// Start worker pools
		for _, pool := range []chan context.Context{workerPools.CRM, workerPools.ERP, workerPools.Custom, workerPools.Legacy, workerPools.SaaS} {
			for i := 0; i < 5; i++ {
				pool <- context.Background()
			}
		}

		// Handle requests
		http.HandleFunc("/", middleware.RealIP())
		http.HandleFunc("/api/{app}", func(w http.ResponseWriter, r *http.Request) {
			app := chi.URLParam(r, "app")
			ctx := r.Context()

			switch app {
			case "CRM":
				// Handle CRM API request
				client.Get("crm:data").Do(ctx)
			case "ERP":
				// Handle ERP API request
				client.Get("erp:data").Do(ctx)
			default:
				http.Error(w, http.StatusText(404), 404)
			}
		})

		log.Fatal(http.ListenAndServe(":8080", nil))
	}()
}

func rateLimitHandler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if time.Since(throttle).Milliseconds() < 1000 {
			http.Error(w, http.StatusText(429), 429)
			return
		}
		throttle = time.Now()
		next.ServeHTTP(w, r)
	})
}

func errorHandler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if err := recover(); err != nil {
				errHandler.Println(err)
				http.Error(w, http.StatusText(500), 500)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func mainHandler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ctx := context.WithValue(r.Context(), "workerPool", workerPools[chi.URLParam(r, "app")])
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}
