#include <openssl/err.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void* cipher_init(const char* password, const unsigned char* salt) {
    // Define constants for PBKDF2 and AES-256-CBC
    const int pbkdf2_iterations_min = 10000;
    const int pbkdf2_iterations_max = 100000;

    // Generate random IV
    unsigned char iv[16];
    RAND_bytes(iv, sizeof(iv));

    // Derive encryption key using PBKDF2 with HMAC-SHA256
    unsigned char derived_key[32];
    int iterations = (rand() % (pbkdf2_iterations_max - pbkdf2_iterations_min)) + pbkdf2_iterations_min;
    PBKDF2_hmac_sha256(password, strlen(password), salt, 16, &derived_key[0], sizeof(derived_key), iterations);

    // Store derived key securely in memory
    void* key = malloc(sizeof(*key));
    memcpy(key, &derived_key[0], sizeof(derived_key));

    // Initialize AES-256-CBC cipher using derived key and IV
    EVP_CIPHER_CTX* ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, (const unsigned char*)key, sizeof(*key), iv);

    // Release resources
    free(key);
    EVP_CIPHER_CTX_free(ctx);

    return ctx;
}
