using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using OpenSSL.Core;
using OpenSSL.Aes;

namespace AsynchronousHttpEndpoint
{
    [ApiController]
    [Route("api/[controller]")]
    public class PageSectionController : ControllerBase
    {
        private readonly ILogger<PageSectionController> _logger;
        private readonly HttpClient _httpClient;
        private readonly AesCbcHelper _aesCbcHelper;

        public PageSectionController(ILogger<PageSectionController> logger, HttpClient httpClient, AesCbcHelper aesCbcHelper)
        {
            _logger = logger;
            _httpClient = httpClient;
            _aesCbcHelper = aesCbcHelper;
        }

        [HttpPost]
        [Route("update")]
        public async Task<IActionResult> UpdatePageSection([FromBody]UpdatePageSectionRequest request)
        {
            try
            {
                // Initialize AES-256-CBC cipher with provided password, setting variable IV and key lengths dynamically based on security requirements and performance constraints
                var key = _aesCbcHelper.GetEncryptionKey(request.Password);
                var iv = _aesCbcHelper.GetInitializationVector();

                // Encrypt the request using the initialized cipher
                var encryptedRequest = _aesCbcHelper.Encrypt(request.Content, key, iv);

                // Send the encrypted request to the external HTML sanitization service
                var response = await _httpClient.PostAsync("https://external-service.com/sanitize", new StringContent(encryptedRequest));

                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception($"Failed to sanitize page section: {response.StatusCode}");
                }

                // Decrypt the sanitized response using the initialized cipher
                var decryptedResponse = _aesCbcHelper.Decrypt(response.Content.ReadAsStringAsync().Result, key, iv);

                return Ok(decryptedResponse);
            }
            catch (Exception ex)
            {
                // Log detailed information about failed requests
                _logger.LogError(ex, "Failed to update page section");

                return StatusCode(500, "Internal Server Error");
            }
        }
    }

    public class UpdatePageSectionRequest
    {
        public string PageSectionId { get; set; }
        public string Content { get; set; }
        public string Password { get; set; }
    }
}

public class AesCbcHelper
{
    public byte[] GetEncryptionKey(string password)
    {
        // Derive the encryption key securely using a secure hash function
        var key = SHA256.HashData(Encoding.UTF8.GetBytes(password));
        return key.Take(32).ToArray();
    }

    public byte[] GetInitializationVector()
    {
        // Generate a random initialization vector
        using var rng = new RNGCryptoServiceProvider();
        var iv = new byte[16];
        rng.GetBytes(iv);
        return iv;
    }

    public string Encrypt(string content, byte[] key, byte[] iv)
    {
        // Initialize the AES-256-CBC cipher with the provided key and IV
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;

        // Encrypt the content using the initialized cipher
        using var memStream = new MemoryStream();
        using var cryptoStream = new CryptoStream(memStream, aes.CreateEncryptor(), CryptoStreamMode.Write);
        using (var writer = new StreamWriter(cryptoStream))
        {
            writer.Write(content);
        }
        return Convert.ToBase64String(memStream.ToArray());
    }

    public string Decrypt(string encryptedContent, byte[] key, byte[] iv)
    {
        // Initialize the AES-256-CBC cipher with the provided key and IV
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;

        // Decrypt the content using the initialized cipher
        using var memStream = new MemoryStream(Convert.FromBase64String(encryptedContent));
        using var cryptoStream = new CryptoStream(memStream, aes.CreateDecryptor(), CryptoStreamMode.Read);
        using (var reader = new StreamReader(cryptoStream))
        {
            return reader.ReadToEnd();
        }
    }
}

public class SHA256
{
    public static byte[] HashData(byte[] data)
    {
        using var sha256 = SHA256.Create();
        return sha256.ComputeHash(data);
    }
}
