class CommandExecutor {
public:
    template<typename T>
    void executeCommand(T&& command) {
        // Create a new thread to execute the command
        std::thread t([this, &command]() {
            try {
                // Execute the command
                command();
            } catch (const std::exception& e) {
                // Handle command execution error
                onError(e);
            }
        });
        t.detach();
    }

    void shutDown() {
        // Shut down all running processes
        for (auto& process : processes_) {
            process->stop();
        }
    }

private:
    class Process {
    public:
        virtual ~Process() {}
        virtual void run() = 0;
        void stop() {
            // Stop the process
        }
    };

    template<typename T>
    class CommandProcess : public Process {
    public:
        CommandProcess(T&& command) : command_(std::forward<T>(command)) {}

        void run() override {
            // Execute the command
            command_();
        }

    private:
