using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;

public class TripleDesEncryption
{
    public async Task<string> DecryptBase64Async(string base64EncodedMessage, string key, string iv)
    {
        using (var tripleDes = TripleDES.Create())
        {
            tripleDes.Key = Convert.FromBase64String(key);
            tripleDes.IV = Convert.FromBase64String(iv);

            var decryptedBytes = await Task.Run(() =>
            {
                byte[] base64DecodedMessage = Convert.FromBase64String(base64EncodedMessage);
                return DecryptBytes(tripleDes, base64DecodedMessage);
            });

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    private byte[] DecryptBytes(TripleDES tripleDes, byte[] encryptedBytes)
    {
        using (var ms = new MemoryStream(encryptedBytes))
        {
            using (var cryptoStream = new CryptoStream(ms, tripleDes.CreateDecryptor(), CryptoStreamMode.Read))
            {
                return ReadFully(cryptoStream);
            }
        }
    }

    private byte[] ReadFully(Stream stream)
    {
        const int bufferLength = 1024;
        byte[] buffer = new byte[bufferLength];
        using (var ms = new MemoryStream())
        {
            int readCount;
            do
            {
                readCount = stream.Read(buffer, 0, bufferLength);
                if (readCount > 0)
                {
                    ms.Write(buffer, 0, readCount);
                }
            } while (readCount == bufferLength);

            return ms.ToArray();
        }
    }
}

public class HtmlSanitizer
{
    private readonly HttpClient _httpClient;
    private readonly ICircuitBreaker _circuitBreaker;

    public HtmlSanitizer(HttpClient httpClient, ICircuitBreaker circuitBreaker)
    {
        _httpClient = httpClient;
        _circuitBreaker = circuitBreaker;
    }

    public async Task<string> SanitizeHtmlAsync(string htmlContent)
    {
        int retryCount = 0;
        while (true)
        {
            try
            {
                return await _httpClient.PostAsJsonAsync("https://external-service.com/sanitize", new { htmlContent }).Result.Content.ReadAsStringAsync().Result;
            }
            catch (HttpRequestException ex) when (_circuitBreaker.IsOpen())
            {
                if (retryCount < 3)
                {
                    retryCount++;
                    await Task.Delay(ExponentialBackoff(retryCount));
                }
                else
                {
                    throw new Exception("Failed to sanitize HTML", ex);
                }
            }
        }
    }

    private static TimeSpan ExponentialBackoff(int retryCount)
    {
        return TimeSpan.FromSeconds(Math.Pow(2, retryCount) * 5);
    }
}

public interface ICircuitBreaker
{
    bool IsOpen();
}
