    public async Task<(bool success, object data)> ProcessEncryptedData(byte[] ciphertext, string encryptionKey, byte[] initializationVector, DateTime? timestamp)
    {
        // Get the encrypted data from the cache
        if (_cacheService.TryGetValue(ciphertext, out var cachedData))
        {
            return (true, cachedData);
        }

        // Encrypt the data
        try
        {
            using (var aes = Aes.Create())
            {
                aes.Key = _keyManagementService.GetEncryptionKey(encryptionKey);
                aes.IV = initializationVector;
                using (var decryptor = aes.CreateDecryptor())
                {
                    using (var memoryStream = new MemoryStream(ciphertext))
                    {
                        await memoryStream.CopyToAsync(decryptor);
                    }
                }
            }
        }
        catch (CryptographicException ex)
        {
            // Log the error
            System.Diagnostics.Trace.WriteLine($"Error decrypting data: {ex.Message}");
            return (false, null);
        }

        // Deserialize the decrypted data
        try
        {
            using (var memoryStream = new MemoryStream())
            {
                await memoryStream.WriteAsync(ciphertext, 0, ciphertext.Length);
                memoryStream.Position = 0;
                var binaryFormatter = new BinaryFormatter();
                return (true, binaryFormatter.Deserialize(memoryStream));
            }
        }
        catch (SerializationException ex)
        {
            // Log the error
            System.Diagnostics.Trace.WriteLine($"Error deserializing data: {ex.Message}");
            return (false, null);
        }

        // Cache the decrypted data
        _cacheService.Set(ciphertext, cachedData);

        return (true, cachedData);
    }
}
