public class DataSerializer
{
    public byte[] Serialize<T>(T obj) where T : class
    {
        if (typeof(T).GetCustomAttributes(typeof(JsonAttribute), true).Any())
        {
            return JsonConvert.SerializeObject(obj);
        }
        else if (typeof(T).GetCustomAttributes(typeof(ProtoBufferAttribute), true).Any())
        {
            return ProtoBufSerializer.Serialize(obj);
        }
        else
        {
            throw new ArgumentException("Unsupported serialization format");
        }
    }

    public T Deserialize<T>(byte[] data) where T : class
    {
        if (typeof(T).GetCustomAttributes(typeof(JsonAttribute), true).Any())
        {
            return JsonConvert.DeserializeObject<T>(data);
        }
        else if (typeof(T).GetCustomAttributes(typeof(ProtoBufferAttribute), true).Any())
        {
            return ProtoBufSerializer.Deserialize<T>(data);
        }
        else
        {
            throw new ArgumentException("Unsupported serialization format");
        }
    }
}

public class DataLoader : IDisposable
{
