    {
        _cache = cache;
        _serializer = serializer;
    }

    public async Task<byte[]> LoadDataAsync(string key)
    {
        return await _cache.GetAsync(key);
    }

    public async Task PutDataAsync(string key, byte[] value)
    {
        await _cache.PutAsync(key, value);
    }

    public void Dispose()
    {
        _cache.Dispose();
        _serializer.Dispose();
    }
}

public class DataRetriever
{
