use actix_web::{web, App, HttpServer, Responder};
use futures::stream;
use std::collections::{HashMap, HashSet};
use std::sync::Arc;

#[derive(Debug)]
struct Graph {
    vertices: HashMap<String, Vertex>,
    edges: Vec<(String, String)>,
}

impl Graph {
    fn add_vertex(&mut self, id: &str, properties: HashMap<String, String>) {
        let vertex = Vertex { id, properties };
        self.vertices.insert(id.to_string(), vertex);
    }

    fn add_edge(&mut self, from: &str, to: &str) {
        self.edges.push((from.to_string(), to.to_string()));
    }
}

#[derive(Debug)]
struct Vertex {
    id: &str,
    properties: HashMap<String, String>,
}

async fn process_data(data: Vec<serde_json::Value>) -> Result<(), Box<dyn std::error::Error>> {
    let mut graph = Arc::new(Graph::new());

    for data in data {
        if let serde_json::Value::Object(obj) = data {
            let id = obj["id"].as_str().unwrap();
            let properties = obj
                .iter()
                .filter_map(|(k, v)| v.as_str().map(|v| (k.clone(), v.clone())))
                .collect();

            graph.add_vertex(id, properties);
        }
    }

    Ok(())
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .app_data(web::Data::new(Arc::new(Graph::new())))
            .service(web::resource("/data").route(web::post().to(process_data)))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
