    // Derive a unique directory name from the user-provided string and timestamp
    let now = DateTime::now(Utc);
    let dir_name = format!("{}-{}", user_input, now.format("%Y%m%d%H%M%S"));

    // Validate the directory name against a predefined list of allowed names
    if !validate_dir_name(&dir_name) {
        return Err(format!("Invalid directory name: {}", dir_name));
    }

    // Create the directory in the specified root location
    let full_path = Path::new(root_dir).join(&dir_name);
    match fs::create_dir_all(full_path.as_path()) {
        Ok(_) => info!("Directory created successfully: {}", full_path.display()),
        Err(err) => {
            error!("Error creating directory: {} - {}", err, full_path.display());
            exit(1);
        }
    };

    // Update the directory permissions to be writable by the current user
    match fs::set_permissions(full_path.as_path(), fs::Permissions::from_mode(0o755)) {
        Ok(_) => info!("Directory permissions updated successfully: {}", full_path.display()),
        Err(err) => error!("Error updating directory permissions: {} - {}", err, full_path.display()),
    };

    // Set an environment variable to reflect the full path of the newly created or updated directory
    let env_var = format!("DIR_PATH_{}", dir_name);
    match std::env::set_var(&env_var, full_path.as_path().to_str()) {
        Ok(_) => info!("Environment variable set successfully: {}", &env_var),
        Err(err) => error!("Error setting environment variable: {} - {}", err, &env_var),
