    private Cache cache = new Cache();
    private CDN cdn = new CDN();

    public Response invoke(String request) throws Exception {
        URI uri = cache.get(request);
        if (uri != null) {
            return cache.getResponse(uri);
        }
        uri = cdn.getUri(request);
        Response response = cdn.invoke(uri);
        cache.put(request, uri);
        return response;
    }

