// Define the structure NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[20];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void* createAndPopulateNFAPICRCList(int N) {
    // Input validation: Check if N is within the range 1 to 1000
    if (N < 1 || N > 1000) {
        printf("Invalid input. Please provide a value between 1 and 1000.\n");
        return NULL;
    }

    // Initialize the head of the linked list
    void* head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (head == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = (NFAPI_CRC_INDICATION_PDU_T*)head;

    // Dynamically allocate memory for each NFAPI_CRC_INDICATION_PDU_T structure
    for (int i = 1; i <= N; i++) {
        void* temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (temp == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        current->RX_UE_INFORMATION_TAG = rand() % 1000; // Generate a random value for RX_UE_INFORMATION_TAG
        strcpy(current->RNTI, "RNTI"); // Set RNTI to a fixed string

        if (i < N) {
            void* next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (next == NULL) {
                printf("Memory allocation failed.\n");
                return NULL;
            }

            current->CRCFLAG = rand() % 2; // Generate a random value for CRCFLAG
            NFAPI_CRC_INDICATION_PDU_T* next_node = (NFAPI_CRC_INDICATION_PDU_T*)next;

            current->next = (void*)next_node;
            current = next_node;
        }
    }

    return head;
}
