using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;
using StackExchange.Redis;

public static void Run(
    [HttpTrigger(AuthorizationLevel.Function, "post", Route = null)] HttpRequestData req,
    ILogger logger)
{
    var config = new ConfigurationBuilder().AddJsonFile("local.settings.json").Build();
    var redisConnectionString = config["RedisConnectionString"];

    using (var connection = ConnectionMultiplexer.Connect(redisConnectionString))
    {
        var cache = connection.GetDatabase();

        if (!cache.KeyExists(req.RouteValues["id"].ToString()))
        {
            await UpdateContentFromExternalServiceAsync(req);
        }

        var sanitizedHtml = await GetSanitizedHtmlFromCacheOrServiceAsync(req);

        // Return the sanitized HTML content
        return new HttpResponseData(new StringContent(sanitizedHtml, Encoding.UTF8, "text/html"));
    }
}

private static async Task UpdateContentFromExternalServiceAsync(HttpRequestData req)
{
    try
    {
        using (var httpClient = new HttpClient())
        {
            var response = await httpClient.PostAsync("https://external-svc.com/api/update", req);
            if (response.IsSuccessStatusCode)
            {
                // Cache the updated content for later use
                await cache.StringSet(req.RouteValues["id"].ToString(), response.Content.ReadAsStreamAsync());
            }
        }
    }
    catch (HttpRequestException ex)
    {
        logger.LogError(ex, "Failed to update content from external service");
    }
}

private static async Task<string> GetSanitizedHtmlFromCacheOrServiceAsync(HttpRequestData req)
{
    try
    {
        // Check if the sanitized HTML is cached
        var cachedHtml = await cache.StringGet(req.RouteValues["id"].ToString());
        if (cachedHtml.HasValue)
        {
            return cachedHtml;
        }

        using (var httpClient = new HttpClient())
        {
            var response = await httpClient.GetAsync("https://external-svc.com/api/sanitize");
            if (response.IsSuccessStatusCode)
            {
                // Cache the sanitized HTML for later use
                await cache.StringSet(req.RouteValues["id"].ToString(), response.Content.ReadAsStreamAsync());
                return await response.Content.ReadAsStringAsync();
            }
        }
    }
    catch (HttpRequestException ex)
    {
        logger.LogError(ex, "Failed to get sanitized HTML from external service");
    }

    // Fallback strategy: use cached data
    return await cache.StringGet(req.RouteValues["id"].ToString());
}

private static void ConfigureRedisConnectionString(IConfiguration configuration)
{
    var redisConnectionString = configuration["RedisConnectionString"];
    if (string.IsNullOrEmpty(redisConnectionString))
    {
        throw new InvalidOperationException("Redis connection string is not configured");
    }
}
