#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

class DataPacket {
public:
    int packetID;
    std::string sourceIP;
    std::string destinationIP;
    long timestamp;
    size_t payloadSize;
};

class PacketCollection {
private:
    std::vector<DataPacket> packets;
    size_t initialCapacity, maxSize;
    std::mutex mutex;
    std::condition_variable cv;

public:
    PacketCollection(size_t initialCapacity, size_t maxSize) 
        : initialCapacity(initialCapacity), maxSize(maxSize) {}

    void addPacket(DataPacket packet) {
        std::unique_lock<std::mutex> lock(mutex);
        if (packets.size() >= initialCapacity && packets.size() >= maxSize / 2)
            cv.wait_for(lock, std::chrono::milliseconds(100));
        if (packets.size() > maxSize)
            throw std::runtime_error("Packet collection exceeded maximum size");
        packets.push_back(packet);
    }

    void clearPackets() {
        std::unique_lock<std::mutex> lock(mutex);
        packets.clear();
    }
};

int main() {
    PacketCollection packetCollection(10000, 100000);

    // Example usage
    for (size_t i = 0; i < 50000; ++i) {
        DataPacket packet;
        packet.packetID = i;
        packet.sourceIP = "192.168.1." + std::to_string(i);
        packet.destinationIP = "10.0.2." + std::to_string(i);
        packet.timestamp = i * 1000000;
        packet.payloadSize = (i % 100) + 1;

        try {
            packetCollection.addPacket(packet);
        } catch (const std::exception& e) {
            std::cerr << "Error adding packet: " << e.what() << std::endl;
        }
    }

    // Clean up
    packetCollection.clearPackets();

    return 0;
}
