// Define a struct for PDSCH instances
typedef struct {
    int cell_id;
    int freq_domain_pos;
    int bw_part;
} pdsch_t;

// Define a hash table to store PDSCH instances
#define HASH_TABLE_SIZE 1024
pdsch_t* pdsch_table[HASH_TABLE_SIZE];
pthread_mutex_t pdsch_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new PDSCH instance
int add_pdsch(int cell_id, int freq_domain_pos, int bw_part) {
    pthread_mutex_lock(&pdsch_lock);
    int index = cell_id % HASH_TABLE_SIZE;
    pdsch_t* new_pdsch = (pdsch_t*)malloc(sizeof(pdsch_t));
    new_pdsch->cell_id = cell_id;
    new_pdsch->freq_domain_pos = freq_domain_pos;
    new_pdsch->bw_part = bw_part;
    pdsch_table[index] = new_pdsch;
    pthread_mutex_unlock(&pdsch_lock);
    return 0;
}

// Function to update an existing PDSCH instance
int update_pdsch(int cell_id, int freq_domain_pos, int bw_part) {
    pthread_mutex_lock(&pdsch_lock);
    int index = cell_id % HASH_TABLE_SIZE;
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (pdsch_table[i] && pdsch_table[i]->cell_id == cell_id) {
            pdsch_table[i]->freq_domain_pos = freq_domain_pos;
            pdsch_table[i]->bw_part = bw_part;
            pthread_mutex_unlock(&pdsch_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pdsch_lock);
    return -1; // PDSCH instance not found
}

// Function to retrieve a PDSCH instance by cell ID and frequency domain position
int* get_pdsch(int cell_id, int freq_domain_pos) {
    pthread_mutex_lock(&pdsch_lock);
    int index = cell_id % HASH_TABLE_SIZE;
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (pdsch_table[i] && pdsch_table[i]->cell_id == cell_id && pdsch_table[i]->freq_domain_pos == freq_domain_pos) {
            pthread_mutex_unlock(&pdsch_lock);
            return &pdsch_table[i]->bw_part;
        }
    }
    pthread_mutex_unlock(&pdsch_lock);
    return NULL; // PDSCH instance not found
