void* nfaapi_crc_indication_pdu_t_allocate(int N) {
    pthread_mutex_lock(&mutex);

    struct NFAPI_CRC_INDICATION_PDU_T* p = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if(p == NULL) {
        // handle memory allocation failure
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for(int i = 0; i < N; i++) {
        p[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        while(true) {
            p[i].RNTI = (int)rand() & RNTI_MAX;
            if(hashset_insert(&rnti_set, &p[i].RNTI)) {
                break;
            }
        }
        strcpy(p[i].CRC_INDICATION_REL8_TAG, "XXXX");
    }

    pthread_mutex_unlock(&mutex);
    return p;
}

void nfaapi_crc_indication_pdu_t_free(void* ptr) {
    free(ptr);
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    int N = 1000; // change this value as needed

    pthread_mutex_init(&mutex, NULL);

    struct hashset* rnti_set = hashset_new();
    for(int i = 0; i < RNTI_MAX; i++) {
        hashset_insert(rnti_set, &i);
    }

    void* p = nfaapi_crc_indication_pdu_t_allocate(N);

    // handle the allocated memory here

    nfaapi_crc_indication_pdu_t_free(p);

    pthread_mutex_destroy(&mutex);
    hashset_free(rnti_set);

    return 0;
}

