// Set up HSM for secure key storage and generation
const hsm = {
  // Set up PBKDF2 with Argon2id for enhanced security
  generateKey: (password) => {
    const salt = crypto.randomBytes(16);
    const iterations = 100000;
    const memoryCost = 1024 * 8;

    return crypto.pbkdf2Sync(password, salt, iterations, memoryCost, 'argon2id');
  },
};

// Implement AES-256-GCM for card information encryption
const encryptCardInfo = (cardInfo) => {
