#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgen.h>

// Define the structure for command results
typedef struct {
    int id;
    char* output;
} CommandResult;

// Function to execute shell commands via child processes
CommandResult* execute_command(char* cmd, int* result_id) {
    // Create a new child process
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: Execute the command and store output
        FILE* pipe = popen(cmd, "r");
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), pipe)) {
            printf("%s", buffer);
        }
        pclose(pipe);
    } else if (pid > 0) {
        // Parent process: Wait for child process to complete
        waitpid(pid, NULL, 0);
        *result_id = pid;
    } else {
        // Error handling: Handle fork failure
        perror("Fork failed");
        exit(1);
    }
}

// Function to stream command results to a web server
void stream_results(CommandResult* result) {
    // Establish connection with the web server
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    inet_pton(AF_INET, "example.com", &addr.sin_addr);

    // Send the command result to the web server
    send(sock, &result->output, strlen(result->output), 0);

    // Close the connection
    close(sock);
}

int main() {
    char* cmd = "ls -l";
    int result_id;

    CommandResult* result = execute_command(cmd, &result_id);

    if (result != NULL) {
        stream_results(result);
        free(result->output);  // Free dynamically allocated memory
        free(result);
    }

    return 0;
}

