            // compute MD5 hash of the updated resource's data
            String resourceData = updatedResource.getData();
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = resourceData.getBytes();
            byte[] digest = md.digest(bytes);
            String hash = DatatypeConverter.printHexBinary(digest);
            // return the response with the computed MD5 hash
            return Response.ok(updatedResource).header("ETag", hash).build();
