import asyncio
import random
import time

class PaymentGateway:
    def __init__(self, name):
        self.name = name
        self.api_url = f"https://api.{name}.com"
        self.retry_attempts = 0
        self.last_error_time = None

    async def make_payment(self, amount):
        if self.last_error_time and time.time() - self.last_error_time < 60:
            await asyncio.sleep(1)  # Wait for 1 second before retrying
            return await self.make_payment(amount)

        try:
            response = await self.send_request(f"{self.api_url}/make-payment", {"amount": amount})
            if response.status_code == 200:
                print(f"Payment successful to {self.name} for ${amount}")
                return True
            else:
                print(f"Error making payment to {self.name}: {response.text}")
                self.retry_attempts += 1
                self.last_error_time = time.time()
                await asyncio.sleep(random.randint(1, 5))  # Wait between 1-5 seconds before retrying
                return False

        except Exception as e:
            print(f"Error making payment to {self.name}: {str(e)}")
            self.retry_attempts += 1
            self.last_error_time = time.time()
            await asyncio.sleep(random.randint(1, 5))  # Wait between 1-5 seconds before retrying
            return False

    async def send_request(self, url, data):
        async with aiohttp.ClientSession() as session:
            async with session.post(url, json=data) as response:
                return response


class PaymentProcessor:
    def __init__(self, gateways):
        self.gateways = [PaymentGateway(name) for name in gateways]
        self.cache = {}

    async def process_payment(self, amount, gateway_name):
        if not self.gateways or not self.gateways[0].name == gateway_name:
            print(f"Invalid gateway: {gateway_name}")
            return False

        try:
            payment_gateway = next(g for g in self.gateways if g.name == gateway_name)
            return await payment_gateway.make_payment(amount)

        except Exception as e:
            print(f"Error processing payment: {str(e)}")
            return False


async def main():
    processor = PaymentProcessor(["paypal", "stripe", "visa", "mastercard"])
    try:
        while True:
            amount = random.randint(1, 100)
            gateway_name = random.choice(["paypal", "stripe", "visa", "mastercard"])
            if await processor.process_payment(amount, gateway_name):
                print(f"Payment of ${amount} processed successfully to {gateway_name}")
            else:
                print(f"Error processing payment of ${amount} to {gateway_name}")

    except KeyboardInterrupt:
        print("Exiting...")

asyncio.run(main())
