#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000
#define CACHED_RESOURCE_LIFETIME 300 // in seconds

typedef struct {
    int *data;
    int length;
} ResourceBundle;

void processResourceBundle(char* filePath, int* array, int reductionValue, void (*callback)(int)) {
    pthread_t thread;

    if (array->length > MAX_ARRAY_SIZE) {
        printf("Array too large! ");
        callback(0);
        return;
    }

    ResourceBundle bundle = { .data = array, .length = array->length };

    pthread_create(&thread, NULL, asyncProcessResourceBundle, &bundle);
    pthread_join(thread, NULL);

    free(array);
}

void* asyncProcessResourceBundle(void* bundle) {
    // Handle resource bundle asynchronously
    ResourceBundle* bundlePtr = (ResourceBundle*)bundle;
    int reduction = 0;

    for (int i = 0; i < bundlePtr->length; i++) {
        reduction += bundlePtr->data[i];
    }

    (*processResourceBundleCallback)(reduction);

    free(bundlePtr);
