#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <zlib.h>

// Define a structure for command-line arguments and configuration settings
typedef struct {
    int manpage;
    char *cs_delimiter;
    char *output_file;
} Config;

// Function to parse command-line arguments
Config parse_args(int argc, char **argv) {
    Config config;
    config.manpage = 0;
    config.cs_delimiter = NULL;
    config.output_file = NULL;

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            config.manpage = 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            config.cs_delimiter = argv[argc - 1];
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            config.output_file = argv[i] + 2;
        }
    }

    return config;
}

// Function to process input files
void process_files(char *input_file, Config config) {
    // Open the input file for reading
    int fd = open(input_file, O_RDONLY);
    if (fd < 0) {
        perror("Error opening input file");
        exit(1);
    }

    // Initialize variables to count lines and store data
    int line_count = 0;
    char buffer[1024];
    z_stream stream;

    // Decompress the file if it's compressed
    if (strchr(input_file, '.')) {
        int compressed_fd = open(input_file, O_RDONLY);
        if (compressed_fd < 0) {
            perror("Error opening compressed input file");
            exit(1);
        }

        // Initialize zlib compression stream
        stream.zalloc = Z_NULL;
        stream.zfree = Z_NULL;
        stream.opaque = Z_NULL;

        // Decompress the file line by line
        while (1) {
            int bytes_read = read(compressed_fd, buffer, 1024);
            if (bytes_read <= 0) {
                break;
            }

            // Inflate the decompressed data
            inflateInit2(&stream, 15);
            stream.next_in = (Bytef *)buffer;
            stream.avail_in = bytes_read;
            while (stream.avail_in > 0) {
                int available_out = sizeof(buffer);
                stream.next_out = buffer;
                stream.avail_out = available_out;
                inflate(&stream, Z_NO_FLUSH);
                if (Z_ERROR_STREAM_END == stream.state) {
                    break;
                }
            }

            // Process the decompressed data
            line_count += count_lines(stream.next_out, stream.total_out);

            // Reset the zlib compression stream
            inflateEnd(&stream);
        }

        close(compressed_fd);
    } else {
        // Read the file line by line
        while (1) {
            int bytes_read = read(fd, buffer, 1024);
            if (bytes_read <= 0) {
                break;
            }
            line_count += count_lines(buffer, bytes_read);
        }
    }

    // Close the input file
    close(fd);

    printf("Total lines: %d\n", line_count);
}

// Function to count lines in a buffer
int count_lines(char *buffer, int length) {
    char *p = buffer;
    int line_count = 0;

    while (length--) {
        if (*p == '\n') {
            line_count++;
            p++;
        } else {
            p++;
        }
    }

    return line_count;
}

int main(int argc, char **argv) {
    // Parse command-line arguments
    Config config = parse_args(argc, argv);

    // Process input files
    process_files("input.txt", config);
}
