class KafkaConsumer {
public:
    KafkaConsumer(boost::asio::io_service& ioService, kafka::client& client)
        : ioService_(ioService), client_(client) {}

    void consumeLogs() {
        // Subscribe to log topic
        client_.subscribe("log_topic");

        while (true) {
            // Consume log entries from Kafka
            auto logEntry = client_.consume();

            if (logEntry.has_value()) {
                LogProcessor processor(ioService_, client_);
                processor.processLogEntry(logEntry.value());
            } else {
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }
    }

