class Packet {
public:
    int srcIP;
    int dstIP;
    char protocol;
    long timestamp;

    // constructor
    Packet(int src, int dst, char p, long ts) : srcIP(src), dstIP(dst), protocol(p), timestamp(ts) {}
};

class NetworkTrafficAnalyzer {
private:
    std::queue<std::shared_ptr<Packet>> packetQueue;
    mutable std::mutex queueMutex;
    std::condition_variable queueCondition;

    // dynamic configuration
    int maxQueueSize;
    std::unordered_map<char, bool> allowedProtocols;
    double anomalyThreshold;

public:
    NetworkTrafficAnalyzer(const Config& config) : maxQueueSize(config.maxQueueSize), 
                                                     allowedProtocols(config.allowedProtocols), 
                                                     anomalyThreshold(config.anomalyThreshold) {}

    void analyzePacket(std::shared_ptr<Packet> packet) {
        std::unique_lock<std::mutex> lock(queueMutex);
        if (packetQueue.size() >= maxQueueSize) {
            // queue overflow, discard packets based on config
        }
        else if (!allowedProtocols.count(packet->protocol)) {
            // protocol not allowed, discard packet
        }
        else {
            packetQueue.push(packet);
            // notify consumers of new data
            lock.unlock();
            queueCondition.notify_all();
        }
    }

    void processAnomalies() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            if (!packetQueue.empty()) {
                auto packet = packetQueue.front();
                if (/* anomaly detection logic */) {
                    // report anomaly to external service
                    reportAnomaly(packet);
                }
                packetQueue.pop();
            }
            else {
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }

    void reportAnomaly(const Packet& packet) {
        // async call to external anomaly detection service
        std::thread([packet]() {
            try {
                // call external service
                // handle success/failure
            }
            catch (const std::exception& e) {
                // log error and retry later
            }
        }).detach();
    }

private:
    class Config {
    public:
        int maxQueueSize;
        std::unordered_map<char, bool> allowedProtocols;
        double anomalyThreshold;

        // constructor
        Config(int mqs, const std::unordered_map<char, bool>& ap, double at) : 
            maxQueueSize(mqs), allowedProtocols(ap), anomalyThreshold(at) {}
    };
};
