['Here is a sample code block for implementing the requested semaphore management system:

```c
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>

// Define the semaphore structure
typedef struct {
    pthread_mutex_t mutex;
    sem_t sem;
} semaphore_t;

// Initialize the semaphore with an initial value and name
semaphore_t* init_semaphore(const char* name, int init_value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    sem->mutex = PTHREAD_MUTEX_INITIALIZER;
    sem->sem = sem_open(name, O_CREAT | O_RDWR, 0644, init_value);
    return sem;
}

// Acquire the semaphore
void acquire_semaphore(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    sem_wait(&sem->sem);
}

// Release the semaphore
void release_semaphore(semaphore_t* sem) {
    sem_post(&sem->sem);
    pthread_mutex_unlock(&sem->mutex);
}

// Initialize and start the semaphore management system
int init_sem_system(int num_threads, int initial_value) {
    // Create a named semaphore with the specified initial value
    semaphore_t* sem = init_semaphore("my_semaphore", initial_value);

    // Start threads and initialize criticality levels
    pthread_t threads[num_threads];
    int thread_criticality[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_criticality[i] = ...;  // Initialize criticality levels based on requirements
        pthread_create(&threads[i], NULL, start_thread, &thread_criticality[i]);
    }

    return 1;
}

// Start each thread with its respective criticality level and semaphore reference
void* start_thread(void* arg) {
    int criticality = *(int*)arg;
    // ...
    acquire_semaphore(sem);
    // Perform critical operations based on the thread's criticality level
    release_semaphore(sem);
    return NULL;
}

// Clean up system resources when shutting down
void cleanup_sem_system() {
    sem_close(sem);  // Close and destroy the semaphore
    free(sem);       // Free memory allocated for the semaphore structure

    // Terminate threads and clean up any remaining resources
    pthread_exit(NULL);
}
