['```rust
extern crate llvm;
extern crate regex;
extern crate dirs;

use std::path::{Path, PathBuf};
use std::fs::File;
use std::io::{Read, Write};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

struct CodeGenerator {
    config: Arc<Mutex<HashMap<String, String>>>,
    llvmlib: llvm::LLVMContext,
}

impl CodeGenerator {
    fn new() -> Self {
        let config = Arc::new(Mutex::new(HashMap::new()));
        let llvmlib = llvm::LLVMContext::new();
        CodeGenerator { config, llvmlib }
    }

    fn generate_ir(&self, file: &Path) -> Result<String, String> {
        // Read configuration from file
        let mut config_file = File::open(file)?;
        let mut contents = String::new();
        config_file.read_to_string(&mut contents)?;

        // Parse configuration
        let mut parser = regex::Regex::new(r"(\w+)=(\S+)").unwrap();
        for cap in parser.captures_iter(&contents) {
            let key = &cap[1];
            let value = &cap[2];
            self.config.lock().unwrap().insert(key.to_string(), value.to_string());
        }

        // Generate IR code
        let ir_code = format!("module {{ {} }}", self.llvmlib.build_module(&self.config));
        Ok(ir_code)
    }
}

fn main() {
    let mut code_generator = CodeGenerator::new();

    // Read configuration files
    let mut files = vec![];
    for file in PathBuf::from("path/to/config/files").read_dir().unwrap() {
        match file {
            Ok(file) => files.push(file.path()),
            Err(_) => println!("Error reading config file"),
        }
    }

    // Generate IR code concurrently
    let handles: Vec<_> = files.iter().map(|file| {
        thread::spawn(move || {
            match code_generator.generate_ir(file) {
                Ok(ir_code) => println!("Generated IR code: {}", ir_code),
                Err(err) => println!("Error generating IR code: {}", err),
            }
        })
    }).collect();

    for handle in handles {
        handle.join().unwrap();
    }
}
