using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace DatabaseConnectionPool
{
    public interface IDatabaseConnection
    {
        void ExecuteQuery(string query);
    }

    public class SqlConnection : IDatabaseConnection
    {
        private readonly string connectionString;

        public SqlConnection(string connectionString)
        {
            this.connectionString = connectionString;
        }

        public void ExecuteQuery(string query)
        {
            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                connection.Open();
                SqlCommand command = new SqlCommand(query, connection);
                command.ExecuteNonQuery();
            }
        }
    }

    public class DatabaseConnectionPool
    {
        private readonly Dictionary<string, List<IDatabaseConnection>> connections;
        private readonly int maxConnectionsPerDatabase;
        private readonly int timeout;

        public DatabaseConnectionPool(int maxConnectionsPerDatabase, int timeout)
        {
            this.maxConnectionsPerDatabase = maxConnectionsPerDatabase;
            this.timeout = timeout;
            this.connections = new Dictionary<string, List<IDatabaseConnection>>();
        }

        public async Task<IDatabaseConnection> GetConnectionAsync(string databaseName)
        {
            if (!this.connections.ContainsKey(databaseName))
            {
                this.connections[databaseName] = new List<IDatabaseConnection>();

                for (int i = 0; i < this.maxConnectionsPerDatabase; i++)
                {
                    await this.CreateConnectionAsync(databaseName);
                }
            }

            return this.connections[databaseName].First();
        }

        private async Task CreateConnectionAsync(string databaseName)
        {
            while (true)
            {
                try
                {
                    IDatabaseConnection connection = new SqlConnection($"Server={databaseName};Database=MyDB;User Id=myuser;Password=mypassword;");
                    await connection.ExecuteQuery("SELECT 1");
                    this.connections[databaseName].Add(connection);
                    break;
                }
                catch (Exception ex)
                {
                    await Task.Delay(this.timeout);
                }
            }
        }

        public void ReturnConnection(IDatabaseConnection connection)
        {
            foreach (var connections in this.connections.Values)
            {
                if (connections.Contains(connection))
                {
                    connections.Remove(connection);
                    return;
                }
            }
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            DatabaseConnectionPool pool = new DatabaseConnectionPool(5, 1000);

            for (int i = 0; i < 10; i++)
            {
                await pool.GetConnectionAsync("Database1").ExecuteQuery($"SELECT * FROM table{i}");
                await pool.ReturnConnection(await pool.GetConnectionAsync("Database1"));
            }
        }
    }
}
