function renderFooterScripts(scripts) {
  const apiUrl = 'https://api.example.com';
  const cache = {};

  async function fetchScriptMetadata(scriptId) {
    try {
      const response = await fetch(`${apiUrl}/metadata/${scriptId}`);
      if (!response.ok) throw new Error('Failed to retrieve metadata');
      return await response.json();
    } catch (error) {
      console.error(error);
      // Fallback to cached data
      const cachedData = cache[scriptId];
      if (cachedData) return cachedData;
      // Revalidate script after a short timeout
      setTimeout(() => revalidateScript(scriptId), 1000);
      return null;
    }
  }

  async function revalidateScript(scriptId) {
    try {
      const response = await fetch(`${apiUrl}/metadata/${scriptId}`);
      if (!response.ok) throw new Error('Failed to revalidate script');
      const metadata = await response.json();
      cache[scriptId] = metadata;
    } catch (error) {
      console.error(error);
    }
  }

  async function renderScript(script) {
    try {
      const metadata = await fetchScriptMetadata(script.scriptId);
      if (!metadata) return '';
      // Add metadata attributes to script tag
      const attributes = ['version', 'author', 'dependencies'].reduce((acc, field) => ({
        ...acc,
        [field]: metadata[field],
      }), {});
      return `
        <script id="${script.scriptId}">
          ${attributes.join(' ')}>${script.scriptContent}</script>
      `;
    } catch (error) {
      console.error(error);
      // Log error and skip rendering
      return '';
    }
  }

  async function renderFooter() {
    const footer = [];
    for await (const script of scripts) {
      try {
        const renderedScript = await renderScript(script);
        footer.push(renderedScript);
      } catch (error) {
        console.error(error);
      }
    }
    return footer.join('');
  }

  return renderFooter();
}
