**Rust Function: Measure Compilation Time and Resident Set Size**

```rust
use log::{info, warn};
use std::process::exit;

fn measure_compilation_time_and_resident_set_size() -> i32 {
    let mut output = String::new();
    let status = std::process::Command::new("rustc")
        .arg("--crate-type=lib")
        .arg("--emit=asm,llvm-ir,object")
        .output(&mut output)
        .expect("Failed to execute command");

    if !output.contains("Error") {
        info!("Compilation successful");
    } else {
        warn!("Compilation failed: {}", &output);
        exit(1);
    }

    let resident_set_size = std::process::Command::new("pmap")
        .arg("-x")
        .arg("/proc/self/status")
        .output()
        .expect("Failed to execute command");

    info!("Resident set size: {}", String::from_utf8_lossy(&resident_set_size.stdout));

    exit(status.code().unwrap_or(0));
}

