public class FileProcessorService {
    private static final int MAX_CONCURRENT_REQUESTS = 10000;
    private static final int FILE_TYPES_CACHE_TTL = 300; // seconds
    private final Map<String, Long> fileSizes = new HashMap<>();
    private final Map<String, Long> fileTypeCounts = new HashMap<>();
    private final CachingLayer cachingLayer;
    private final ThirdPartyLogger logger;

    public FileProcessorService(CachingLayer cachingLayer, ThirdPartyLogger logger) {
        this.cachingLayer = cachingLayer;
        this.logger = logger;
    }

    public void processFilePaths(Consumer<String> fileProcessor) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
        CompletionService<String> completionService = new ExecutorCompletionService<>(executor);

        for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
            completionService.submit(() -> processFilePath(fileProcessor));
        }

        int completedRequests = 0;
        while (completedRequests < MAX_CONCURRENT_REQUESTS) {
            try {
                String fileProcessed = completionService.take().get();
                if (fileProcessed != null) {
                    processFile(fileProcessed);
                }
            } catch (InterruptedException | ExecutionException e) {
                logger.error("Error processing file", e);
                break;
            }
            completedRequests++;
        }

        executor.shutdownNow();
    }

    private void processFilePath(Consumer<String> fileProcessor) throws InterruptedException, IOException {
        // Process the file path and extract the file type
        String filePath = fileProcessor.accept();
        if (filePath == null) return;

        try {
            File file = new File(filePath);
            Long fileSize = getFileSize(file);
            fileSizes.put(getFileType(file), fileSize);
            fileTypeCounts.put(getFileType(file), fileTypeCounts.getOrDefault(getFileType(file), 0L) + 1);
        } catch (IOException e) {
            logger.error("Error reading file", e);
        }
    }

    private String getFileType(File file) {
        // Implement your file type detection logic here
        return "Unknown";
    }

    private Long getFileSize(File file) throws IOException {
        // Read the file size and calculate average file size for each type
        return file.length();
    }

    public Map<String, Long> getAverageFileSizes() {
        // Calculate and cache the average file sizes for each type
        Map<String, Long> averageFileSizes = new HashMap<>();
        for (Map.Entry<String, Long> entry : fileSizes.entrySet()) {
            String fileType = entry.getKey();
            long fileSizeSum = 0;
            int count = 0;
            for (Map.Entry<String, Long> cacheEntry : cachingLayer.getCacheEntries().entrySet()) {
                if (cacheEntry.getKey().equals(fileType)) {
                    fileSizeSum += cacheEntry.getValue();
                    count++;
                }
            }
            averageFileSizes.put(fileType, (long) Math.round(fileSizeSum / count));
        }
        return averageFileSizes;
    }

    public void shutdown() {
        cachingLayer.shutdown();
    }
}
