import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class DynamicBackgroundTaskExecutor {
    private static final int DEFAULT_MAX_THREADS = 5;
    private ExecutorService executor;
    private AtomicInteger taskCount = new AtomicInteger(0);
    private double systemHealthFactor = 1.0; // initial value

    public void start(int maxThreads) {
        this.executor = Executors.newFixedThreadPool(maxThreads);
    }

    public void executeTask(Runnable task) {
        int currentTaskCount = taskCount.incrementAndGet();
        if (currentTaskCount > MAX_TASKS && systemHealthFactor < 0.5) {
            // scale down when load is high and system health is low
            executor.shutdown();
            start(DEFAULT_MAX_THREADS);
        }
        executor.submit(task);
    }

    public void updateSystemHealth(double factor) {
        this.systemHealthFactor = factor;
    }

    public void shutdown() {
        executor.shutdownNow();
    }
}

