use tokio::prelude::*;
use actix_web::{web, App, HttpResponse};
use serde_derive::Deserialize;

#[derive(Deserialize)]
struct Data {
    foo: String,
    bar: i32,
}

async fn handle_request() -> Result<HttpResponse, Box<dyn std::error::Error>> {
    // Load data from external APIs
    let api_data = load_api_data().await?;

    // Process API data and store in cache
    let mut cache = tokio::sync::RwLock::new(());

    for item in api_data {
        let result = process_item(item);
        if let Ok(data) = result {
            *cache.write().unwrap() = Some(data);
        }
    }

    // Serve data from cache or load from database
    match get_from_cache(&mut cache).await {
        Ok(Some(data)) => HttpResponse::Ok().json(&data),
        Ok(None) => {
            let db_data = load_from_database().await?;
            *cache.write().unwrap() = Some(db_data);
            HttpResponse::Ok().json(&db_data)
        }
        Err(err) => HttpResponse::InternalServerError().json(&err.to_string()),
    }
}

async fn load_api_data() -> Result<Vec<Data>, Box<dyn std::error::Error>> {
    // Load data from four external APIs
    let mut api_data = vec![];
    for _ in 0..4 {
        let data = load_single_api().await?;
        api_data.extend(data);
    }
    Ok(api_data)
}

async fn process_item(item: Data) -> Result<Data, Box<dyn std::error::Error>> {
    // Process item and return processed data
    Ok(item)
}

async fn get_from_cache(cache: &mut tokio::sync::RwLock<()>) -> Result<Option<Data>, Box<dyn std::error::Error>> {
    // Get data from cache if available
    match cache.read().await.as_ref() {
        Some(data) => Ok(Some(*data)),
        None => Ok(None),
    }
}

async fn load_from_database() -> Result<Data, Box<dyn std::error::Error>> {
    // Load data from database (slow)
    Ok(Data { foo: "database".to_string(), bar: 12345 })
}

#[actix_web::main]
async fn main() {
    let system = System::new("my_service");

    let app = web::app()
        .service(web::resource("/").route(web::get().to(handle_request)));

    system.run(app.to_http());
}
