use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex};
use std::thread;
use tokio::sync::mpsc;

async fn handle_message(message: String) {
    println!("Received message: {}", message);
}

async fn process_messages(messages: Vec<String>) {
    for message in messages {
        handle_message(message).await;
    }
}

#[actix_web]async fn consumer_handler(req: HttpRequest) -> Result<HttpResponse, Error> {
    let config = Arc::new(Mutex::new(HashMap::<String, String>::new()));

    let (tx, mut rx) = mpsc::channel(100);

    thread::spawn(move || {
        loop {
            match rx.recv() {
                Ok(msg) => process_messages(vec![msg]).await,
                Err(_) => return,
            }
        }
    });

    // Start a new actix-web server to receive messages
    let server = HttpServer::new(|| {
        App::new()
            .service(web::resource("/").to(consumer_handler))
    })
    .bind("127.0.0.1:8080")?
    .run();

    server.await.unwrap();
}

#[actix_web]async fn producer_handler(req: HttpRequest) -> Result<HttpResponse, Error> {
    // Send messages to the consumer
    let mut messages = VecDeque::new();
    for i in 0..1000 {
        messages.push_back(format!("Message #{}", i));
    }
    while let Some(msg) = messages.pop_front() {
        tx.send(msg).await.unwrap();
    }

    HttpResponse::Ok().finish()
}

fn main() {
    HttpServer::new(|| {
        App::new()
            .service(web::resource("/producer").to(producer_handler))
    })
    .bind("127.0.0.1:8081")?
