// Define a struct to store transaction data
typedef struct {
    int id;
    int age;
    double weighted_sum;
} Transaction;

// Define a function to filter transactions based on criteria
Transaction* filter_transactions(Transaction* transactions, int num_transactions) {
    // Initialize the maximum weighted sum and corresponding transaction ID
    double max_weighted_sum = -1.0;
    int best_transaction_id = -1;

    for (int i = 0; i < num_transactions; i++) {
        Transaction* current_transaction = &transactions[i];
        if (current_transaction->age > 3) {
            continue;
        }
        if (current_transaction->weighted_sum > max_weighted_sum) {
            max_weighted_sum = current_transaction->weighted_sum;
            best_transaction_id = current_transaction->id;
        }
    }

    return best_transaction_id;
}
