class DistributedKeyValueStore {
public:
    // Constructor
    DistributedKeyValueStore(std::string node_id, std::string messaging_system_url)
        : node_id_(node_id), messaging_system_url_(messaging_system_url) {}

    // Method to put a key-value pair into the distributed store
    void put(const std::string& key, const std::string& value) {
        // Send message to Kafka topic using the messaging system
        sendMessageToKafka(messaging_system_url_, "put", {{"key", key}, {"value", value}});
    }

    // Method to get a key-value pair from the distributed store
    void get(const std::string& key, const std::function<void(std::string)>& callback) {
        // Send message to Kafka topic using the messaging system
        sendMessageToKafka(messaging_system_url_, "get", {{"key", key}});

        // Listen for messages from other nodes in the distributed store
        receiveMessagesFromNodes([callback](const std::string& message) {
            if (message.find("value:") != std::string::npos) {
                callback(message.substr(6));
            }
        });
    }

private:
    std::string node_id_;
    std::string messaging_system_url_;

    // Helper method to send a message to the Kafka topic
    void sendMessageToKafka(const std::string& url, const std::string& operation, const std::map<std::string, std::string>& data) {
        // Create a new producer using the messaging system
        auto producer = createProducer(url);

        // Send the message to the Kafka topic
        producer->send(operation, data);
    }

    // Helper method to receive messages from other nodes in the distributed store
    void receiveMessagesFromNodes(const std::function<void(std::string)>& callback) {
        // Create a new consumer using the messaging system
        auto consumer = createConsumer(messaging_system_url_);

        // Start listening for messages from other nodes
        consumer->startListening([callback](const std::string& message) {
            callback(message);
        });
    }

    // Helper method to create a producer or consumer using the messaging system
