using System;
using System.IO;
using System.Linq;

public class LargestIntegerFinder
{
    public int FindLargestInteger(Stream inputStream)
    {
        var integers = new List<int>();
        using (var reader = new BinaryReader(inputStream))
        {
            while (reader.BaseStream.Position < reader.BaseStream.Length)
            {
                try
                {
                    var integer = reader.ReadInt32();
                    integers.Add(integer);
                }
                catch (EndOfStreamException)
                {
                    // Handle end of stream
                    break;
                }
                catch (Exception ex)
                {
                    // Log and handle malformed data
                    Console.WriteLine($"Error reading integer: {ex.Message}");
                    return 0; // Fallback value or error handling
                }
            }
        }

        return integers.Max();
    }
}
