using System.Security.Cryptography;
using System.Threading;

namespace Md5Library
{
    public enum LoggingLevel { Debug, Info, Warning, Error }

    public class Md5Hasher
    {
        private readonly object _lock = new object();
        private readonly Dictionary<string, byte[]> _cache = new Dictionary<string, byte[]>(new DictionaryComparer<string>(StringComparer.OrdinalIgnoreCase));
        private readonly int _cacheSize;
        private readonly LoggingLevel _logLevel;

        public Md5Hasher(int cacheSize, LoggingLevel logLevel)
        {
            _cacheSize = cacheSize;
            _logLevel = logLevel;
        }

        public byte[] Hash(string input)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentException("Input string cannot be null or empty");

            var hash = ComputeHash(input);

            LogInputAndHash(input, hash);

            return hash;
        }

        private void LogInputAndHash(string input, byte[] hash)
        {
            using (var logWriter = GetLogWriter())
            {
                if (_logLevel >= LoggingLevel.Info)
                    logWriter.WriteLine($"Hashed string '{input}' with length {input.Length} to {BitConverter.ToString(hash).Replace("-", "")}");
                else if (_logLevel >= LoggingLevel.Warn)
                    logWriter.WriteLine("Hashing attempt failed due to invalid input or caching issues");
            }
        }

        private Stream GetLogWriter()
        {
            // Implement logging integration here
            throw new NotImplementedException();
        }

        private byte[] ComputeHash(string input)
        {
            using (var md5 = MD5.Create())
            {
                var stream = new MemoryStream(Encoding.UTF8.GetBytes(input));
                var hashBytes = md5.ComputeHash(stream);

                if (_cache.Count >= _cacheSize / 2) // Evict cache entries every half the configured size
                    _cache = _cache.Take(_cacheSize).ToDictionary(kvp => kvp.Key, kvp => kvp.Value);

                return hashBytes;
            }
        }

        public class DictionaryComparer<TKey> : IEqualityComparer<TKey>
        {
            private readonly IEqualityComparer<TKey> _comparer;

            public DictionaryComparer(IEqualityComparer<TKey> comparer)
            {
                _comparer = comparer;
            }

            public bool Equals(TKey x, TKey y) => _comparer.Equals(x, y);

            public int GetHashCode(TKey obj) => _comparer.GetHashCode(obj);
        }
    }
}
