public Order FetchAndProcessOrderData(int orderId)
{
    // Retry mechanism with exponential backoff
    int retries = 0;
    const int maxRetries = 5;

    while (retries <= maxRetries)
    {
        try
        {
            // Call the external payment processing service
            var response = CallExternalService(orderId);

            if (!response.IsSuccessStatusCode())
            {
                throw new Exception($"Failed to retrieve order data: {response.StatusCode}");
            }

            // Process the response data
            var processedOrder = ProcessResponseData(response.Content());

            return processedOrder;
        }
        catch (Exception ex)
        {
            retries++;

            if (retries >= maxRetries)
            {
                throw new Exception("Failed to retrieve order data after multiple retries", ex);
            }

            // Wait for the exponential backoff period
            Thread.Sleep(ExponentialBackoff(retries));
        }
    }

    return null;
}

// Private methods omitted for brevity

private static HttpStatusCode ExponentialBackoff(int retryCount)
{
    int baseTimeout = 1000; // 1 second
    int maxTimeout = 30000; // 30 seconds

    int timeout = (int)Math.Pow(2, retryCount) * baseTimeout;

    return new TimeSpan(timeout).Hours;
}

