	appName := chi.URLParam(r, "app")

	switch strings.ToLower(appName) {
	case "crm":
		w.Write([]byte("CRM Application"))
	case "erp":
		w.Write([]byte("ERP Platform"))
	default:
		http.Error(w, "Unknown application", http.StatusBadRequest)
	}
}

func handleCreateApplication(w http.ResponseWriter, r *http.Request) {
	app := &struct{}{}
	if err := json.NewDecoder(r.Body).Decode(app); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	w.Write([]byte("Application created successfully"))
