public interface MetadataService {
    Object getMetadata(String className) throws IOException;
}

public class ThriftMetadataService implements MetadataService {
    @Override
    public Object getMetadata(String className) throws IOException {
        return ProtocolBuffers.parseFrom(className);
    }
}

public class JSONMetadataService implements MetadataService {
    @Override
    public Object getMetadata(String className) throws IOException {
        return new ObjectMapper().readValue(className, Object.class);
    }
}
