const { createConnection } = require('mariadb');
const { EncryptionService } = require('./encryption-service');
const { ConfigurationParser } = require('./configuration-parser');
const { S3 } = require('aws-sdk');
const { CircuitBreaker } = require('circuit-breaker');

class ConfigManager {
  constructor({
    configId,
    s3BucketName,
    encryptionServiceUrl,
    encryptionKey,
    mariadbUsername,
    mariadbPassword,
    mariadbHost,
    mariadbPort
  }) {
    this.configId = configId;
    this.s3BucketName = s3BucketName;
    this.encryptionServiceUrl = encryptionServiceUrl;
    this.encryptionKey = encryptionKey;
    this.mariadbUsername = mariadbUsername;
    this.mariadbPassword = mariadbPassword;
    this.mariadbHost = mariadbHost;
    this.mariadbPort = mariadbPort;

    this.rateLimiter = new RateLimiter({
      points: 100,
      duration: 1
    });

    this.circuitBreaker = new CircuitBreaker({
      fallback: () => console.log('Circuit breaker tripped'),
      timeout: 1000,
      maxFailures: 3,
      sleepDuration: 2000
    });

    this.s3 = new S3({
      region: 'your-region',
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      accessKeyId: process.env.AWS_ACCESS_KEY_ID
    });
  }

  async getConfiguration() {
    const s3Object = await this.s3.getObject({ Bucket: this.s3BucketName, Key: `config/${this.configId}.json` }).promise();
    return JSON.parse(s3Object.Body.toString());
  }

  async updateConfiguration(newConfig) {
    if (!this.rateLimiter.allow()) throw new Error('Rate limiting exceeded');

    try {
      const encryptedNewConfig = await this.encryptConfiguration(newConfig);
      await this.writeToMysql(encryptedNewConfig);
    } catch (error) {
      if (this.circuitBreaker.try()) {
        await this.updateConfiguration(newConfig);
      }
    }
  }

  async encryptConfiguration(config) {
    const encryptionService = new EncryptionService(this.encryptionKey, this.encryptionServiceUrl);
    return JSON.stringify(await encryptionService.encrypt(config));
  }

  async writeToMysql(encryptedConfig) {
    const mariadbConnection = await createConnection({
      host: this.mariadbHost,
      port: this.mariadbPort,
      user: this.mariadbUsername,
      password: this.mariadbPassword
    });

    try {
      await mariadbConnection.query(`UPDATE config SET value = ? WHERE id = ?`, [encryptedConfig, this.configId]);
    } catch (error) {
      console.error(error);
    } finally {
      mariadbConnection.end();
    }
  }

  async readFromMysql() {
    const mariadbConnection = await createConnection({
      host: this.mariadbHost,
      port: this.mariadbPort,
      user: this.mariadbUsername,
      password: this.mariadbPassword
    });

    try {
      const config = await mariadbConnection.query(`SELECT value FROM config WHERE id = ?`, [this.configId]);
      return JSON.parse(config[0].value);
    } catch (error) {
      console.error(error);
    } finally {
      mariadbConnection.end();
    }
  }
}

module.exports = ConfigManager;
