use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

struct Config {
    log_level: String,
    log_destination: String,
    // ...
}

impl Default for Config {
    fn default() -> Self {
        Config {
            log_level: "INFO".to_string(),
            log_destination: "/var/log/ecommerce.log".to_string(),
            // ...
        }
    }
}

struct Logger {
    config: Arc<Mutex<Config>>,
    log_buffer: Vec<String>,
}

impl Logger {
    fn new(config: Arc<Mutex<Config>>) -> Self {
        Logger { 
            config,
            log_buffer: vec![], 
        }
    }

    fn log(&mut self, level: String, message: String) {
        let now = Instant::now();
        thread::sleep(Duration::from_millis(100));
        match &*self.config.lock().unwrap().log_level.as_str() {
            "DEBUG" => println!("{} [DEBUG] {}", now, message),
            "INFO" => println!("{} [INFO] {}", now, message),
            _ => {}
        }
    }

    fn flush(&mut self) {
        if let Some(message) = self.log_buffer.pop() {
            match &*self.config.lock().unwrap().log_destination.as_str() {
                "/var/log/ecommerce.log" => {
                    // TO DO: implement logging to file
                },
                _ => {}
            }
        }
    }

    fn set_log_level(&mut self, level: String) {
        *self.config.get_mut().unwrap().log_level = level;
    }
}

fn main() {
    let config = Arc::new(Mutex::new(Config::default()));
    let mut logger = Logger::new(config.clone());

    thread::spawn(move || loop {
        thread::sleep(Duration::from_millis(500));
        logger.log("INFO".to_string(), "Hello, World!".to_string());
    });

    thread::sleep(Duration::from_secs(10));
    logger.flush();
}
