            return self.services[service_type_id]()
        else:
            raise KeyError(f"Service type {service_type_id} not found")

    def to_json(self) -> str:
        config = {}
        for service_type_id, factory in self.services.items():
            config[service_type_id] = {"factory": factory.__module__ + "." + factory.__qualname__}
        return json.dumps(config)

    @classmethod
    def from_json(cls, json_config: str) -> 'ServiceDirectory':
        directory = cls()
        config = json.loads(json_config)
        for service_type_id, service_config in config.items():
            factory_name = service_config["factory"]
            directory.register_factory(service_type_id, globals()[factory_name])
        return directory

