package com.example.api.client;

import io.grpc.*;
import io.grpc.stub.*;
import java.util.concurrent.*;

public class ApiClient {
    private static final Logger logger = LoggerFactory.getLogger(ApiClient.class);
    private final ManagedChannel channel;
    private final BlockingStub<ApiService> apiStub;
    private final AsyncStub<ApiService> asyncApiStub;
    private final ScheduledExecutorService executor;

    public ApiClient(String target, int timeout) throws IOException {
        channel = ManagedChannelBuilder.forTarget(target).setIdleTimeout(timeout).build();
        apiStub = ApiService.newBlockingStub(channel);
        asyncApiStub = ApiService.newAsyncStub(channel);
        executor = Executors.newSingleThreadScheduledExecutor();
    }

    // User authentication
    public void authenticate(String username, String password) {
        try {
            apiStub.authenticate(username, password);
        } catch (StatusRuntimeException e) {
            logger.error("Authentication failed: {}", e.getMessage());
        }
    }

    // Payment processing
    public CompletableFuture<String> makePayment(PaymentRequest paymentRequest) {
        return asyncApiStub.makePayment(paymentRequest).thenApply(ApiResponse::getMessage);
    }

    // Order management
    public void placeOrder(OrderRequest orderRequest) {
        try {
            apiStub.placeOrder(orderRequest);
        } catch (StatusRuntimeException e) {
            logger.error("Order placement failed: {}", e.getMessage());
        }
    }

    // Inventory control
    public CompletableFuture<InventoryResponse> getInventory() {
        return asyncApiStub.getInventory().thenApply(ApiResponse::getInventoryResponse);
    }

    // Supply chain logistics
    public void trackShipment(ShipmentRequest shipmentRequest) {
        try {
            apiStub.trackShipment(shipmentRequest);
        } catch (StatusRuntimeException e) {
            logger.error("Shipment tracking failed: {}", e.getMessage());
        }
    }

    // Shutdown and cleanup
    public void shutdown() {
        channel.shutdown();
        executor.shutdown();
    }
}
