// Function to calculate statistics
void calc_stats() {
    int total_packets = 0;
    int packet_loss = 0;
    int duplicate_packets = 0;

    // Calculate stats based on packet hash fingerprints
    for (Monitor* m : monitors) {
        // Get packets from monitoring system
        Packet* p = get_packets(m);
        if (!p)
            continue;

        total_packets += p->length;
        for (int i = 0; i < p->length; i++) {
            if (hash_fingerprint(p[i]) == duplicate_hash) {
                duplicate_packets++;
            } else {
                packet_loss++;
            }
        }
