    double avg_packet_size = (double)total_packets / get_total_packets();

    printf("Total packets: %d\n", total_packets);
    printf("Packet loss: %d (%.2f%%)\n", packet_loss, ((packet_loss * 100.0) / total_packets));
    printf("Duplicate packets: %d (%.2f%%)\n", duplicate_packets, ((duplicate_packets * 100.0) / total_packets));
    printf("Average packet size: %.2f bytes\n", avg_packet_size);
}

// Threaded function to process packets concurrently
void* thread_func(void* arg) {
    pthread_t tid = pthread_self();

    // Process packets from a specific monitor
    for (Monitor* m : monitors) {
        if (pthread_equal(tid, m->monitor_tid)) {
            while (1) {
                Packet* p = get_packets_from_monitor(m);
                process_packet(p);
            }
        }
    }

    return NULL;
}

// Function to start threads and handle shutdown
void start_threads() {
    pthread_t tid;

    for (Monitor* m : monitors) {
        pthread_create(&tid, NULL, thread_func, m->monitor_tid);
    }

    // Handle shutdown when requested
    if (shutdown_requested()) {
        // Stop threads
        for (Monitor* m : monitors) {
            pthread_cancel(m->monitor_tid);
        }
    }
}

int main() {
