    [ApiController]
    [Route("api/[controller]")]
    public class WebPageSectionController : ControllerBase
    {
        private readonly ILogger<WebPageSectionController> _logger;
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly IHtmlSanitizerService _htmlSanitizerService;

        public WebPageSectionController(ILogger<WebPageSectionController> logger, 
            IHttpClientFactory httpClientFactory, IHtmlSanitizerService htmlSanitizerService)
        {
            _logger = logger;
            _httpClientFactory = httpClientFactory;
            _htmlSanitizerService = htmlSanitizerService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateWebPageSection([FromBody] UpdateWebPageSectionRequest request)
        {
            try
            {
                // Call the external HTML sanitization service to sanitize the input HTML
                var sanitizedHtml = await _htmlSanitizerService.SanitizeHtmlAsync(request.HtmlContent);

                // Create a new database transaction to ensure atomicity and idempotence
                using (var dbContext = new WebPageSectionDbContext())
                {
                    await dbContext.Database.BeginTransactionAsync();

                    try
                    {
                        // Update the web page section with the sanitized HTML
                        await dbContext.WebPageSections.UpdateAsync(request.PageSectionId, sanitizedHtml);

                        // Commit the transaction
                        await dbContext.Database.CommitTransactionAsync();
                    }
                    catch (Exception ex)
                    {
                        // Roll back the transaction on failure
                        await dbContext.Database.RollbackTransactionAsync();

                        _logger.LogError(ex, "Failed to update web page section");

                        return StatusCode(500);
                    }
                }
            }
            catch (HttpRequestException ex)
            {
                // Retry the request if the external HTML sanitization service is unavailable
                for (int i = 0; i < 3; i++)
                {
                    try
                    {
                        await _htmlSanitizerService.SanitizeHtmlAsync(request.HtmlContent);
                        break;
                    }
                    catch (HttpRequestException ex2)
                    {
                        // Fall back to a default HTML sanitization mechanism if the service is unavailable
                        sanitizedHtml = await _defaultHtmlSanitizerService.SanitizeHtmlAsync(request.HtmlContent);

                        // Create a new database transaction to ensure atomicity and idempotence
                        using (var dbContext = new WebPageSectionDbContext())
                        {
                            await dbContext.Database.BeginTransactionAsync();

                            try
                            {
                                // Update the web page section with the sanitized HTML
                                await dbContext.WebPageSections.UpdateAsync(request.PageSectionId, sanitizedHtml);

                                // Commit the transaction
                                await dbContext.Database.CommitTransactionAsync();
                            }
                            catch (Exception ex3)
                            {
                                // Roll back the transaction on failure
                                await dbContext.Database.RollbackTransactionAsync();

                                _logger.LogError(ex3, "Failed to update web page section");

                                return StatusCode(500);
                            }
                        }
                    }
                }
            }

            return Ok("Web page section updated successfully");
        }
    }
}
