    private readonly IHtmlSanitizerService _htmlSanitizerService;
    private readonly IDatabaseContext _databaseContext;

    public PageSectionController(HttpClient httpClient, IHtmlSanitizerService htmlSanitizerService, IDatabaseContext databaseContext)
    {
        _httpClient = httpClient;
        _htmlSanitizerService = htmlSanitizerService;
        _databaseContext = databaseContext;
    }

    [HttpGet]
    public async Task<IActionResult> GetPageSections()
    {
        var pageSections = await _databaseContext.GetPageSectionsAsync();
        return Ok(pageSections);
    }

    [HttpPost]
    public async Task<IActionResult> UpdatePageSection([FromBody]UpdatePageSectionRequest request)
    {
        try
        {
            // Sanitize HTML content using external service
            var sanitizedHtml = await _htmlSanitizerService.SanitizeHtml(request.HtmlContent);

            // Update page section in database
            await _databaseContext.UpdatePageSectionAsync(request.PageSectionId, sanitizedHtml);

            return Ok("Page section updated successfully");
        }
        catch (HttpRequestException ex)
        {
            if (ex.StatusCode == 503) // Service unavailable
            {
                // Retry mechanism for failed sanitization calls
                await RetrySanitizationCall(request);
            }

            return StatusCode(500, "Internal Server Error");
        }
    }

    private async Task RetrySanitizationCall(UpdatePageSectionRequest request)
    {
        var retryCount = 0;

        while (retryCount < 10 && DateTime.Now - _lastRetryTime < TimeSpan.FromHours(1))
        {
            try
            {
                // Retry sanitization call using external service
                var sanitizedHtml = await _htmlSanitizerService.SanitizeHtml(request.HtmlContent);

                // Update page section in database if sanitization successful
                await _databaseContext.UpdatePageSectionAsync(request.PageSectionId, sanitizedHtml);
                return;
            }
            catch (HttpRequestException ex)
            {
                if (ex.StatusCode == 503) // Service unavailable
                {
                    await Task.Delay(1000); // Wait for a second before retrying
                }
            }

            retryCount++;
        }
    }
}

public class UpdatePageSectionRequest
{
    public int PageSectionId { get; set; }
    public string HtmlContent { get; set; }
}
