public:
    class Result {
    public:
        bool isValid;
        std::string output;

        Result(bool valid, const std::string& output) : 
            isValid(valid), output(output) {}
    };

    class Command {
    public:
        virtual ~Command() {}
        virtual void execute() = 0;
        virtual Result getResults() = 0;
    };

    template<typename T>
    class CommandBuilder {
    public:
        template<typename... Args>
        static auto make(Args&&... args) -> std::unique_ptr<Command> {
            return std::make_unique<T>(std::forward<Args>(args)...);
        }
    };

    CommandExecutor();

    void execute(const Command& cmd);

private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<std::function<void()> > commands;
};

class WebServer {
public:
    void handleCommandResult(const CommandExecutor::Result& result) {
        // Render the command output on the web server
    }
};

int main() {
    // Create a web server instance
    WebServer webServer;

    // Define some sample commands
    auto cmd1 = CommandExecutor::CommandBuilder<Command1>().make("ls", "-l");
    auto cmd2 = CommandExecutor::CommandBuilder<Command2>().make("curl", "https://example.com");

    // Start the command executor with the web server
    CommandExecutor executor;
    std::thread thread([&executor, &webServer]() {
        while (true) {
            if (!executor.commands.empty()) {
                auto cmd = std::move(executor.commands.front());
                executor.commands.pop();
                cmd();
            }
            cv.wait(mtx);
        }
    });

    // Execute some commands
    executor.execute(*cmd1);
    executor.execute(*cmd2);

    return 0;
}

class Command1 : public CommandExecutor::Command {
public:
    void execute() override {
        // Simulate command execution
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        output = "ls -l output";
    }

    CommandExecutor::Result getResults() override {
        return {true, output};
    }

private:
    std::string output;
};

class Command2 : public CommandExecutor::Command {
public:
    void execute() override {
        // Simulate command execution
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        output = "curl https://example.com output";
    }

    CommandExecutor::Result getResults() override {
        return {true, output};
    }

private:
    std::string output;
};

CommandExecutor::CommandExecutor() {
    // Initialize the command executor
}

void CommandExecutor::execute(const Command& cmd) {
    commands.emplace([cmd]() {
        try {
            cmd.execute();
            Result result = cmd.getResults();
            if (result.isValid) {
                // Stream the command results to the web server
                webServer.handleCommandResult(result);
            }
        } catch (const std::exception& e) {
            // Handle any exceptions that occur during command execution
            std::cerr << "Error executing command: " << e.what() << std::endl;
        }
    });
    cv.notify_one();
}

