            try {
                Event event = eventQueue.take();
                if (!acknowledgedEvents.compareAndSet(0, 1)) continue;
                processEvent(event);
                acknowledgedEvents.set(1);
            } catch (InterruptedException | Exception e) {
                // Handle exceptions
            }
        }
    }

