    bool processorRunning;
    std::queue<EventLogEntry> processQueue;

    void ProcessBatch();
};

void StreamingDataProcessor::Start() {
    processorThread = new std::thread([this]() { this->Process(); });
    processorRunning = true;
}

void StreamingDataProcessor::Stop() {
    if (processorRunning) {
        processorRunning = false;
        processorThread->join();
        delete processorThread;
    }
}

void StreamingDataProcessor::Put(EventLogEntry entry) {
    processQueue.push(entry);
}

void StreamingDataProcessor::ProcessBatch() {
    // batch processing logic here
}

void StreamingDataProcessor::Process() {
    while (processorRunning) {
        EventLogEntry entry;
        {
            std::unique_lock<std::mutex> lock(processLock);
            if (!processQueue.empty()) {
                entry = processQueue.front();
                processQueue.pop();
            } else {
                processCond.wait(lock, [this] { return processorRunning; });
            }
        }
        ProcessBatch();
    }
}
