#include <map>
#include <unordered_map>
#include <unordered_set>
#include <string>
#include <chrono>
#include <numeric>

namespace CommandExecutor {
    class Framework {
    public:
        Framework() : commandQueue_, availableResources_(5), maxConcurrency_(5000), runningCommands_(0) {}

        void executeCommand(int commandId, std::function<void()> command) {
            // Acquire resource and add to queue
            if (availableResources_ > 0) {
                availableResources_--;
                commandQueue_.emplace(commandId, command);
                if (runningCommands_ < maxConcurrency_) {
                    runningCommands_++;
                    executeNextCommand();
                }
            } else {
                // Resource unavailable, store in pending queue and retry later
                pendingCommands_[commandId] = command;
            }
        }

        void updateResources(int available) {
            availableResources_ = available;
            if (availableResources_ > 0) {
                executeNextCommand();
            }
        }

        void shutDown() {
            // Stop execution, drain queue and release resources
            while (!commandQueue_.empty()) {
                auto commandId = commandQueue_.front().first;
                commandQueue_.pop();
                runningCommands_--;
                // Execute or store command as needed
                if (auto cmdIt = pendingCommands_.find(commandId); cmdIt != pendingCommands_.end()) {
                    cmdIt->second();  // Execute command
                    pendingCommands_.erase(cmdIt);
                }
            }
        }

    private:
        std::priority_queue<std::pair<int, std::function<void()>>> commandQueue_;
        int availableResources_, maxConcurrency_, runningCommands_;

        std::unordered_map<int, std::function<void()"> pendingCommands_;

        void executeNextCommand() {
            if (!commandQueue_.empty()) {
                auto commandId = commandQueue_.top().first;
                commandQueue_.pop();
                runningCommands_++;
                // Execute or store command as needed
                if (auto cmdIt = pendingCommands_.find(commandId); cmdIt != pendingCommands_.end()) {
                    cmdIt->second();  // Execute command
                    pendingCommands_.erase(cmdIt);
                } else {
                    // Command available, execute it
                    commandQueue_.top().second();
                }
            }
        }
    };

    int main() {
        Framework framework;
        // Create a list of commands and execute them
        std::vector<std::function<void()"> commands = ...;  // Initialize with your commands
        for (auto& command : commands) {
            framework.executeCommand(1, command);
        }
        return 0;
    }
