        algorithmFactory_ = AlgorithmFactory::createAlgorithm(name);
    }

    void unloadAlgorithm() {
        algorithmFactory_.reset();
    }

    void performEncryption(const std::string& input, std::string& output) {
        if (algorithmFactory_) {
            algorithmFactory_->performEncryption(input, output);
        } else {
            // Handle error: no algorithm loaded
        }
