def file_size_intervals(file_sizes):
    intervals = {}
    for size in file_sizes:
        if size <= 1024:  # under 1KB
            intervals.setdefault("0-1KB", 0)[0] += 1
        elif size <= 32768:  # under 32KB
            intervals.setdefault("1KB-32KB", 0)[0] += 1
        elif size <= 1048576:  # under 1MB
            intervals.setdefault("32KB-1MB", 0)[0] += 1
        else:
            intervals.setdefault(">1MB", 0)[0] += 1
    return {f"{start}-{end}": count for start, end in intervals}
```']

