    CombatStrategyManager() : attackDatabase(), cache(), cacheExpirationTime(1000) {}

    void loadAttackDatabase(const std::string& databaseUrl) {
        // Load the attack database
        // For simplicity, assume a JSON file containing attacks and their cooldowns
        // Use a library like jsoncpp to parse the file
    }

    void updateAttackCooldowns() {
        for (const auto& [attackName, cooldown] : attackDatabase) {
            if (cooldown < 0) {
                // Attack is off cooldown, add it to the cache
                cache[attackName] = true;
            }
        }
    }

    bool isValidAttack(const std::string& attackName) const {
        return attackDatabase.count(attackName);
    }

    void executeAttack(const std::string& attackName) {
        if (!isValidAttack(attackName)) {
            // Attack not found, handle error
            return;
        }

        if (cache.count(attackName) && cache[attackName]) {
            // Attack is off cooldown and in the cache, use it
            cache.erase(attackName);
            updateAttackCooldowns();
        } else {
            // Attack is on cooldown or not found, wait for cooldown to expire or retry later
            std::this_thread::sleep_for(std::chrono::milliseconds(cooldown));
        }
    }

    void startCombatLoop() {
        while (true) {
            for (const auto& [attackName, cooldown] : attackDatabase) {
                if (cooldown < 0) {
                    // Attack is off cooldown, execute it
                    executeAttack(attackName);
                }
            }
        }
    }

private:
