#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>

class DataPacket {
public:
    int packetID;
    std::string sourceIP;
    std::string destinationIP;
    long timestamp;
    int payloadSize;
};

class PacketManager {
private:
    const int C; // Initial capacity
    const int M; // Maximum size limit

    std::mutex mtx;
    std::condition_variable cv;

    std::queue<DataPacket*> packets;

public:
    PacketManager(int c, int m) : C(c), M(m) {}

    void addPacket(DataPacket* packet) {
        std::unique_lock<std::mutex> lock(mtx);

        if (packets.size() >= C) {
            cv.wait_for(lock, std::chrono::microseconds(1000));
        }

        packets.push(packet);
    }

    DataPacket* getPacket() {
        std::unique_lock<std::mutex> lock(mtx);

        while (packets.empty()) {
            cv.wait_for(lock, std::chrono::microseconds(1000));
        }

        auto packet = packets.front();
        packets.pop();

        return packet;
    }
};
