#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    LOG_TO_FILE,
    LOG_TO_NETWORK,
    LOG_TO_CONSOLE
} loggingMechanism;

typedef struct {
    loggingMechanism mechanism;
    void* fileHandle; // for file logging
    int networkPort; // for network logging
    // add more fields as needed
} loggingConfig;

char* truncateAndLogArray(int** input, int sizeLimit, int* maxLength, void (*logError)(loggingConfig*, const char*), loggingConfig* loggingConfig) {
    if (!input || !*input || **input == 0) return *input ? *input : "";
    int length = strlen(*input);
    if (length <= sizeLimit) return *input;

    char* result = malloc((sizeLimit + 3) * sizeof(char));
    sprintf(result, "%.*s...", sizeLimit, *input);
    free(*input);
    *input = result;
    if (*maxLength < length) {
        logError(loggingConfig, "Array truncated due to exceeding maxLength");
        *maxLength = length;
    }
    return *input;
}
