    // Constructor to initialize the event manager
    IoTEventManager() : kafkaProducer("localhost:9092"), aggregationWindow(1000) {}

    // Start listening for events from Kafka
    void startListening() {
        // Initialize a thread pool to handle multiple threads
        std::vector<std::thread> threads;
        for (int i = 0; i < 4; i++) {
            threads.emplace_back([this]() { consumeEventsFromKafka(); });
        }

        // Start the event loop
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    // Consume events from Kafka and process them
    void consumeEventsFromKafka() {
        kafkaProducer.start();

        while (true) {
            auto event = kafkaProducer.consume();
            if (!event.empty()) {
                processEvent(event);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    // Process an event by aggregating it with other events
    void processEvent(Event& event) {
        // Get the device ID and data from the event
        int deviceId = event.deviceId;
        std::string data = event.data;

        // Aggregate the event with other events for the same device
        auto& aggregationQueue = aggregates[deviceId];
        aggregationQueue.push(event);

        // Check if the aggregation window has been exceeded
        if (aggregationQueue.size() >= aggregationWindow) {
            // Process the aggregated events and reset the queue
            processAggregatedEvents(deviceId);
            aggregationQueue.clear();
        }
    }

