import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class VideoStreamProcessor {

    public static void processVideoStream(String streamId, double initialAggregationValue, Callback callback) {
        // Create an ExecutorService with a fixed thread pool size
        ExecutorService executor = Executors.newFixedThreadPool(5);

        // Wrap the processing logic in a Callable task
        Callable<Void> processStreamTask = () -> {
            // Simulate network operations and data processing
            double processedAggregationValue = initialAggregationValue * 2;
            System.out.println("Processed stream " + streamId + ": " + processedAggregationValue);

            // Call the callback function with the processed result
            callback.onResult(streamId, processedAggregationValue);
            return null;
        };

        // Submit the task to the ExecutorService and get a Future object
        Future<Void> processStreamFuture = executor.submit(processStreamTask);

        try {
            // Get the result of the processing task using the Future.get() method
            processStreamFuture.get();
        } catch (InterruptedException | ExecutionException e) {
            System.out.println("Error processing stream " + streamId);
        }

        // Shut down the ExecutorService
        executor.shutdown();
    }
}

interface Callback {
    void onResult(String streamId, double aggregationValue);
}
