using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Threading.Tasks;

namespace RealTimeUpdateEndpoint
{
    [ApiController]
    [Route("api/[controller]")]
    public class PageSectionController : ControllerBase
    {
        private readonly IHtmlSanitizer _htmlSanitizer;
        private readonly IPageSectionService _pageSectionService;
        private readonly ICacheManager _cacheManager;

        public PageSectionController(IHtmlSanitizer htmlSanitizer, IPageSectionService pageSectionService, ICacheManager cacheManager)
        {
            _htmlSanitizer = htmlSanitizer;
            _pageSectionService = pageSectionService;
            _cacheManager = cacheManager;
        }

        [HttpPost]
        [Route("update")]
        public async Task<IActionResult> UpdatePageSection([FromBody] PageSectionUpdateRequest request)
        {
            // Sanitize HTML content using external service
            var sanitizedContent = await _htmlSanitizer.Sanitize(request.Content);

            // Validate page section ID and element IDs
            if (!await IsValidPageSectionAndElements(request.PageSectionId, request.Elements))
            {
                return BadRequest("Invalid page section or elements");
            }

            // Update page section in database using transactional integrity
            await _pageSectionService.UpdatePageSectionAsync(request.PageSectionId, sanitizedContent);

            // Invalidate cache for the updated page section
            await _cacheManager.InvalidateCacheForPageSection(request.PageSectionId);

            return Ok("Page section updated successfully");
        }

        private async Task<bool> IsValidPageSectionAndElements(string pageSectionId, PageElement[] elements)
        {
            // Call external service to validate page section ID and element IDs
            var validationResult = await _pageSectionService.ValidatePageSectionAndElementsAsync(pageSectionId, elements);

            return validationResult.IsValid;
        }
    }

    public class PageSectionUpdateRequest
    {
        public string PageSectionId { get; set; }
        public string Content { get; set; }
        public PageElement[] Elements { get; set; }
    }

    public class PageElement
    {
        public int Id { get; set; }
        public string HtmlContent { get; set; }
    }
}
