    int frequency_band; // Frequency band for transmission
    int modulation_scheme; // Modulation scheme used
} TX_CELL_CONTEXT_T;

// Define structure to hold dynamic array of TX cells
typedef struct {
    TX_CELL_CONTEXT_T *cells;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TX_CELL_ARRAY_T;

// Function to initialize the dynamic array
TX CELL_ARRAY_T* tx_cell_array_init(size_t initial_capacity) {
    TX_CELL_ARRAY_T* array = (TX_CELL_ARRAY_T*)malloc(sizeof(TX_CELL_ARRAY_T));
    array->cells = (TX_CELL_CONTEXT_T*)malloc(initial_capacity * sizeof(TX_CELL_CONTEXT_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Function to add a new cell to the dynamic array
int tx_cell_array_add(TX_CELL_ARRAY_T* array, TX_CELL_CONTEXT_T* new_cell) {
    if (array->size >= array->capacity) {
        // Double the capacity if full
        size_t new_capacity = 2 * array->capacity;
        array->cells = (TX_CELL_CONTEXT_T*)realloc(array->cells, new_capacity * sizeof(TX_CELL_CONTEXT_T));
        array->capacity = new_capacity;
    }
    array->cells[array->size] = *new_cell;
    array->size++;
    return 0;
}

// Function to remove a cell from the dynamic array
int tx_cell_array_remove(TX_CELL_ARRAY_T* array, int ci) {
    for (size_t i = 0; i < array->size; i++) {
        if (array->cells[i].ci == ci) {
            memmove(&array->cells[i], &array->cells[i+1], (array->size - i - 1) * sizeof(TX_CELL_CONTEXT_T));
            array->size--;
            return 0;
        }
    }
    return -1; // Cell not found
}

// Function to validate cell configuration parameters
