    return 0;
}

// Function to execute a command in the background using fork and wait system calls
int execute_command_in_background(const char* command) {
    pid_t child_pid = fork();
    if (child_pid == -1) {
        return 0; // Failed to create child process
    }
    else if (child_pid > 0) {
        int status;
        wait(&status);
        return WEXITSTATUS(status); // Return the status of the child process
