// Define a class to manage IoT devices
class IoTGateway {
public:
    // Constructor
    IoTGateway() : connectedDevices(0) {}

    // Connect a new device
    void connectDevice(int deviceId, std::string deviceName) {
        // Insert device into vector
        devices_.emplace_back(deviceId, deviceName);
        connectedDevices++;

        // Start listening for data from the device
        std::thread([this, deviceId]() {
            receiveData(deviceId);
        }).detach();
    }

    // Disconnect a device
    void disconnectDevice(int deviceId) {
        // Remove device from vector
        devices_.erase(std::remove_if(devices_.begin(), devices_.end(),
            [&deviceId](const auto& device) { return device.first == deviceId; }),
        devices_.end());
        connectedDevices--;

        // Stop listening for data from the device
    }

    // Handle incoming data from a device
    void receiveData(int deviceId, std::string data) {
        // Process the data and store it in a database or cloud service
        processAndStoreData(deviceId, data);

        // Notify other devices of the updated state (e.g., via MQTT)
        notifyDevices();
