    public function getSessionToken($username, $password): string {
        // Implement session token generation logic
        foreach ($this->providerManagers as $manager) {
            if ($manager instanceof OAuthSessionManager && $manager->validateAuthentication($username, $password)) {
                return $manager->getSessionToken($username, $password);
            }
            elseif ($manager instanceof OpenIDSessionManager && $manager->validateAuthentication($username, $password)) {
                return $manager->getSessionToken($username, $password);
