// Define the connection pool class
public class ConnectionPool {
    private Map<String, Connection> connections;

    public ConnectionPool() {
        this.connections = new HashMap<>();
    }

    public Connection getConnection(String source) {
        Connection conn = connections.get(source);
        if (conn == null) {
            // Establish a new connection to the external system
            conn = establishConnection(source);
            connections.put(source, conn);
        }
        return conn;
    }

    public void close() {
        // Close all open connections
        for (Connection conn : connections.values()) {
            conn.close();
        }
    }

