// Define the distributed task queue class
public class DistributedTaskQueue {
    public List<PipelineTask> tasks;

    public DistributedTaskQueue() {
        this.tasks = new ArrayList<>();
    }

    public void enqueue(PipelineTask task) {
        // Add the task to the distributed task queue
        tasks.add(task);
    }

    public void close() {
        // Close all open tasks in the distributed task queue
        for (PipelineTask task : tasks) {
            task.run();
        }
    }
}

// Define the command-line interface class
public class CLI {
    public static void main(String[] args) {
        // Parse the pipeline configuration from command-line arguments
        PipelineConfig config = new PipelineConfig();
        config.inputSources = parseArgs(args, "--input-source");
        config.transformationRules = parseArgs(args, "--transformation-rule");
        config.outputDestinations = parseArgs(args, "--output-destination");

        // Run the pipeline processor
        PipelineRunner runner = new PipelineRunner(config);
        runner.run();
    }

    private static Map<String, String> parseArgs(String[] args, String option) {
        Map<String, String> options = new HashMap<>();
        for (int i = 0; i < args.length; i++) {
            if (args[i].startsWith(option)) {
                options.put(option.substring(1), args[i + 1]);
                i++;
            }
        }
        return options;
    }
}
