// Define a BatchDataManager class to manage dynamic dataset of string items across multiple regions
class BatchDataManager {
private:
    std::unordered_map<std::string, std::vector<std::string>> data_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;

public:
    // Constructor to initialize the BatchDataManager instance
    BatchDataManager() : data_(), mutex_(), condition_() {}

    // Method to insert string items into the dataset based on specified criteria
    void Insert(const std::string& key, const std::vector<std::string>& values) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            for (const auto& value : values) {
                data_[key].push_back(value);
            }
        }
        condition_.notify_all();
    }

    // Method to append string items into the dataset based on specified criteria
    void Append(const std::string& key, const std::vector<std::string>& values) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            for (const auto& value : values) {
                data_[key].push_back(value);
            }
        }
        condition_.notify_all();
    }

    // Method to delete string items from the dataset based on specified criteria
    void Delete(const std::string& key, const std::vector<std::string>& values) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            for (const auto& value : values) {
                data_[key].erase(std::remove(data_[key].begin(), data_[key].end(), value), data_[key].end());
            }
        }
        condition_.notify_all();
    }

    // Method to retrieve string items from the dataset based on specified criteria
    std::vector<std::string> Retrieve(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);
        return data_.at(key);
    }
};

