    public class DynamicDatabaseConnection
    {
        private readonly Dictionary<string, SqlConnection> _connections = new();
        private readonly HashSet<string> _connectedDatabases = new();

        public async Task ConnectAsync(string databaseName)
        {
            if (!_connectedDatabases.Contains(databaseName))
            {
                // Check if the connection string is valid
                string connectionString = GetConnectionString(databaseName);
                if (string.IsNullOrEmpty(connectionString))
                    throw new InvalidOperationException("Invalid connection string");

                // Create a new connection pool for this database
                _connections.Add(databaseName, new SqlConnection(connectionString));
                await _connections[databaseName].OpenAsync();
                _connectedDatabases.Add(databaseName);
            }
        }

        public async Task ExecuteQueryAsync(string databaseName, string query)
        {
            if (!_connectedDatabases.Contains(databaseName))
                throw new InvalidOperationException("Database not connected");

            using (SqlConnection connection = _connections[databaseName])
            {
                await connection.OpenAsync();
                SqlCommand command = new SqlCommand(query, connection);
                // Parameterized query
                // ...
                await command.ExecuteNonQueryAsync();
            }
        }

        public async Task DisconnectAsync(string databaseName)
        {
            if (_connectedDatabases.Contains(databaseName))
            {
                _connections[databaseName].Close();
                _connectedDatabases.Remove(databaseName);
            }
        }

        private string GetConnectionString(string databaseName)
