        public uint RnTi { get; set; }
        public byte[] Data { get; set; }
    }

    public class RntiValidatorService
    {
        private readonly ILogger<RntiValidatorService> _logger;
        private readonly IConnectionManager _connectionManager;
        private readonly IConfigurationRoot _configuration;

        public RntiValidatorService(ILogger<RntiValidatorService> logger, IConnectionManager connectionManager, IConfigurationRoot configuration)
        {
            _logger = logger;
            _connectionManager = connectionManager;
            _configuration = configuration;
        }

        public async Task ProcessNfaApiCrcIndicationPduTsAsync(List<NfaApiCrcIndicationPduT> pduTs, CancellationToken cancellationToken)
        {
            foreach (var pduT in pduTs)
            {
                await ValidateAndProcessPduTAsync(pduT, cancellationToken);
            }
        }

        private async Task ValidateAndProcessPduTAsync(NfaApiCrcIndicationPduT pduT, CancellationToken cancellationToken)
        {
            // Check if RnTi value is duplicate
            if (await IsRnTiValueDuplicateAsync(pduT.RnTi))
            {
                _logger.LogInformation("Duplicate RnTi value found: {RnTi}", pduT.RnTi);
                // Handle duplicate RnTi value
            }
            else
            {
                // Populate other fields with random values
                pduT.Data = new byte[16];
                using (var rng = RandomNumberGenerator.Create())
                {
                    for (int i = 0; i < pduT.Data.Length; i++)
                    {
                        pduT.Data[i] = (byte)rng.Next(0, 256);
                    }
                }

                // Process pduT asynchronously
                await _connectionManager.ProcessPduTAsync(pduT, cancellationToken);
            }
        }

        private async Task<bool> IsRnTiValueDuplicateAsync(uint rnti)
        {
            // Check if RnTi value is duplicate in the database
            using (var connection = _connectionManager.GetConnection())
            {
                var query = "SELECT COUNT(*) FROM NfaApiCrcIndicationPduTs WHERE RnTi = @RnTi";
                var command = new SqlCommand(query, connection);
                command.Parameters.AddWithValue("@RnTi", rnti);

                var count = (int)await command.ExecuteScalarAsync();
                return count > 0;
            }
        }
    }

    public interface IConnectionManager
    {
        IDbConnection GetConnection();
        Task ProcessPduTAsync(NfaApiCrcIndicationPduT pduT, CancellationToken cancellationToken);
    }
}
