using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using System.Linq;
using System.Collections.Generic;

namespace MyApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ResourcesController : ControllerBase
    {
        private readonly IResourceRepository _repository;
        private readonly INotificationService _notificationService;
        private readonly IExternalValidationService _validationService;
        private readonly IPredictiveUpdateModel _predictiveModel;

        public ResourcesController(IResourceRepository repository, 
            INotificationService notificationService,
            IExternalValidationService validationService,
            IPredictiveUpdateModel predictiveModel)
        {
            _repository = repository;
            _notificationService = notificationService;
            _validationService = validationService;
            _predictiveModel = predictiveModel;
        }

        [HttpPut]
        public async Task<IActionResult> UpdateResource([FromBody] Resource resource)
        {
            if (!await ValidateResource(resource))
                return BadRequest("Invalid resource");

            try
            {
                await _repository.UpdateAsync(resource);
                await _notificationService.NotifyUpdate(resource);
                return Ok();
            }
            catch (Exception ex)
            {
                await _predictiveModel.PredictAndCorrect(ex, resource);
                return StatusCode(500, "Error updating resource");
            }
        }

        [HttpDelete]
        public async Task<IActionResult> DeleteResource([Route("{id}")] string id)
        {
            try
            {
                var resource = await _repository.GetAsync(id);
                if (resource == null)
                    return NotFound("Resource not found");

                if (!await EnforceSoftDelete(resource))
                    return BadRequest("Cannot delete soft-deleted resource");

                await _repository.DeleteAsync(resource);
                await _notificationService.NotifyDelete(resource);
                return Ok();
            }
            catch (Exception ex)
            {
                await _predictiveModel.PredictAndCorrect(ex, id);
                return StatusCode(500, "Error deleting resource");
            }
        }

        [HttpDelete]
        public async Task<IActionResult> DeleteResources([FromBody] List<string> ids)
        {
            try
            {
                var resources = await _repository.GetManyAsync(ids);
                if (!resources.Any())
                    return Ok();

                foreach (var resource in resources)
                {
                    await DeleteResource(resource.Id);
                }

                return Ok();
            }
            catch (Exception ex)
            {
                await _predictiveModel.PredictAndCorrect(ex, ids);
                return StatusCode(500, "Error deleting resources");
            }
        }

        private async Task<bool> ValidateResource(Resource resource) =>
            await _validationService.ValidateAsync(resource);

        private async Task<bool> EnforceSoftDelete(Resource resource) =>
            await _repository.EnforceSoftDeleteAsync(resource);
    }
}
