from flask import Flask, jsonify, request, abort
import json
from flask_api import status
from flask_sqlalchemy import SQLAlchemy
from flask_marshmallow import Marshmallow
from marshmallow import fields
from marshmallow.exceptions import ValidationError
from flask_cors import CORS

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///api.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)
ma = Marshmallow(app)

# Define models
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)

class Order(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    total = db.Column(db.Float, nullable=False)

# Define API endpoints
@app.route('/users', methods=['GET'])
def get_users():
    users = User.query.all()
    return jsonify([u.serialize() for u in users])

@app.route('/orders', methods=['GET'])
def get_orders():
    orders = Order.query.all()
    return jsonify([o.serialize() for o in orders])

@app.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    user = User.query.get(user_id)
    if not user:
        abort(status.HTTP_404_NOT_FOUND, 'User not found')
    return jsonify(user.serialize())

@app.route('/orders/<int:order_id>', methods=['GET'])
def get_order(order_id):
    order = Order.query.get(order_id)
    if not order:
        abort(status.HTTP_404_NOT_FOUND, 'Order not found')
    return jsonify(order.serialize())

@app.route('/users', methods=['POST'])
def create_user():
    data = request.get_json()
    try:
        user = User(name=data['name'])
        db.session.add(user)
        db.session.commit()
        return jsonify(user.serialize()), status.HTTP_201_CREATED
    except ValidationError as e:
        abort(status.HTTP_400_BAD_REQUEST, str(e))

@app.route('/orders', methods=['POST'])
def create_order():
    data = request.get_json()
    try:
        order = Order(user_id=data['user_id'], total=data['total'])
        db.session.add(order)
        db.session.commit()
        return jsonify(order.serialize()), status.HTTP_201_CREATED
    except ValidationError as e:
        abort(status.HTTP_400_BAD_REQUEST, str(e))

@app.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    user = User.query.get(user_id)
    if not user:
        abort(status.HTTP_404_NOT_FOUND, 'User not found')
    data = request.get_json()
    try:
        user.name = data['name']
        db.session.commit()
        return jsonify(user.serialize()), status.HTTP_200_OK
    except ValidationError as e:
        abort(status.HTTP_400_BAD_REQUEST, str(e))

@app.route('/orders/<int:order_id>', methods=['PUT'])
def update_order(order_id):
    order = Order.query.get(order_id)
    if not order:
        abort(status.HTTP_404_NOT_FOUND, 'Order not found')
    data = request.get_json()
    try:
        order.total = data['total']
        db.session.commit()
        return jsonify(order.serialize()), status.HTTP_200_OK
    except ValidationError as e:
        abort(status.HTTP_400_BAD_REQUEST, str(e))

@app.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    user = User.query.get(user_id)
    if not user:
        abort(status.HTTP_404_NOT_FOUND, 'User not found')
    db.session.delete(user)
    db.session.commit()
    return jsonify({'message': 'User deleted'}), status.HTTP_200_OK

@app.route('/orders/<int:order_id>', methods=['DELETE'])
def delete_order(order_id):
    order = Order.query.get(order_id)
    if not order:
        abort(status.HTTP_404_NOT_FOUND, 'Order not found')
    db.session.delete(order)
    db.session.commit()
    return jsonify({'message': 'Order deleted'}), status.HTTP_200_OK

if __name__ == '__main__':
    app.run(debug=True)

# Define serialization
class UserSchema(ma.Schema):
    class Meta:
        fields = ('id', 'name')

user_schema = UserSchema()

class OrderSchema(ma.Schema):
    class Meta:
        fields = ('id', 'total')

order_schema = OrderSchema()
