    private Cache<String, Map<String, Object>> marketDataCache;
    private ExecutorService executorService;

    public MarketDataLibrary() {
        // Initialize cache with a staleness-based eviction policy
        marketDataCache = CacheBuilder.newBuilder()
                .maximumSize(1000000) // Set the maximum size of the cache
                .expireAfterAccess(60, TimeUnit.SECONDS) // Expire entries after 1 minute of inactivity
