// comment.service.ts
import { Injectable } from '@nestjs/common';
import * as WebSocket from 'ws';
import { SSE } from 'sse-stream';
import { CommentModerationService } from './comment-moderation.service';
import { CommentRepository } from './comment.repository';

@Injectable()
export class CommentService {
  private wss: WebSocket.Server;
  private sse: SSE;

  constructor(
    private readonly commentRepository: CommentRepository,
    private readonly commentModerationService: CommentModerationService
  ) {}

  setupRealTimeComments() {
    this.wss = new WebSocket.Server({ port: 8081 });
    this.sse = new SSE();

    this.wss.on('connection', (ws) => {
      ws.on('message', (message) => {
        const commentId = parseInt(message);
        this.commentRepository.getComment(commentId).then((comment) => {
          if (comment) {
            // Send updated comment to connected clients
            this.sse.send(`comment:${JSON.stringify(comment)}`);
          }
        });
      });

      ws.on('close', () => {
        console.log('Client disconnected');
      });
    });
  }

  async createComment(comment: any) {
    try {
      const result = await this.commentRepository.createComment(comment);
      // Send created comment to connected clients
      this.sse.send(`comment:${JSON.stringify(result)}`);
    } catch (error) {
      console.error(error);
    }
  }

  async updateComment(commentId: number, updatedComment: any) {
    try {
      const result = await this.commentRepository.updateComment(commentId, updatedComment);
      // Send updated comment to connected clients
      this.sse.send(`comment:${JSON.stringify(result)}`);
    } catch (error) {
      console.error(error);
    }
  }

  async integrateWithModerationService() {
    setInterval(() => {
      try {
        const moderationResult = await this.commentModerationService.moderateComments();
        // Handle moderation results
      } catch (error) {
        console.error(error);
      }
    }, 1000);

    // Asynchronous request handling with retries and circuit breaker patterns
    this.commentModerationService.setModerationAPI('https://moderation-service.com/api/moderate');
  }

  async optimizePerformance() {
    // Implement dynamic caching eviction policies based on user activity patterns and comment popularity
    // Monitor performance metrics and dynamically adjust caching strategies and database query plans to optimize for both latency and cost
  }

  async validateComment(comment: any) {
    try {
      const result = await this.commentRepository.validateComment(comment);
      return result;
    } catch (error) {
      console.error(error);
      throw error;
    }
  }
}
