export class CommentRepository {
  async createComment(comment: any): Promise<any> {
    try {
      const result = await db.comments.insertOne(comment);
      return result.ops[0];
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  async updateComment(commentId: number, updatedComment: any): Promise<any> {
    try {
      const result = await db.comments.updateOne({ _id: commentId }, { $set: updatedComment });
      return result.result.ok === 1;
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  async getComment(commentId: number): Promise<any> {
    try {
      const result = await db.comments.findOne({ _id: commentId });
      return result;
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  async validateComment(comment: any): Promise<any> {
    try {
      // Validate comment against content policies, format correctness, and potential security threats
      const result = await db.comments.validateOne(comment);
      return result;
    } catch (error) {
      console.error(error);
      throw error;
    }
  }
}
