const express = require('express');
const app = express();
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;
const { fork } = require('child_process');

if (cluster.isMaster) {
  console.log(`Worker ${process.pid} is master`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died.`);
  });
} else {
  const worker = fork('path/to/worker.js');

  // Handle messages from the main process.
  worker.on('message', (message) => {
    console.log(`Received message from master: ${message}`);
  });

  // Send a message to the main process.
  worker.send({ type: 'ping' });
}

app.get('/load-module', (req, res) => {
  const moduleName = req.query.moduleName;
  const moduleVersion = req.query.moduleVersion;

  if (!moduleName || !moduleVersion) {
    return res.status(400).send({ error: 'Module name and version are required.' });
  }

  // Load the module from the disk.
  const modulePath = `path/to/modules/${moduleName}/${moduleVersion}.js`;
  const moduleCode = fs.readFileSync(modulePath, 'utf8');

  // Execute the module in a worker thread.
  const worker = fork('path/to/worker.js');
  worker.send({ type: 'load', code: moduleCode });

  res.send({ message: `Loaded module ${moduleName}@${moduleVersion}` });
});

app.listen(3000, () => {
  console.log('Server listening on port 3000.');
});
