async fn create_directory() -> Result<String, Box<dyn std::error::Error>> {
    let dir_path = env::var("NEW_DIRECTORY_PATH").unwrap_or_else(|_| {
        let mut path = PathBuf::from("/tmp/my_service");
        if !path.exists() {
            path.create_dir_all()?;
        }
        path.to_str().unwrap().to_string()
    });

    // Ensure the directory is created safely under concurrency
    tokio::fs::create_dir_all(&dir_path).await?;

    Ok(dir_path.clone())
}

