// rust_user_management.rs
use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex};
use std::thread;

pub struct UserManager {
    users: Arc<Mutex< HashMap<String, User>>>,
}

impl UserManager {
    pub fn new() -> Self {
        UserManager {
            users: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn create_user(&self, user: &User) {
        self.users.lock().unwrap().insert(user.id.clone(), user.clone());
    }

    pub fn get_user(&self, id: &str) -> Option<&User> {
        self.users.lock().unwrap().get(id)
    }

    pub fn update_user(&self, user: &User) {
        if let Some(mut users) = self.users.lock().map(|mut users| users) {
            if let Some(user) = users.get_mut(user.id.as_str()) {
                *user = user.clone();
            }
        }
    }

    pub fn delete_user(&self, id: &str) {
        if let Some(mut users) = self.users.lock().map(|mut users| users) {
            users.remove(id);
        }
    }
}

#[derive(Debug)]
pub struct User {
    pub id: String,
    pub name: String,
    pub email: String,
    pub password: String,
}

