typedef struct Transaction {
    int age;
    double weighted_sum;
} Transaction;

int filter_transactions(Transaction* transactions, int num_transactions) {
    int max_weighted_sum = 0;
    int transaction_id = -1;

    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i].age > 3 && transactions[i].weighted_sum > max_weighted_sum) {
            max_weighted_sum = transactions[i].weighted_sum;
            transaction_id = i;
        }
    }

    return transaction_id;
}

int main() {
