    int num_transactions = ...; // Get number of transactions

    int result = filter_transactions(transactions, num_transactions);

    if (result != -1) {
        printf("Maximum weighted sum: %.2f\n", transactions[result].weighted_sum);
        printf("Corresponding transaction ID: %d\n", result);
    } else {
        printf("No matching transactions found.\n");
    }

    return 0;
}
