using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

namespace DynamicImageAndValueProcessor
{
    public class ImageProcessor
    {
        private readonly ICalibrationService _calibrationService;
        private readonly Dictionary<string, TIFFImage> _imageCache = new();

        public ImageProcessor(ICalibrationService calibrationService)
        {
            _calibrationService = calibrationService;
        }

        public async Task<TIFFImage> ProcessTIFFImageAsync(string imageUri)
        {
            if (_imageCache.TryGetValue(imageUri, out var cachedImage))
                return cachedImage;

            try
            {
                var tiffImage = await _calibrationService.GetMetadataFromCalibrationServiceAsync(imageUri);
                _imageCache.Add(imageUri, tiffImage);
                return tiffImage;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing image: {ex.Message}");
                throw;
            }
        }

        public class TIFFImage
        {
            public int BitsPerSample { get; set; }
            public int SamplesPerPixel { get; set; }
            public List<string> ExtraSamples { get; set; }
        }
    }

    public interface ICalibrationService
    {
        Task<TIFFImageMetadata> GetMetadataFromCalibrationServiceAsync(string imageUri);
    }

    public class RandomValueGenerator
    {
        private readonly int _seed;

        public RandomValueGenerator(int seed)
        {
            _seed = seed;
        }

        public async Task<int> GenerateRandomIntAsync()
        {
            return await GenerateRandomNumberAsync(_seed, 0, int.MaxValue);
        }

        public async Task<float> GenerateRandomFloatAsync()
        {
            return await GenerateRandomNumberAsync(_seed, 0f, float.MaxValue);
        }

        private async Task<T> GenerateRandomNumberAsync<T>(int seed, T min, T max) where T : IComparable
        {
            try
            {
                var random = new Random(seed);
                while (true)
                {
                    var value = (T)random.NextDouble() * (max - min) + min;
                    if (value.CompareTo(min) >= 0 && value.CompareTo(max) <= 0)
                        return value;
                }
            }
            catch
            {
                Console.WriteLine("Error generating random number");
                throw;
            }
        }
    }
}
