#include <mutex>
#include <condition_variable>
#include <memory>
#include <map>
#include <set>
#include <deque>
#include <queue>

class DynamicNetworkResourceManager {
public:
    DynamicNetworkResourceManager();

    void allocateBandwidth(size_t request);
    void allocateCPUCore(size_t request);

private:
    std::mutex resourceMutex;
    std::condition_variable limitCondition;

    std::map<std::string, size_t> bandwidthLimits;
    std::map<std::string, size_t> cpuCoreLimits;

    std::set<std::thread::id> activeThreads;
    std::deque<std::unique_ptr<std::thread>> threadPool;

    void updateLimits();
    void checkLimit(size_t request);
};

DynamicNetworkResourceManager::DynamicNetworkResourceManager() {
    // Initialize limits from external configuration service
    updateLimits();
}

void DynamicNetworkResourceManager::allocateBandwidth(size_t request) {
    std::unique_lock<std::mutex> lock(resourceMutex);
    checkLimit(request);
    if (request > 0 && activeThreads.size() < bandwidthLimits["bandwidth"]) {
        // Allocate bandwidth
        for (size_t i = 0; i < request; ++i) {
            threadPool.emplace_back([this]() {
                while (!activeThreads.insert(std::this_thread::get_id()).second) {
                    std::this_thread::sleep_for(std::chrono::microseconds(1));
                }
                // Simulate resource usage
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            });
        }
    } else {
        // Reject overcommitment request
