namespace Apigateway
{
    public class Startup
    {
        private readonly IWebHostEnvironment _env;
        private readonly IConfigurationRoot _config;

        public Startup(IWebHostEnvironment env, IConfigurationRoot config)
        {
            _env = env;
            _config = config;
        }

        // This method gets called by the runtime. Use this method to configure the HTTP request pipeline.
        public void Configure(IApplicationBuilder app, IWebHostEnvironment env, ILoggerFactory loggerFactory)
        {
            loggerFactory.AddConsole(Configuration.GetSection("Logging"));

            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }

    public class PolicyEngine
    {
        // Define routing policies based on service health, load, and availability
        public void ApplyPolicy(Route route)
        {
            if (route.ServiceHealth == ServiceHealth.Offline)
            {
                route.FailoverTarget = "AlternateService";
            }
            else if (route.Load > 0.5f)
            {
                route.CircuitBreaker = true;
            }
            else
            {
                route.Target = route.DefaultTarget;
            }
        }
    }

    public class RequestRouter
    {
        private readonly PolicyEngine _policyEngine;

        public RequestRouter(PolicyEngine policyEngine)
        {
            _policyEngine = policyEngine;
        }

        public async Task<Route> RouteRequest(HttpRequest request)
        {
            var route = await GetRouteForRequest(request);
            _policyEngine.ApplyPolicy(route);

            return route;
        }
    }

    public class CacheManager
    {
        private readonly RedisConnection _redis;

        public CacheManager(RedisConnection redis)
        {
            _redis = redis;
        }

        public async Task InvalidateCache(string key)
        {
            await _redis.DeleteAsync(key);
        }
    }

    public class ErrorHandlingMiddleware
    {
        private readonly ILoggerFactory _loggerFactory;

        public ErrorHandlingMiddleware(ILoggerFactory loggerFactory)
        {
            _loggerFactory = loggerFactory;
        }

        public async Task InvokeAsync(HttpContext context, RequestDelegate next)
        {
            try
            {
                await next(context);
            }
            catch (Exception ex)
            {
                // Handle transient errors with retries and circuit breaking
                if (ex is TransientError)
                {
                    // Retry or circuit break based on policy
                }
                else
                {
                    // Log and notify stakeholders for prolonged failures
                    _loggerFactory.CreateLogger("ErrorHandling").LogError(ex);
                }
            }
        }
    }

    public class MonitoringMiddleware
    {
        private readonly IMetrics _metrics;

        public MonitoringMiddleware(IMetrics metrics)
        {
            _metrics = metrics;
        }

        public async Task InvokeAsync(HttpContext context, RequestDelegate next)
        {
            try
            {
                await next(context);
                // Update metrics for request processing time, error rate, and service utilization
                _metrics.UpdateMetrics(context.Request);
            }
            catch (Exception ex)
            {
                // Log errors and update metrics
                _loggerFactory.CreateLogger("ErrorHandling").LogError(ex);
            }
        }
    }

    public class Apigateway : IWebHostBuilder
    {
        private readonly IConfigurationRoot _config;

        public Apigateway(IConfigurationRoot config)
        {
            _config = config;
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env, ILoggerFactory loggerFactory)
        {
            // Configure API gateway with policy engine, request router, cache manager, error handling middleware, and monitoring middleware
            app.UseMiddleware<ErrorHandlingMiddleware>();
            app.UseMiddleware<MonitoringMiddleware>();

            // Configure distributed cache using Redis
            var redis = new RedisConnection(_config["RedisConnectionString"]);
            app.UseCacheManager(redis);

            // Configure policy engine with configurable routing policies
            var policyEngine = new PolicyEngine();
            app.UseRequestRouter(policyEngine);
        }
    }
}
