class Serializable {
public:
    virtual ~Serializable() {}
};

template<typename T>
std::unique_ptr<T> deserialize(const std::vector<char>& data) {
    if (!data.size()) {
        return nullptr;
    }

    auto deserialized = std::make_unique<T>();
    if (!deserialized->deserialize(data)) {
        throw std::runtime_error("Failed to deserialize object");
    }
    return deserialized;
}

class MyObject : public Serializable {
public:
    bool deserialize(const std::vector<char>& data) {
        std::istringstream iss(std::string(data.begin(), data.end()));
        iss >> *this; // Assuming a specific serialization format
        return true;
    }

private:
    int id;
    std::string name;

    friend std::istream& operator>>(std::istream& is, MyObject& obj) {
        is >> obj.id >> obj.name;
        return is;
    }
};

MyObject* deserializeAndCreate(const std::vector<char>& data) {
    auto deserialized = deserialize<MyObject>(data);
    if (!deserialized) {
        return nullptr;
    }
    return deserialized.get();
}
