    public class HashingService : IHashingService
    {
        private readonly ICachingService _cache;
        private readonly IDependencyService _dependencies;
        private readonly IDistributedWorkerService _distributedWorkers;
        private readonly IValidationService _validation;

        public HashingService(ICachingService cache, IDependencyService dependencies, IDistributedWorkerService distributedWorkers, IValidationService validation)
