        public async Task<string> Sha256HashAsync(string input)
        {
            var hash = _dependencies.GetSha256().ComputeHash(Encoding.UTF8.GetBytes(input));
            return BitConverter.ToString(hash).Replace("-", string.Empty);
        }

        public async Task<string> HashAsync(string input, HashAlgorithm algorithm)
        {
            using (var hash = algorithm.Create())
            {
                hash.TransformFinalBlock(Encoding.UTF8.GetBytes(input), 0, Encoding.UTF8.GetByteCount(input));
                return Convert.ToBase64String(hash.HashValue);
            }
        }

        public async Task<string> DistributedHashAsync(string input, HashAlgorithm algorithm)
        {
            var task = _distributedWorkers.QueueWork(() => Md5HashAsync(input));
            return await task;
        }
    }
}
