const express = require('express');
const app = express();
const geocoder = require('geocoder');
const axios = require('axios');
const { retry, backoff } = require('backoff');

app.use(express.json());

const WEATHER_API_URL = 'https://weather-api.com/weather';
const TRAFFIC_API_URL = 'https://traffic-api.com/traffic';
const GEOCODER_API_URL = 'https://geocoder-api.com/geocode';

// Geocoding API rate limiting
const geocoderRateLimit = {
  retries: 3,
  delay: backoff.linear(1000, 5000),
};

// Weather and traffic API rate limiting
const weatherRateLimit = {
  retries: 3,
  delay: backoff.linear(2000, 6000),
};

app.get('/weather', async (req, res) => {
  const { address } = req.query;
  try {
    // Geocode the address
    const geocoderResult = await geocoder(GEOCODER_API_URL, { q: address });
    if (!geocoderResult.ok) {
      return res.status(400).send({ error: 'Geocoding failed' });
    }
    const lat = geocoderResult.result.lat;
    const lng = geocoderResult.result.lng;

    // Fetch weather data
    const weatherResponse = await retry(() => axios.get(`${WEATHER_API_URL}?lat=${lat}&lng=${lng}`), {
      maxAttempts: 3,
      delay: backoff.linear(1000, 5000),
    });
    if (!weatherResponse.ok) {
      return res.status(400).send({ error: 'Weather API failed' });
    }
    const weatherData = await weatherResponse.data;

    // Fetch traffic data
    const trafficResponse = await retry(() => axios.get(`${TRAFFIC_API_URL}?lat=${lat}&lng=${lng}`), {
      maxAttempts: 3,
      delay: backoff.linear(1000, 5000),
    });
    if (!trafficResponse.ok) {
      return res.status(400).send({ error: 'Traffic API failed' });
    }
    const trafficData = await trafficResponse.data;

    // Combine weather and traffic data
    return res.json({ weather: weatherData, traffic: trafficData });
  } catch (error) {
    console.error(error);
    return res.status(500).send({ error: 'Internal Server Error' });
  }
});

app.listen(3000, () => {
  console.log('Weather and Traffic Microservice listening on port 3000');
});
