#[tokio::main]
async fn main() {
    let rt = TokioRuntime::new().unwrap();
    env_logger::init_from_env(
        &[
            ("LOG_LEVEL", "info"),
            ("LOG_TARGET", "console"),
        ],
    );

    // Initialize the command-line argument parser
    let args: Vec<String> = std::env::args().collect();

    // Parse the command-line arguments
    let data_type = match args.get(1) {
        Some(arg) => arg.to_string(),
        None => "users".to_string(),
    };
    let id = match args.get(2) {
        Some(arg) => arg.parse::<u32>().unwrap_or_default(),
        None => 0,
    };

    // Initialize the connection pool
    let mut conn_pool = Arc::new(Mutex::new(ConnectionPool::new()));

    // Establish connections and start listening for incoming requests
    rt.block_on(async move {
        info!("Starting listener");
        let listener = listen_for_requests(&mut conn_pool).await;
        info!("Listener started");

        loop {
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
            // Periodically check the connection pool size and adjust it if necessary
            if let Some(pool) = &*conn_pool.lock().unwrap() {
                if pool.size() < 50 {
                    conn_pool.lock().unwrap().add_connections(5).await;
                }
            }
        }
    });
}

async fn listen_for_requests(conn_pool: &mut Arc<Mutex<ConnectionPool>>) -> tokio::net::TcpListener {
    let listener = tokio::net::TcpListener::bind("0.0.0.0:8080").unwrap();
    info!("Listening on port 8080");

    loop {
        // Accept incoming connections
        let (stream, _) = listener.accept().await.unwrap();
        info!("Accepted new connection");

        // Handle the connection in a separate task
        tokio::task::spawn(handle_connection(stream, conn_pool.clone()));
    }
}

async fn handle_connection(mut stream: tokio::net::TcpStream, conn_pool: Arc<Mutex<ConnectionPool>>) {
    // Establish a connection and start listening for requests
    let conn = conn_pool.lock().unwrap().get_or_create_connection();
    info!("Established new connection");

    loop {
        // Read the incoming request
        let mut buffer = vec![0; 1024];
        stream.read(&mut buffer).await.unwrap();

        // Process the request and send the response back
        let response = process_request(buffer);
        stream.write(response).await.unwrap();
    }
}

struct ConnectionPool {
    connections: Vec<tokio::net::TcpStream>,
}

impl ConnectionPool {
    fn new() -> Self {
        Self { connections: vec![] }
    }

    async fn add_connections(&mut self, count: u32) {
        for _ in 0..count {
            let conn = tokio::net::TcpStream::connect("example.com:8080").await.unwrap();
            self.connections.push(conn);
        }
    }

    fn get_or_create_connection(&self) -> &tokio::net::TcpStream {
        if self.connections.is_empty() {
            // Create a new connection
            let conn = tokio::net::TcpStream::connect("example.com:8080").unwrap();
            self.connections.push(conn);
            return conn;
        }
        self.connections.last().unwrap()
    }

    fn size(&self) -> u32 {
        self.connections.len() as u32
    }
}

