import json
from abc import ABC, abstractmethod
from typing import Dict, List

class Service(ABC):
    @abstractmethod
    def start(self) -> None:
        pass

    @abstractmethod
    def stop(self) -> None:
        pass

    @property
    @abstractmethod
    def type_id(self) -> str:
        pass

class ServiceDirectory:
    def __init__(self, config: Dict):
        self.config = config
        self.services = {}

    def register_service(self, service_type_id: str, service_config: Dict):
        if service_type_id not in self.config['service_types']:
            raise ValueError(f"Unsupported service type ID: {service_type_id}")
        self.services[service_type_id] = service_config

    def get_service_instance(self, service_type_id: str) -> Service:
        factory = self.config['service_factories'][service_type_id]
        return factory()

    def start_all_services(self) -> None:
        for service in self.services.values():
            service.start()

    def stop_all_services(self) -> None:
        for service in self.services.values():
            service.stop()

    def to_json(self) -> str:
        return json.dumps(self.config)

    @classmethod
    def from_json(cls, config_str: str) -> 'ServiceDirectory':
        return cls(json.loads(config_str))

    def get_services(self) -> List[Service]:
        return list(self.services.values())
