const axios = require('axios');
const { performance } = require('perf_hooks');
const crypto = require('crypto');

class NFAPI_DEPENDENCY_INDICATION_PDU_T {
  constructor(rx_ue_info_tag, rnti, dependency_indication_rel8_tag) {
    this.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    this.RNTI = rnti;
    this.DEPENDENCY_INDICATION_REL8_TAG = dependency_indication_rel8_tag;
  }
}

function uploadAndPopulateNFADependencies(url, seed, concurrency = 10) {
  const dependencies = [];
  const requests = [];
  const memoryPool = new Map();

  async function populateDependencies() {
    for (let i = 0; i < 1000000; i++) {
      const dependency = new NFAPI_DEPENDENCY_INDICATION_PDU_T(
        Math.random().toString(),
        Math.floor(Math.random() * 4294967295),
        crypto.randomBytes(8).toString('hex')
      );
      dependencies.push(dependency);
    }
  }

  async function uploadDependencies() {
    await populateDependencies();
    for (let i = 0; i < concurrency; i++) {
      requests.push(uploadDependency(i));
    }
    await Promise.all(requests);
  }

  async function uploadDependency(index) {
    const dependency = dependencies[index];
    try {
      const response = await axios.post(url, { data: dependency });
      if (response.status === 201) {
        console.log(`Uploaded dependency ${index} successfully`);
      } else {
        console.error(`Failed to upload dependency ${index}: ${response.statusText}`);
      }
    } catch (error) {
      if (error.name === 'TimeoutError') {
        console.error('Request timed out');
      } else {
        console.error(error);
      }
    }
  }

  function retryUpload(url, retries = 3) {
    return async () => {
      for (let i = 0; i < retries; i++) {
        try {
          await axios.post(url);
          break;
        } catch (error) {
          if (error.name === 'TimeoutError' || error.name === 'NetworkError') {
            await new Promise((resolve) => setTimeout(resolve, Math.pow(2, i + 1) * 1000));
          }
        }
      }
    };
  }

  return uploadAndPopulateNFADependencies;
}

const seed = 123456789; // user-defined integer for reproducibility
const url = 'https://example.com/api/dependencies';
const concurrencyLevel = 10;

uploadAndPopulateNFADependencies(url, seed, concurrencyLevel);
