        Packet* packet = &packets[i];
        if (!apply_filter(packet)) {
            printf("Packet filtered out\n");
        }
    }
}

// Function to calculate statistics on packet loss, duplication, and average packet size
void calculate_statistics(Packet* packets, int count) {
    // Calculate packet loss ratio and duplicate packet rate
    double packet_loss = (double)(count - get_valid_packets()) / count;
    double duplicate_rate = (double)get_duplicates() / count;

    // Calculate average packet size
    int total_size = 0;
    for (int i = 0; i < count; i++) {
        Packet* packet = &packets[i];
        total_size += packet->size;
    }
    double avg_packet_size = (double)total_size / count;

    printf("Packet loss: %f, Duplicate rate: %f, Average packet size: %d\n", packet_loss, duplicate_rate, avg_packet_size);
}

// Function to integrate with multiple external monitoring systems
void send_data_to_monitoring_systems(Packet* packets, int count) {
