// File extension management service
class FileExtensionService {
private:
    std::map<std::string, std::string> extensions_;
    std::mutex mutex_;
    ConfigService* configService_;

public:
    FileExtensionService(ConfigService* configService) : configService_(configService) {}

    void updateExtensions() {
        auto newExtensions = configService_->getExtensions();
        for (auto& pair : newExtensions) {
            // Update extensions_
            std::lock_guard<std::mutex> lock(mutex_);
            if (!extensions_.count(pair.first)) {
                extensions_[pair.first] = pair.second;
            }
        }
    }

    std::string getExtension(const std::string& filename) {
        auto it = extensions_.find(filename);
        return it == extensions_.end() ? "" : it->second;
    }
};

