<?php

class Message {
    private $id;
    private $from;
    private $to;
    private $text;
    private $timestamp;

    public function __construct($id, $from, $to, $text) {
        $this->id = $id;
        $this->from = $from;
        $this->to = $to;
        $this->text = $text;
        $this->timestamp = time();
    }

    public function getId() {
        return $this->id;
    }

    public function getFrom() {
        return $this->from;
    }

    public function getTo() {
        return $this->to;
    }

    public function getText() {
        return $this->text;
    }

    public function getTimestamp() {
        return $this->timestamp;
    }
}

class MessageQueue {
    private $messages = [];
    private $messageId = 0;

    public function enqueue(Message $message) {
        $this->messages[] = $message;
        $this->messageId++;
    }

    public function dequeue() {
        if (empty($this->messages)) {
            return null;
        }
        $message = array_shift($this->messages);
        return $message;
    }

    public function getMessageId() {
        return $this->messageId;
    }
}

class MessageProcessor {
    private $messageQueue;

    public function __construct(MessageQueue $messageQueue) {
        $this->messageQueue = $messageQueue;
    }

    public function processMessages() {
        while (true) {
            $message = $this->messageQueue->dequeue();
            if ($message === null) {
                break;
            }
            // Process the message here
            echo "Processing message with id: " . $message->getId() . "\n";
        }
    }
}

$messageQueue = new MessageQueue();
$messageProcessor = new MessageProcessor($messageQueue);

while (true) {
    $messageId = $messageQueue->getMessageId();
    if ($messageId > 1000) {
        break;
    }

    $message = new Message($messageId, "John", "Jane", "Hello, Jane!");
    $messageQueue->enqueue($message);
}

$messageProcessor->processMessages();

