**SIMD Instructions for CRC Flag Setting**

```c
#include <immintrin.h>

void setCRCFlag(NFAPI_CRC_INDICATION_PDU_T* array, int numElements) {
    __m256i flags = _mm256_setzero_si256();
    __m256i mask = _mm256_set1_epi32(0x01);

    for (int i = 0; i < numElements; i += 8) {
        __m256i vecFlags = _mm256_loadu_si256((__m256i*)&array[i]);
        __m256i vecMask = _mm256_loadu_si256((__m256i*)mask);
        vecFlags = _mm256_xor_si256(vecFlags, vecMask);
        _mm256_storeu_si256((__m256i*)&array[i], vecFlags);
    }
}
