    public class PageSectionController : ControllerBase
    {
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly IMemoryCache _memoryCache;
        private readonly IHtmlSanitizerService _htmlSanitizerService;

        public PageSectionController(IHttpClientFactory httpClientFactory, 
            IMemoryCache memoryCache, 
            IHtmlSanitizerService htmlSanitizerService)
        {
            _httpClientFactory = httpClientFactory;
            _memoryCache = memoryCache;
            _htmlSanitizerService = htmlSanitizerService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdatePageSection([FromBody]UpdatePageSectionRequest request)
        {
            // Validate and sanitize the HTML content using external service
            var sanitizedHtml = await _htmlSanitizerService.Sanitize(request.HtmlContent);

            // Check if page section ID is valid
            if (!IsValidPageSectionId(request.PageSectionId))
            {
                return BadRequest("Invalid page section ID");
            }

            // Cache the updated page section HTML content using LRU policy
            var cacheKey = $"page-section-{request.PageSectionId}";
            await _memoryCache.SetAsync(cacheKey, sanitizedHtml, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1)
            });

            return Ok("Page section updated successfully");
        }

        // Implement exponential backoff and circuit breakers for retry logic with external service failures

        private bool IsValidPageSectionId(string pageSectionId) => true;
    }
}

