                    throw new Exception("Invalid key");
                }

                using var encryptor = _aesCbc.CreateEncryptor(key, encryptedData.IV);

                var decryptedBytes = await Task.Run(() =>
                {
                    using var ms = new MemoryStream();
                    using var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write);
                    encryptedData.Ciphertext.CopyTo(cs);
                    cs.FlushFinalBlock();
                    return ms.ToArray();
                });

                var decryptedData = new DecryptedData
                {
                    Plaintext = Encoding.UTF8.GetString(decryptedBytes),
                    IsValid = true
                };

                _logger.Log(LogLevel.Info, $"Decryption successful for {encryptedData.KeyId}");
                return decryptedData;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Decryption failed");
                throw;
            }
        }

