// Thread-safe queue system for packet processing
typedef struct {
    pthread_mutex_t lock;
    Packet* packets[4096];
    int head, tail, count;
} PacketQueue;

PacketQueue* create_queue() {
    PacketQueue* q = (PacketQueue*)malloc(sizeof(PacketQueue));
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enqueue(PacketQueue* q, Packet* packet) {
    pthread_mutex_lock(&q->lock);
    q->packets[q->tail++] = packet;
    if(q->tail >= 4096) q->tail = 0;
    q->count++;
    pthread_mutex_unlock(&q->lock);
}

Packet* dequeue(PacketQueue* q) {
    Packet* packet;
    pthread_mutex_lock(&q->lock);
    if(q->head == q->tail) packet = NULL; // queue is empty
    else {
        packet = q->packets[q->head++];
        if(q->head >= 4096) q->head = 0;
        q->count--;
    }
    pthread_mutex_unlock(&q->lock);
    return packet;
}

