    public class AESDecryptionService
    {
        private readonly IKeyManagementService _keyManager;
        private readonly IDistributedCacheService _distributedCache;
        private readonly ILogger _logger;

        public AESDecryptionService(IKeyManagementService keyManager, IDistributedCacheService distributedCache, ILogger logger)
        {
            _keyManager = keyManager;
            _distributedCache = distributedCache;
            _logger = logger;
        }

        public async Task<DecryptedData> DecryptAsync(EncryptedData encryptedData)
        {
            try
            {
                var decryptedData = new DecryptedData();
                using (var aes = Aes.Create())
                {
                    aes.Key = await _keyManager.GetKeyAsync(encryptedData.KeyId);
                    aes.IV = await _distributedCache.GetAsync(encryptedData.InitVectorId);
                    using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
                    {
                        using (var ms = new MemoryStream())
                        {
                            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Write))
                            {
                                encryptedData.Ciphertext.CopyTo(cs);
                                cs.FlushFinalBlock();
                                var decryptedBytes = ms.ToArray();
                                decryptedData.Plaintext = Encoding.UTF8.GetString(decryptedBytes);
                            }
                        }
                    }
                }
                return decryptedData;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Decryption failed");
                throw;
            }
        }

        public void LogDecryptionAttempt(DecryptionLog log)
        {
            _logger.LogInformation($"Decryption attempt: {log.Timestamp} - Success: {log.Successful}");
        }
