typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    int listSize;
    char ueInformationTag[16];
    int crcFlag;
} ConfigStruct;

void populateListFromXML(xmlNodePtr cur, int listSize, ConfigStruct **configList) {
    xmlAttrPtr attr;
    xmlNodePtr child;
    ConfigStruct *config;

    for (int i = 0; i < listSize; i++) {
        config = (ConfigStruct *)malloc(sizeof(ConfigStruct));
        if (!config) {
            printf("Memory allocation failed\n");
            return;
        }

        attr = cur->children->attributes;
        child = xmlChildElement(cur, "ueInformationTag");
        strcpy(config->ueInformationTag, child->content);
        free(child);

        config->listSize = atoi(attr->children->content);
        config->crcFlag = atoi(attr->next->children->content);

        // Dynamic memory allocation for RNTI values
        int rntiCount = 0;
        xmlNodePtr rntiNode = xmlChildElement(cur, "rnti");
        while (rntiNode) {
            if (rntiCount >= listSize) {
                printf("Invalid configuration: RNTI count exceeds the specified size\n");
                free(config);
                return;
            }
            config->pdu[i].rnti = atoi(rntiNode->content);
            rntiNode = rntiNode->next;
        }

        if (!xmlFindChildElement(cur, "crcFlag")) {
            printf("Missing CRC flag configuration\n");
            free(config);
            return;
        }

        (*configList)++;

        free(config);
    }
}

int main() {
    xmlNodePtr root = xmlDocReadFile("config.xml");
    int listSize = 10; // Initialize with a default value
    ConfigStruct *configList = (ConfigStruct *)malloc(sizeof(ConfigStruct));

    if (!root || !xmlChildElement(root, "listSize")) {
        printf("Invalid XML configuration\n");
        return -1;
    }

    listSize = atoi(xmlChildElement(root, "listSize")->content);
    configList = (ConfigStruct *)realloc(configList, sizeof(ConfigStruct) * listSize);

    populateListFromXML(root, listSize, &configList);

    for (int i = 0; i < listSize; i++) {
        printf("RNTI: %d\n", configList[i].pdu[i].rnti);
    }

    free(configList);
    xmlFreeDoc(root);

    return 0;
}
