            printf("Error: Invalid RNTI value %s\n", config_data->ueInformationTag[i].rnti);
            continue;
        }
    }

    // Initialize cache with parsed configuration data
    cache->config_data = config_data;
    cache->last_update = time(NULL);

    // Integrate with external REST API service to validate configuration settings
    CURL* curl_handle;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl_handle = curl_easy_init();

    for (int i = 0; i < config_data->listSize; i++) {
