    curl_global_cleanup();
}

// Function to check for configuration changes and update the cache accordingly
void update_config_cache(const char* xml_file_path, ConfigCache* cache) {
    time_t current_time = time(NULL);

    if (cache->last_update + 300 <= current_time && cache->config_data != NULL) { // Cache has not been updated in last 5 minutes
        read_config_from_xml(xml_file_path, cache);
    }
}

// Function to integrate with external REST API service for data validation and caching
void validate_and_cache(const char* xml_file_path, ConfigCache* cache) {
    if (cache->config_data == NULL || time(NULL) - cache->last_update > 300) { // Cache has not been updated in last 5 minutes or is invalid
        read_config_from_xml(xml_file_path, cache);
    } else {
        // Validate configuration settings from cache and update the cache if necessary
        for (int i = 0; i < cache->config_data->listSize; i++) {
            char* url = malloc(strlen("http://api.example.com/validate_rnti?rnti=") + strlen(cache->config_data->ueInformationTag[i].rnti) + 1);
            sprintf(url, "http://api.example.com/validate_rnti?rnti=%s", cache->config_data->ueInformationTag[i].rnti);

