        }
    }
}

// Function to initialize NFAPI_CRC_INDICATION_PDU_T structures based on configuration settings
void init_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu, const ConfigCache* cache) {
