        crc_indications[i]->RNTI = get_RNTI(); // fallback mechanism
        crc_indications[i]->CRC_INDICATION_REL8_TAG = get_CRC_INDICATION_REL8_TAG();

        if (validate_CRC_indication(crc_indications[i])) {
            crc_indications[i]->CRC_flag = 1;
        } else {
            crc_indications[i]->CRC_flag = 0; // failed demodulation
        }
    }

    pthread_mutex_unlock(&sem);
}

int main() {
    // Initialize semaphore and resource pool
    sem_init(&sem, 0, N_MAX);

    // Process CRC indications
    process_crc_indications(N);

    // Clean up resources
    sem_destroy(&sem);

    return 0;
}
