void processResourceBundle(const char* resourceFile, int* array, int reductionValue, void (*callback)(int)) {
    // Load resource bundle asynchronously
    pthread_t thread;
    pthread_create(&thread, NULL, loadResourceBundle, (void*)resourceFile);
    pthread_join(thread, NULL);

    // Perform asynchronous reduction logic
    int sum = 0;
    for (int i = 0; i < *array; i++) {
        sum += array[i];
    }
    callback(sum + reductionValue);
}

