#define MAX_CMD_LENGTH 1024

typedef struct {
    int rnti;
    char rx_ue_info_tag[16];
} NFAPI_DEPENDENCY_INDICATION_PDU_T;

void generateNFADependencyIndications(int count, NFAPI_DEPENDENCY_INDICATION_PDU_T *indicators) {
    srand(time(NULL));

    for (int i = 0; i < count; i++) {
        indicators[i].rnti = rand() % 10000;
        sprintf(indicators[i].rx_ue_info_tag, "RX_%06X", rand());

        if (rand() % 2 == 1) {
            indicators[i].DEPENDENCY_FLAG = 0x01; // Randomly set the dependency flag
        } else {
            indicators[i].DEPENDENCY_FLAG = 0x02;
        }
    }
}

int executeCommand(char *cmd, char **output) {
    pid_t pid = fork();

    if (pid == 0) { // Child process
        system(cmd);
        exit(0);
    } else if (pid > 0) { // Parent process
        int status;
        wait(&status);

        if (WEXITSTATUS(status) == 0)
            return 1; // Success
        else
            return 0; // Failure
    } else {
        perror("Fork failed");
        return -1;
    }
}
