    void onServiceUnavailable() {
        cout << "Data Validation Service unavailable. Using fallback mechanism." << endl;
    }
};

// Log Processor Class
class LogProcessor {
public:
    LogProcessor(DVSC* dvsc, mutex& mtx, condition_variable& cv) : 
        dvsc_(dvsc), mtx_(mtx), cv_(cv) {}

    void processLog(const string& logData) {
        // Check if the data is valid using the DVSC
        dvsc_->requestValidation(logData);
