#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>

// Define the structure to hold semaphore information
typedef struct {
    int initial_value;
    int criticality;
    pthread_mutex_t mutex;
    sem_t semaphore;
} Semaphore;

// Function to initialize a semaphore with given initial value and criticality
void *initialize_semaphore(void *arg) {
    Semaphore *semaphore = (Semaphore *) arg;
    if(sem_init(&semaphore->semaphore, 0, semaphore->initial_value) == -1) {
        perror("Error initializing semaphore");
        return NULL;
    }
    return semaphore;
}

// Function to acquire the semaphore
void acquire_semaphore(Semaphore *semaphore) {
    pthread_mutex_lock(&semaphore->mutex);
    if(sem_wait(&semaphore->semaphore, 0) == -1) {
        perror("Error acquiring semaphore");
    }
    pthread_mutex_unlock(&semaphore->mutex);
}

// Function to release the semaphore
void release_semaphore(Semaphore *semaphore) {
    pthread_mutex_lock(&semaphore->mutex);
    if(sem_post(&semaphore->semaphore) == -1) {
        perror("Error releasing semaphore");
    }
    pthread_mutex_unlock(&semaphore->mutex);
}

// Function to set the criticality of a semaphore
void set_criticality(Semaphore *semaphore, int criticality) {
    semaphore->criticality = criticality;
}

// Function to get the criticality of a semaphore
int get_criticality(Semaphore *semaphore) {
    return semaphore->criticality;
}

// Main function to demonstrate semaphore usage
int main() {
    // Initialize a semaphore with initial value 3 and criticality 2
    Semaphore semaphore = (Semaphore) { .initial_value = 3, .criticality = 2 };
    pthread_mutex_init(&semaphore.mutex, NULL);

    // Create a thread to acquire the semaphore
    pthread_t thread;
    if(pthread_create(&thread, NULL, &initialize_semaphore, &semaphore)) {
        perror("Error creating thread");
        return -1;
    }

    // Acquire and release the semaphore
    acquire_semaphore(&semaphore);
    printf("Semaphore acquired\n");
    release_semaphore(&semaphore);
    printf("Semaphore released\n");

    // Get the criticality of the semaphore
    int criticality = get_criticality(&semaphore);
    printf("Criticality: %d\n", criticality);

    return 0;
}
