```csharp
using System;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;
using Amazon.RDS;

public class DynamicDataAccessLayer
{
    private readonly string _connectionString;
    private readonly IConfiguration _config;
    private readonly IDatabaseFactory _databaseFactory;

    public DynamicDataAccessLayer(IConfiguration config, IDatabaseFactory databaseFactory)
    {
        _config = config;
        _databaseFactory = databaseFactory;
        _connectionString = config["ConnectionStrings:DefaultConnection"];
    }

    public async Task ExecuteQueryAsync(string query, object parameters)
    {
        using var db = _databaseFactory.CreateDbContext(_connectionString);
        await db.ExecuteQueryAsync(query, parameters);
    }
}

public class DatabaseFactory : IDatabaseFactory
{
    private readonly IAmazonRDS _rds;

    public DatabaseFactory(IAmazonRDS rds)
    {
        _rds = rds;
    }

