    if video_collection.find_one({'_id': video_id}):
        cached_data = requests.get(f'https://cdn.com/{video_id}.mp4').content
        video_collection.update_one({'_id': video_id}, {'$set': {'cached_data': cached_data}})
        return jsonify({'status': 'Video cached successfully!'})
    else:
        return jsonify({'error': 'Video not found'}), 404

@app.route('/route', methods=['POST'])
def route_video():
    video_id = request.json['video_id']
    region = request.json['region']
    if video_collection.find_one({'_id': video_id}):
        cached_data = video_collection.find_one({'_id': video_id})['cached_data']
        if not cached_data:
            return jsonify({'error': 'Video is not cached'}), 404
        else:
            return cached_data, {'Content-Type': 'video/mp4'}
    else:
        return jsonify({'error': 'Video not found'}), 404

