      entryPoint: 'processLog',
      onMessage: (msg) => console.log(msg),
    });
    await worker.postMessage(req.body);
    res.send({ message: 'Log processing completed successfully' });
  } catch (err) {
    console.error(err);
    res.status(500).send({ message: 'Error processing log file' });
  }
