type (
    // Request contains the request body
    Request struct {
        *dynamodb.PutItemInput `json:"put_item"`
        *dynamodb.DeleteItemInput `json:"delete_item"`
    }

    // Response contains the response
    Response struct {
        Message string `json:"message"`
    }
)

func main() {
    lambda.Start(handleRequest)
}

func handleRequest(ctx context.Context) (interface{}, error) {
    w := aws.NewWriteAtLE(128 * 1024)
    r := aws.NewReadAtLE(256 * 1024, 2*1024*1024)

    // Initialize DynamoDB client
    dynamodbSvc := dynamodb.New(session.New(&aws.Config{Region: "us-east-1"}))

    // Handle HTTP requests
