    handler.HandleFunc("/api/update", updateResource)
    handler.HandleFunc("/api/delete", deleteResource)

    log.Println("Server started on port 8080")
    log.Fatal(http.ListenAndServe(":8080", handler))
}

func updateResource(w http.ResponseWriter, r *http.Request) {
    // Process the request
    req := &Request{}
    err := json.NewDecoder(r.Body).Decode(req)
    if err != nil {
        http.Error(w, "Invalid JSON request body", http.StatusBadRequest)
        return
    }

    // Update resource in DynamoDB
    resp, err := dynamodbSvc.PutItemWithContext(ctx, req.put_item)
    if err != nil {
        log.Println(err)
        http.Error(w, "Error updating resource", http.StatusInternalServerError)
        return
    }

    // Return the response
    res := &Response{Message: "Resource updated successfully"}
    json.NewEncoder(w).Encode(res)
}

func deleteResource(w http.ResponseWriter, r *http.Request) {
    // Process the request
    req := &Request{}
    err := json.NewDecoder(r.Body).Decode(req)
    if err != nil {
        http.Error(w, "Invalid JSON request body", http.StatusBadRequest)
        return
    }

    // Delete resource in DynamoDB
    resp, err := dynamodbSvc.DeleteItemWithContext(ctx, req.delete_item)
    if err != nil {
        log.Println(err)
        http.Error(w, "Error deleting resource", http.StatusInternalServerError)
        return
    }

    // Return the response
    res := &Response{Message: "Resource deleted successfully"}
    json.NewEncoder(w).Encode(res)
}
