NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu_list(int n, int* list_size) {
    // Initialize the list size
    *list_size = 0;

    // Create a lock for thread safety
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    // Define a function to retrieve unique RNTI values from an external database
