    NFAPI_CRC_INDICATION_PDU_T* generate_list(int n) {
        NFAPI_CRC_INDICATION_PDU_T* list = NULL;
        int i;

        // Allocate memory for the list
        pthread_mutex_lock(&list_lock);
        list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list) {
            LOG_ERROR("Failed to allocate memory for the list.");
            return NULL;
