            pdu->RX_UE_INFORMATION_TAG = rand() % 100;

            // Get a unique RNTI value from the database and set it in the structure
            pdu->RNTI = get_unique_rnti();

            // Set CRCFLAG to a random value
            pdu->CRCFLAG = (uint8_t)rand();
        }

        pthread_mutex_unlock(&list_lock);
        return list;
    }

