        // Generate and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
        NFAPI_CRC_INDICATION_PDU_T* list = generate_list(n);

        if (!list) {
            LOG_ERROR("Failed to generate the list.");
            return NULL;
