package com.example.sessionmanager;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class SessionManager {

    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private final AtomicLong tokenCounter = new AtomicLong(0);
    private final List<Token> tokens = new ArrayList<>();
    private final ExternalIdentityService identityService;
    private final ExternalDataStores dataStores;
    private final LoadBalancer loadBalancer;

    public SessionManager(ExternalIdentityService identityService, 
                           ExternalDataStores dataStores, 
                           LoadBalancer loadBalancer) {
        this.identityService = identityService;
        this.dataStores = dataStores;
        this.loadBalancer = loadBalancer;
    }

    public void createSession(String userId) throws Exception {
        Token token = generateToken(userId);
        tokens.add(token);
    }

    private Token generateToken(String userId) throws Exception {
        long timestamp = Instant.now().toEpochMillisecond();
        long sequenceNumber = tokenCounter.incrementAndGet();
        return new Token(timestamp, sequenceNumber, userId);
    }

    public boolean verifySession(Token token) throws Exception {
        if (tokens.contains(token)) {
            return true;
        } else {
            throw new Exception("Invalid token");
        }
    }

    private class Token {
        long timestamp;
        long sequenceNumber;
        String userId;

        public Token(long timestamp, long sequenceNumber, String userId) {
            this.timestamp = timestamp;
            this.sequenceNumber = sequenceNumber;
            this.userId = userId;
        }
    }
}

