```rust
// perf_analyzer.rs
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

fn analyze_performance(app_path: &str) -> String {
    let file = File::open(Path::new(&app_path).join("performance.log")).unwrap();
    let reader = BufReader::new(file);

    let mut metrics = Vec::new();

    for line in reader.lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();

        if parts.len() >= 3 {
            metrics.push((parts[0].to_string(), parts[1].parse::<f64>().unwrap()));
        }
    }

    format!("{:?}", metrics)
}

export "perf_analyzer.rs";
