// Service declaration
import { Injectable } from '@nestjs/common';
import { Observable, throwError } from 'rxjs';
import { catchError, retry } from 'rxjs/operators';

@Injectable()
export class DynamicDOMProcessor {
  private readonly apiEndpoints = ['api1.com', 'api2.com'];
  private readonly cacheTTL = 30000; // 30 seconds
  private readonly rateLimit = 5;
  private readonly retryDelay = 2000;

  constructor(private readonly httpClient: HttpClient) {}

  async processDOMTree(domTree: Element[], criteria: string[]): Promise<any[]> {
    const processedElements: any[] = [];

    for (const element of domTree) {
      if (this.matchesCriteria(element, criteria)) {
        const metadata = await this.fetchMetadata(element);
        processedElements.push({ ...element, metadata });
      }
    }

    return processedElements;
  }

  private async fetchMetadata(element: Element): Promise<any> {
    const url = `${this.apiEndpoints[0]}/metadata/${element.id}`;
    try {
      const response = await this.httpClient.get(url).toPromise();
      return response.json();
    } catch (error) {
      if (error.status === 429) {
        await new Observable(subscribe => {
          setTimeout(() => subscribe.error(error), this.retryDelay);
        }).pipe(retry(this.rateLimit)).subscribe();
        return await this.fetchMetadata(element);
      }
      throw error;
    }
  }

