  }
}

// HttpClient implementation using a caching layer and rate limiting
import { Injectable } from '@nestjs/common';
import { Observable, from } from 'rxjs';
import { cache } from 'rxfetch-cache';
import { tap } from 'rxjs/operators';

@Injectable()
export class HttpClient extends (Observable | Promise<any>) {
  private readonly cache = cache();
  private readonly rateLimiter = new RateLimiter({
    points: this.rateLimit,
    timeWindow: this.cacheTTL
  });

  constructor() {}

  get(url: string): Observable<HttpResponse<any>> {
    return from(fetch(url))
      .pipe(
        tap(response => {
          const cacheKey = `${url}-cache`;
          if (response.ok) {
            this.cache.set(cacheKey, response.json());
          }
        }),
        retryWhen(errors =>
          errors.pipe(
            tap(error => {
              if (error.status === 429) {
                this.rateLimiter.acquire().then(() => error);
              } else {
                throw error;
              }
            })
          )
        )
      );
  }
}

// Rate Limiter implementation
import { Injectable } from '@nestjs/common';
import { Observable, timer } from 'rxjs';

@Injectable()
export class RateLimiter {
  private readonly points: number;
  private readonly timeWindow: number;

  constructor(points: number, timeWindow: number) {
    this.points = points;
    this.timeWindow = timeWindow;
  }

  async acquire(): Promise<void> {
    await timer(this.timeWindow).toPromise();
  }
}
