using StackExchange.Redis;

namespace TransactionProcessor
{
    public class TransactionProcessorService : ITransactionProcessorService
    {
        private readonly ILogger<TransactionProcessorService> _logger;
        private readonly IDatabase _database;
        private readonly IRandomValueGenerator _randomValueGenerator;
        private readonly IHttpContextAccessor _httpContextAccessor;
        private readonly IAuthenticationService _authenticationService;

        public TransactionProcessorService(
            ILogger<TransactionProcessorService> logger,
            IDatabase database,
            IRandomValueGenerator randomValueGenerator,
            IHttpContextAccessor httpContextAccessor,
            IAuthenticationService authenticationService)
        {
            _logger = logger;
            _database = database;
            _randomValueGenerator = randomValueGenerator;
            _httpContextAccessor = httpContextAccessor;
            _authenticationService = authenticationService;
        }

        public async Task ProcessTransaction(Transaction transaction)
        {
            // Validate transaction data
            if (!ValidateTransaction(transaction))
            {
                return;
            }

