class JobManager:
    def __init__(self, engine_registry: List[Engine]):
        self.engine_registry = engine_registry
        self.job_queue = []
        self.executor = ThreadPoolExecutor(max_workers=10)

    def submit_job(self, task: Task) -> None:
        self.job_queue.append(task)
        self.executor.submit(self.process_job, task)

    def process_job(self, task: Task) -> None:
        for engine in self.engine_registry:
            if engine.supports_task_type(task.job_type):
                engine.submit_job(task)
                break
        else:
            # job not supported by any engine, retry later
            pass

