```csharp
public class LogMessageHandler : ILogMessageHandler
{
    private readonly ILogger _logger;
    private readonly SemaphoreSlim _logBufferSemaphore = new(100);
    private readonly Queue<LogEntry> _logEntries = new();
    private readonly CancellationTokenSource _cts = new();
    private readonly int _maxLogBufferSize = 1000000; // adjust based on performance requirements
    private readonly int _retryCount = 3;
    private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(1);

    public LogMessageHandler(ILogger logger)
    {
        _logger = logger;
    }

    public async Task LogMessageHandlerAsync(LogEntry logEntry)
    {
        await _logBufferSemaphore.WaitAsync(_cts.Token);
        try
        {
            _logEntries.Enqueue(logEntry);

            if (_logEntries.Count >= _maxLogBufferSize / 2) // adjust based on performance requirements
            {
                FlushLogs();
            }
        }
        catch (OperationCanceledException)
        {
            // log buffer was cancelled, exit method
            return;
        }
        finally
        {
            _logBufferSemaphore.Release();
        }
    }

    public async Task StartAsync()
    {
        while (_cts.IsCancellationRequested == false)
        {
            await ProcessLogsAsync();
            await _cts.Token.WaitHandle.WaitOne(_retryInterval);
        }
    }

    private async Task ProcessLogsAsync()
    {
        try
        {
            while (_logEntries.Count > 0)
            {
                LogEntry logEntry = _logEntries.Dequeue();
                await SendLogEntryToLoggerAsync(logEntry);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing logs");
            if (_retryCount > 0)
            {
                await Task.Delay(_retryInterval);
                await ProcessLogsAsync();
            }
            else
            {
                // log queue is not being processed, exit method
                return;
            }
        }
    }

    private async Task SendLogEntryToLoggerAsync(LogEntry logEntry)
    {
        try
        {
            await _logger.LogInformationAsync(logEntry);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error sending log entry to logger");
        }
    }

    public void FlushLogs()
    {
        while (_logEntries.Count > 0)
        {
            LogEntry logEntry = _logEntries.Dequeue();
            SendLogEntryToLoggerAsync(logEntry).Wait(); // adjust based on performance requirements
        }
    }

    public async Task StopAsync()
    {
        _cts.Cancel();
        await StartAsync();
    }
}
