		r.Get("/{device_id}", iotHandler)
	})

	// API endpoint for CRM system integration
	crmAPI := "https://crm.example.com/api"
	r.Get("/crm/{customer_id}", crmHandler)

	// API endpoint for ERP platform integration
	erpAPI := "https://erp.example.com/api"
	r.Get("/erp/{order_id}", erpHandler)

	// Start HTTP server
	log.Println("Starting HTTP server on port 8080...")
	http.ListenAndServe(":8080", r)
}

