using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

namespace DataManagementLibrary
{
    public class DataProvider : IDataProvider
    {
        private readonly ILogger _logger;
        private readonly ICachingStrategy _cachingStrategy;
        private readonly IAuthenticationService _authenticationService;
        private readonly IRatelimitingService _ratelimitingService;

        public DataProvider(ILogger logger, ICachingStrategy cachingStrategy, IAuthenticationService authenticationService, IRatelimitingService ratelimitingService)
        {
            _logger = logger;
            _cachingStrategy = cachingStrategy;
            _authenticationService = authenticationService;
            _ratelimitingService = ratelimitingService;
        }

        public async Task<T> GetDataAsync<T>(string dataUri, CancellationToken cancellationToken) where T : class
        {
            if (dataUri.StartsWith("file://"))
            {
                return await LoadDataFromFileAsync<T>(dataUri);
            }
            else if (dataUri.StartsWith("https://") || dataUri.StartsWith("http://"))
            {
                return await LoadDataFromRemoteApiAsync<T>(dataUri, cancellationToken);
            }
            else
            {
                // Handle unknown data sources
                throw new ArgumentException($"Unsupported data source: {dataUri}");
            }
        }

        private async Task<T> LoadDataFromFileAsync<T>(string fileUri) where T : class
        {
            try
            {
                using (var fileStream = File.OpenRead(fileUri))
                {
                    return JsonConvert.DeserializeObject<T>(fileStream);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error loading data from file");
                throw;
            }
        }

        private async Task<T> LoadDataFromRemoteApiAsync<T>(string apiUri, CancellationToken cancellationToken) where T : class
        {
            try
            {
                using var client = new HttpClient();
                var request = new HttpRequestMessage(HttpMethod.Get, apiUri);
                request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _authenticationService.GetAccessToken());

                var response = await client.SendAsync(request, cancellationToken).ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                {
                    return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync());
                }
                else
                {
                    throw new Exception($"Failed to load data from API: {apiUri}, status code: {response.StatusCode}");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error loading data from API");
                throw;
            }
        }

        public async Task LoadDataAsync(string dataUri, CancellationToken cancellationToken)
        {
            try
            {
                var data = await GetDataAsync<object>(dataUri, cancellationToken);

                if (_cachingStrategy.IsCacheable(dataUri))
                {
                    await _cachingStrategy.SetDataInCacheAsync(dataUri, data);
                }

                // Handle caching and rate limiting based on the data source
                switch (dataUri)
                {
                    case "file://local-data.json":
                        _ratelimitingService.LimitRate("File-Based", TimeSpan.FromMinutes(1));
                        break;
                    case "https://remote-api.com/data":
                        _ratelimitingService.LimitRate("Remote-API", TimeSpan.FromHours(1));
                        break;
                    default:
                        // Handle unknown data sources
                        throw new ArgumentException($"Unsupported data source: {dataUri}");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error loading and caching data");
                throw;
            }
        }
    }

    public interface IDataProvider
    {
        Task<T> GetDataAsync<T>(string dataUri, CancellationToken cancellationToken) where T : class;
    }

    public interface ICachingStrategy
    {
        bool IsCacheable(string dataUri);
        Task SetDataInCacheAsync(string dataUri, object data);
    }

    public interface IAuthenticationService
    {
        string GetAccessToken();
    }

    public interface IRatelimitingService
    {
        void LimitRate(string serviceType, TimeSpan rateLimit);
    }
}
