import json
import functools
import threading

class DynamicJSONHandler:
    def __init__(self):
        self.registry = {}
        self.cache = {}
        self.lock = threading.Lock()

    @functools.lru_cache(maxsize=None)
    def from_json(self, data):
        if not isinstance(data, str):
            raise ValueError("Input must be a JSON string")
        try:
            obj = json.loads(data)
            return type(obj)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON: {e}")

    @functools.lru_cache(maxsize=None)
    def to_json(self, obj):
        if not isinstance(obj, dict):
            raise ValueError("Input must be a dictionary")
        return json.dumps(obj)

    def register_handler(self, id, handler_class):
        self.registry[id] = handler_class

    def get_handler(self, id):
        return self.registry.get(id)

    def deserialize(self, data):
        try:
            obj = self.from_json(data)
        except ValueError as e:
            raise ValueError(f"Invalid JSON: {e}")
        return obj

    def serialize(self, obj):
        try:
            data = self.to_json(obj)
        except ValueError as e:
            raise ValueError(f"Invalid object for serialization: {e}")
        return data
