#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

class SensorData {
public:
    std::string sensorId;
    std::vector<double> data;

    SensorData(const std::string& id) : sensorId(id) {}
};

class SensorNetwork {
public:
    std::vector<SensorData*> sensors;
    std::mutex mtx;
    std::condition_variable cv;
    bool running = true;

    void addSensor(SensorData* sensor) {
        sensors.push_back(sensor);
    }

    void run() {
        while (running) {
            for (auto& sensor : sensors) {
                // Read data from sensor and process it
                if (sensor->data.empty()) continue;
                std::cout << "Received data from " << sensor->sensorId << ": ";
                for (double d : sensor->data) std::cout << d << " ";
                std::cout << std::endl;

                // Process the data here...
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    void stop() {
        running = false;
    }
};

class DataAggregator {
public:
    SensorNetwork* sensorNet;
    std::vector<std::string> aggregatedData;

    DataAggregator(SensorNetwork* net) : sensorNet(net) {}

    void aggregate() {
        while (sensorNet->running) {
            for (auto& sensor : sensorNet->sensors) {
                // Check if there is new data available
                if (sensor->data.empty()) continue;
                aggregatedData.push_back(sensor->sensorId + ": " +
                    std::to_string(sensor->data[0]));
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }
};

class KafkaClient {
public:
    DataAggregator* aggregator;

    KafkaClient(DataAggregator* aggr) : aggregator(aggr) {}

    void ingest() {
        // Read data from Kafka topic
        std::string data;
        // Process the data...
        aggregator->aggregatedData.push_back(data);
    }
};

int main() {
    SensorNetwork sensorNet;
    DataAggregator aggregator(&sensorNet);
    KafkaClient kafkaClient(&aggregator);

    std::thread sensorThread([&sensorNet]() {
        sensorNet.run();
    });

    std::thread kafkaThread([&kafkaClient]() {
        kafkaClient.ingest();
    });

    // Run the threads
    sensorThread.join();
    kafkaThread.join();

    return 0;
}
```']

