    private final LoadingCache<String, PaymentGateway> paymentGateways = CacheBuilder.newBuilder()
            .maximumSize(10)
            .expireAfterWrite(1, TimeUnit.HOURS)
            .build(new PaymentGatewayLoader());

    // Distributed rate-limiting mechanism
    private final RateLimiter rateLimiter = new RedisRateLimiter();

    // Circuit breaker for prolonged failures
    private final CircuitBreaker circuitBreaker = new HystrixCircuitBreaker();

    // Caching layer using adaptive LRU algorithm
    private final LoadingCache<String, TransactionResult> transactionResults = CacheBuilder.newBuilder()
            .maximumSize(10000)
            .expireAfterWrite(5, TimeUnit.MINUTES)
            .build(new TransactionResultLoader());

