// Define log file structures
typedef struct {
    char* timestamp;
    int status_code;
    char* request_method;
    char* request_uri;
} LogEntry;

LogEntry* read_log_file(const char* filename) {
    // Read log file and parse structured data
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    LogEntry* log_entries = (LogEntry*)malloc(sizeof(LogEntry));
    size_t entries_count = 0;
    while (fscanf(file, "%s %d %s\n", &log_entries[entries_count].timestamp, 
                  &log_entries[entries_count].status_code, &log_entries[entries_count].request_method) == 3) {
        fscanf(file, "%s\n", &log_entries[entries_count++].request_uri);
    }

    fclose(file);

    return log_entries;
}

// Compute statistical metrics like average response times
double compute_average_response_time(LogEntry* log_entries, size_t count) {
    double total_response_time = 0.0;
    for (size_t i = 0; i < count; ++i) {
        total_response_time += log_entries[i].status_code * 1000; // assume status code represents response time in ms
    }
    return total_response_time / count;
}

