type APIGateway struct {
	routes  []*Route
	metrics map[string]int64
}

type Route struct {
	Path        string
	HandlerFunc http.HandlerFunc
}

func NewAPIGateway() *APIGateway {
	return &APIGateway{
		routes: make([]*Route, 0),
		metrics: make(map[string]int64),
	}
}

func (ag *APIGateway) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	for _, route := range ag.routes {
		if route.Path == r.URL.Path {
			route.HandlerFunc(w, r)
			return
		}
	}
	http.Error(w, "Route not found", http.StatusNotFound)
}

func (ag *APIGateway) AddRoute(path string, handler http.HandlerFunc) {
	ag.routes = append(ag.routes, &Route{Path: path, HandlerFunc: handler})
}

func main() {
	gateway := NewAPIGateway()
	mux := mux.NewRouter()

	gateway.AddRoute("/users", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "Hello, user!")
	})

	http.Handle("/", gateway)
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func (ag *APIGateway) Start() {
}
