			ctx := context.WithValue(r.Context(), "requestID", time.Now().Unix())
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	})

	r.HandleFunc("/api/v1", func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.Method == http.MethodGet:
			// Handle API v1 GET requests
		case r.Method == http.MethodPost:
			// Handle API v1 POST requests
		default:
			http.Error(w, "Invalid method", http.StatusBadRequest)
		}
	})

	r.Use(jwt.New("your-secret-key"))

	authRoute := r.PathPrefix("/auth").Subrouter()
	authRoute.HandleFunc("/login", loginHandler).Methods("POST")

	dataProcessingPipelineRoute := r.PathPrefix("/data-processing-pipeline").Subrouter()
	dataProcessingPipelineRoute.HandleFunc("", dataProcessingPipelineHandler).Methods("GET")

	realtimeDataHandlingRoute := r.PathPrefix("/real-time-data-handling").Subrouter()
	realtimeDataHandlingRoute.HandleFunc("", realTimeDataHandlingHandler).Methods("POST")

	// Start the API Gateway service
	log.Println("API Gateway started on port 8080")
	http.ListenAndServe(":8080", r)
}

