function copyBytes(chunks, numBytes) {
  const dstBuffer = Buffer.allocUnsafe(numBytes);
  let bytesRead = 0;
  for (const chunk of chunks) {
    const bytesAvailable = Math.min(chunk.length, numBytes - bytesRead);
    chunk.copy(chunk, 0, dstBuffer, bytesRead, bytesRead + bytesAvailable);
    bytesRead += bytesAvailable;
  }
  return dstBuffer;
}
