class Dao {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updatePassword($userId, $oldPass, $newPass) {
        try {
            // Validate user input
            if (strlen($oldPass) < 8 || strlen($newPass) < 8) {
                throw new Exception("Password length must be at least 8 characters.");
            }

            // Check password strength
            if (!preg_match('/[a-z]/', $newPass) || !preg_match('/[A-Z]/', $newPass)) {
                throw new Exception("Password must contain at least one lowercase and uppercase letter.");
            }

            // Update user's password in database
            $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
            $stmt->execute(array($newPass, $userId));

            // Log successful update
            echo "Password updated successfully.\n";
        } catch (Exception $e) {
            // Handle error condition
            echo "Error: " . $e->getMessage() . "\n";
        }
    }
}
