#include <iostream>
#include <fstream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

// Custom logging severity levels (Error, Warning, Info, Debug)
enum class LogSeverity { Error, Warning, Info, Debug };

class Logger {
public:
    // Constructor with custom file name and rotation interval
    Logger(const std::string& filename, size_t rotationInterval) : filename_(filename), rotationInterval_(rotationInterval) {}

    // Log a message with specified severity and optional timestamp
    void log(LogSeverity severity, const std::string& message, bool timestamp = true) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (timestamp)
            message = "[" + std::chrono::system_clock::now().time_since_epoch().count() + "] ";
        message += "[" + getSeverityString(severity) + "] " + message;

        // Handle log file rotation
        rotateLogFile();

        // Append the log entry to the current log file
        ofstream_ << message << "\n";
    }

private:
    std::string filename_;
    size_t rotationInterval_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::ofstream ofstream_;

    // Helper function to get severity level string
    std::string getSeverityString(LogSeverity severity) {
        switch (severity) {
            case LogSeverity::Error:
                return "ERROR";
            case LogSeverity::Warning:
                return "WARNING";
            case LogSeverity::Info:
                return "INFO";
            case LogSeverity::Debug:
                return "DEBUG";
        }
    }

    // Helper function to rotate log file
    void rotateLogFile() {
        if (ofstream_.good()) {
            ofstream_.flush();
            std::this_thread::sleep_for(std::chrono::seconds(rotationInterval_));
            ofstream_.close();
            filename_ = getNewFileName(filename_);
            ofstream_.open(filename_, std::ios::app);
        }
    }

    // Helper function to generate a new log file name
    std::string getNewFileName(const std::string& filename) {
        size_t index = 1;
        while (true) {
            std::string newFilename = filename + "_" + std::to_string(index++);
            if (!std::ifstream(newFilename, std::ios::in))
                return newFilename;
        }
    }
};

// Example usage
int main() {
    Logger logger("example.log", 60); // Log to "example.log" with 1-minute rotation

    logger.log(LogSeverity::Error, "Error occurred");
    logger.log(LogSeverity::Warning, "Warning message");
    logger.log(LogSeverity::Info, "Informational log");

    return 0;
}
