int retrieveTransactionIDs(int start, int end) {
    // Initialize the list of valid transaction IDs
    pthread_mutex_init(&transactionListMutex, NULL);
    transactionList = (Transaction**)malloc((end - start + 1) * sizeof(Transaction*));
    pthread_mutex_lock(&transactionListMutex);

    // Iterate through the specified range and retrieve transaction IDs from API
    for (int i = start; i <= end; i++) {
        char apiRequest[256];
        sprintf(apiRequest, "https://api.example.com/transactions/%d", i);
        CURL* curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, apiRequest);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeMemoryCallback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &transactionResponse);
            curl_easy_perform(curl);
            curl_easy_cleanup(curl);

            // Validate the retrieved transaction ID
            if (transactionResponse.id >= start && transactionResponse.id <= end) {
                Transaction* newTransaction = (Transaction*)malloc(sizeof(Transaction));
                newTransaction->id = transactionResponse.id;
                newTransaction->timestamp = time(NULL);
                newTransaction->metadata = strdup(transactionResponse.metadata);
                // Add the valid transaction ID to the list
                pthread_mutex_lock(&transactionListMutex);
                int* newIndex = (int*)realloc(transactionList, (transactionListSize + 1) * sizeof(Transaction*));
                transactionList = (Transaction**)newIndex;
                transactionList[transactionListSize] = newTransaction;
                transactionListSize++;
                pthread_mutex_unlock(&transactionListMutex);
            }
        }
    }

    // Handle memory allocation failures gracefully
    if (!transactionList) {
        printf("Memory allocation failure.\n");
        return -1;
    }

    pthread_mutex_unlock(&transactionListMutex);
    return 0;
}

// Function to generate reports detailing the number and types of transaction IDs retrieved, validated, and stored over specified time periods
void generateComplianceReport(time_t start, time_t end) {
    // Iterate through the stored transaction IDs and count the number of transactions within the specified time range
    int transactionsInPeriod = 0;
    pthread_mutex_lock(&transactionListMutex);
    for (int i = 0; i < transactionListSize; i++) {
        if (transactionList[i]->timestamp >= start && transactionList[i]->timestamp <= end) {
            transactionsInPeriod++;
        }
    }
    pthread_mutex_unlock(&transactionListMutex);

    // Print the report
    printf("Transactions in period: %d\n", transactionsInPeriod);
}

