typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generateNfarcrcIndications(int numStructures) {
    // Initialize the head and tail pointers for the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    // Create a pool of objects to minimize heap allocations
    NFAPI_CRC_INDICATION_PDU_T** pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < numStructures; i++) {
        pool[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Initialize random number generator
    srand(time(NULL));

    // Populate the linked list
    for (int i = 0; i < numStructures; i++) {
        pool[i]->RX_UE_INFORMATION_TAG = rand() % 100;
        pool[i]->RNTI = rand() % 10000;
        pool[i]->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        if (head == NULL) {
            head = tail = pool[i];
        } else {
            tail->next = pool[i];
            tail = pool[i];
        }
    }

    return head;
}
