// APIGatewayConfig represents the configuration for the API gateway.
type APIGatewayConfig struct {
	Port int
}

// NewAPIGateway returns a new instance of the API gateway with the given config.
func NewAPIGateway(config *APIGatewayConfig) (*APIGateway, error) {
	return &APIGateway{
		config: config,
	}, nil
}

// APIGateway represents the API gateway service.
type APIGateway struct {
	config *APIGatewayConfig
	mux    *chi.Mux
}

// Run starts the API gateway service.
func (g *APIGateway) Run(ctx context.Context) error {
	// Create a new router instance.
	g.mux = chi.NewRouter()
	g.mux.Use(middleware.RequestID)
	g.mux.Use(middleware.RealIP)
	g.mux.Use(middleware.Logger)

	// Register API routes.
	g.mux.Route("/api/*", func(r chi.Router) {
		r.Get("/", apiHandler)
		r.Post("/", apiHandler)
	})

	// Start the HTTP server.
	srv := &http.Server{
		Addr:         fmt.Sprintf(":%d", g.config.Port),
		Handler:      g.mux,
		WriteTimeout: time.Second * 15,
		ReadTimeout:  time.Second * 15,
	}

	log.Printf("API gateway listening on port %d...", g.config.Port)
	return srv.ListenAndServe()
}

func apiHandler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "Hello, World!")
}

