    // Release any remaining resources when the object is destroyed
}

void TCPConnectionManager::addConnection(const TCP_CONNECTION_RECORD& record) {
    std::unique_lock<std::mutex> lock(mtx);
    connections[record.SRC_IP] = {std::make_shared<TCP_CONNECTION_RECORD>(record), 0};
    // Update last heartbeat time when connection is added
}

void TCPConnectionManager::removeConnection(const TCP_CONNECTION_RECORD& record) {
    std::unique_lock<std::mutex> lock(mtx);
    connections.erase(record.SRC_IP);
    // Notify waiting threads that a connection has been removed
}

bool TCPConnectionManager::getConnectionStatus(const TCP_CONNECTION_RECORD& record) const {
