			tokenInfo, err := token.ParseRequestToken(r)
			if err != nil {
				log.Println(err)
				http.Error(w, "Unauthorized access", 401)
				return
			}
			fmt.Fprintf(w, "API: %s, Token: %s", r.URL.Path, tokenInfo.RawToken())
		} else {
			http.Error(w, "Invalid Request Path", 404)
		}
	})

	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "Welcome to the Middleware Service!")
	})

	port := ":8080"
	log.Println("Server running on port", port)
	log.Fatal(http.ListenAndServe(port, cors.Default()))
}

func GetTLSConfig() *tls.Config {
	return &tls.Config{
		InsecureSkipVerify: true,
	}
}
