// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    // Valid RX_UE_INFORMATION_TAG
    char rx_ue_info_tag[16];
    // RNTI
    uint32_t rnti;
    // CRC_INDICATION_REL8_TAG with randomly set CRCFLAG
    uint16_t crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the queue structure for asynchronous processing
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PDU_QUEUE_T;

// Initialize the PDU queue
PDU_QUEUE_T* init_pdu_queue() {
    PDU_QUEUE_T* queue = (PDU_QUEUE_T*)malloc(sizeof(PDU_QUEUE_T));
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

// Enqueue a PDU
void enqueue_pdu(PDU_QUEUE_T* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue->mutex);
    queue->pdu = pdu;
    queue->size++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

// Dequeue a PDU
NFAPI_CRC_INDICATION_PDU_T* dequeue_pdu(PDU_QUEUE_T* queue) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    pthread_mutex_lock(&queue->mutex);
    if (queue->size > 0) {
        pdu = queue->pdu;
        queue->size--;
        if (queue->size == 0) {
            pthread_cond_broadcast(&queue->cond);
        }
    }
    pthread_mutex_unlock(&queue->mutex);
    return pdu;
}

// Main processing loop
void* process_pdu(void* arg) {
    PDU_QUEUE_T* queue = (PDU_QUEUE_T*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = dequeue_pdu(queue);
        if (pdu != NULL) {
            // Process the PDU
            printf("Processing PDU: %x, RNTI: %d\n", pdu->crc_ind_rel8_tag, pdu->rnti);
            free(pdu);
        }
    }
}

// Main function
int main() {
    int num_threads = 4; // Adjust according to your system resources
    pthread_t threads[num_threads];
    PDU_QUEUE_T* queue = init_pdu_queue();

    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, process_pdu, queue);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(queue);

    return 0;
}
```
