            uniqueDataPoints++;
            processedDataPoints.insert(dataPoint);
        }
    }

    // Print out total and unique data points
    std::cout << "Total Data Points: " << totalDataPoints << "\n";
    std::cout << "Unique Data Points: " << uniqueDataPoints << "\n";

    // Implement real-time deduplication by comparing each new data point with the existing set of processed data points
    for (const auto& dataPoint : dataPoints) {
        bool isDuplicate = false;
        for (const auto& existingDataPoint : processedDataPoints) {
            if (dataPoint == existingDataPoint) {
                isDuplicate = true;
                break;
            }
        }

        // If this is a duplicate, skip it and continue with the next data point
