void* asyncReduceCRCIndications(void* arg) {
    // Extract the necessary data from the argument
    int initialReduction = *(int*)arg;
    int n = N;
    NFAPI_CRC_INDICATION_PDU_T* indicationsArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the reduction value and the count of successfully created elements
    int reducedValue = initialReduction;
    int successCount = 0;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T indication;
        indication.RX_UE_INFORMATION_TAG = rand();
        indication.RNTI = rand();
        indication.CRCFLAG = rand() % 2;
        indicationsArray[i] = indication;

        // Simulate asynchronous processing
        sleep(1);
        reducedValue += indication.RX_UE_INFORMATION_TAG + indication.RNTI + indication.CRCFLAG;
        successCount++;

        // Report progress and completion status using a callback mechanism
        if (i < n - 1) {
            // Call the callback function with the accumulated value and the current number
            printf("Progress: %d/%d\n", i, n);
        } else {
            printf("Completed\n");
        }
    }

    free(indicationsArray);
    return &reducedValue;
}

int main() {
    int initialReduction = 0;

    pthread_t thread;
    pthread_create(&thread, NULL, asyncReduceCRCIndications, &initialReduction);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    printf("Final reduced value: %d\n", *(int*)pthread_getspecific(NULL));
    return 0;
}

