    data_t* data = (data_t*)arg;
    int* array = data->array;
    size_t n = data->n;
    int result = 0; // initial reduction value
    int (*callback)(int, int); // callback for asynchronous reduction

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < n; i++) {
        result = callback(result, array[i]);
    }
    pthread_mutex_unlock(&mutex);

    return &result;
}

int asyncReduceCRCIndicationsWrapper(data_t* data, int (*callback)(int, int)) {
    pthread_t thread;
    pthread_create(&thread, NULL, asyncReduceCRCIndications, data);
    pthread_join(thread, NULL);

