// JavaScript function to collect data from a stream and save it to an array

function collectDataStream(stream, arr) {
    let paused = false;

    stream.on('data', (chunk) => {
        if (!paused) {
            arr.push(chunk.toString());
        }
    });

    stream.on('pause', () => {
        paused = true;
    });

    stream.on('resume', () => {
        paused = false;
        if (arr.length > 0) {
            console.log('Resumed. Last chunk: ' + arr[arr.length - 1]);
        }
    });

    stream.on('end', () => {
        if (!paused) {
            console.log('Stream ended. Data collected:', arr);
        } else {
            console.log('Stream paused when ending. Last chunk: ' + arr[arr.length - 1]);
        }
    });
}

// Usage
let data = [];
collectDataStream(require('stream').PassThrough(), data);

setTimeout(() => {
    collectDataStream(require('stream').PassThrough(), data).pause();
}, 2000);

setTimeout(() => {
    collectDataStream(require('stream').PassThrough(), data).resume();
}, 4000);
