// Define a struct to hold command data and results
typedef struct {
    char* cmd;
    char* output;
} CommandData;

// Define a function to execute a shell command and store the result
void execute_command(CommandData* cmd_data) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: execute the command and write output to stdout
        execl("/bin/sh", "sh", "-c", cmd_data->cmd, NULL);
        _exit(1);
    } else if (pid > 0) {
        // Parent process: wait for child to finish and read output
        int status;
        waitpid(pid, &status, 0);
        FILE* file = fopen("/dev/stdin", "r");
        if (file != NULL) {
            fseek(file, 0, SEEK_END);
            int length = ftell(file);
            cmd_data->output = malloc(length + 1);
            rewind(file);
            fread(cmd_data->output, 1, length, file);
            fclose(file);
        }
    } else {
        // Error: fork failed
        perror("fork");
    }
}

