// NetworkCommunication.h
#ifndef NETWORKCOMMUNICATION_H
#define NETWORKCOMMUNICATION_H

#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <boost/asio.hpp>

namespace NetworkCommunication {
    class ClientServer {
        boost::asio::io_context ioc;
        boost::asio::ip::tcp::resolver resolver;

        void startListening(int port) {
            boost::asio::ip::tcp::acceptor acceptor(ioc, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), port));
            acceptor.listen();
        }

        void connectToServer(int port, boost::asio::ip::tcp::resolver::results_type results) {
            boost::asio::ip::tcp::socket socket(ioc);
            boost::system::error_code ec;
            boost::asio::connect(socket, results.next(), ec);

            if (ec) {
                std::cerr << "Error connecting: " << ec.message() << std::endl;
                return;
            }
        }

    public:
        ClientServer(int port) : ioc(), resolver(ioc), startListening(port) {}

        void listenAndConnect(int port, int serverPort) {
            boost::asio::ip::tcp::resolver resolver(ioc);
            boost::asio::ip::tcp::resolver::results_type results = resolver.resolve(serverPort);

            startListening(port);
            connectToServer(serverPort, results);
        }
    };

    class PeerToPeer {
        boost::asio::io_context ioc;
        boost::asio::ip::tcp::socket socket;

        void startConnecting(int port) {
            boost::asio::ip::tcp::resolver resolver(ioc);
            boost::asio::ip::tcp::resolver::results_type results = resolver.resolve(port);

            boost::system::error_code ec;
            boost::asio::connect(socket, results.next(), ec);

            if (ec) {
                std::cerr << "Error connecting: " << ec.message() << std::endl;
                return;
            }
        }

    public:
        PeerToPeer(int port) : ioc(), socket(ioc), startConnecting(port) {}
    };

    class WebSocketClient {
        boost::asio::io_context ioc;
        websocketpp::client<websocketpp::connection_hdl> ws;

        void startConnecting(std::string host, int port) {
            websocketpp::uri uri = "ws://" + host + ":" + std::to_string(port);
            ws.connect(uri);

            if (!ws.get_current_connection()) {
                std::cerr << "Error connecting to WebSocket: " << ws.get_error() << std::endl;
                return;
            }
        }

    public:
        WebSocketClient(std::string host, int port) : ioc(), ws(ioc), startConnecting(host, port) {}
    };

} // namespace NetworkCommunication

#endif // NETWORKCOMMUNICATION_H
