// Asynchronous event queue
class EventQueue {
public:
    void enqueue(const std::string& event) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(event);
        lock.unlock();
        cv_.notify_one();
    }

    bool dequeue(EventHandler& handler) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_.empty()) {
            cv_.wait(lock);
        }
        const std::string event = queue_.front();
        queue_.pop();
        handler.handleEvent(event);
        return true;
    }

