    uint32_t calculated_checksum = 0;
    // ...
    if (calculated_checksum != packet->checksum) {
        printf("Packet integrity error!\n");
        return -1;
    }
    return 0;
}

void detect_duplicates() {
    for (int i = 0; i < packet_count; i++) {
        for (int j = i + 1; j < packet_count; j++) {
            if (memcmp(&packets[i], &packets[j], sizeof(Packet)) == 0) {
                stats.duplicate_count++;
            }
        }
    }
}

double calculate_average_packet_size() {
    double sum = 0;
    for (int i = 0; i < packet_count; i++) {
        sum += packets[i].packet_size;
    }
    return sum / packet_count;
}

void update_statistics() {
