['Here is the C library code block for managing dynamic collections of LTE PHY Transport Channels (PDSCH):

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int cell_id;
    int time_frequency_grid;
    int bandwidth_part;
} PDSCH;

typedef struct {
    pthread_mutex_t mutex;
    PDSCH* pdsch_list;
    int list_size;
} PDSCH_LIST;

PDSCH_LIST* create_pdsch_list() {
    PDSCH_LIST* list = (PDSCH_LIST*)malloc(sizeof(PDSCH_LIST));
    list->pdsch_list = NULL;
    list->list_size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_pdsch_to_list(PDSCH_LIST* list, PDSCH pdsch) {
    pthread_mutex_lock(&list->mutex);
    list->pdsch_list = realloc(list->pdsch_list, (list->list_size + 1) * sizeof(PDSCH));
    list->pdsch_list[list->list_size++] = pdsch;
    pthread_mutex_unlock(&list->mutex);
}

PDSCH* get_pdsch_from_list(PDSCH_LIST* list, int cell_id, int time_frequency_grid) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->list_size; i++) {
        if (list->pdsch_list[i].cell_id == cell_id && list->pdsch_list[i].time_frequency_grid == time_frequency_grid) {
            PDSCH* pdsch = &list->pdsch_list[i];
            pthread_mutex_unlock(&list->mutex);
            return pdsch;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void free_pdsch_list(PDSCH_LIST* list) {
    for (int i = 0; i < list->list_size; i++) {
        free(list->pdsch_list[i]);
    }
    free(list->pdsch_list);
    pthread_mutex_destroy(&list->mutex);
}
