            return "Password updated successfully!";
        } else {
            return "Error updating password: " . $this->dbConn->error;
        }
    }

    public function validatePassword($user_id, $password) {
        // Retrieve the user's stored hashed password from the database
        $stored_password = "";
        $query = "SELECT password FROM users WHERE id = $user_id";
        if ($result = $this->dbConn->query($query)) {
            while ($row = $result->fetch_assoc()) {
                $stored_password = $row['password'];
            }
            $result->free();
        } else {
            return "Error retrieving stored password: " . $this->dbConn->error;
        }

        // Check if the provided password matches the stored hashed password
        if (password_verify($password, $stored_password)) {
            return true;
        } else {
            return false;
        }
    }

