const express = require('express');
const app = express();
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const compression = require('compression');
const expressWs = require('express-ws');
const { createProxyMiddleware } = require('http-proxy-middleware');
const axios = require('axios');

app.use(cors());
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  delayAfter: 5 * 60 * 1000, // 5 minutes
  max: 100,
  skipFailedRequests: true
}));

app.use(helmet());
app.use(compression());

const wsProxy = createProxyMiddleware({
  target: 'ws://localhost:8081',
  changeOrigin: true,
  pathRewrite: { '^/api': '' }
});

app.use('/api', expressWs(), (req, res) => {
  if (req.url.startsWith('/api/ws')) {
    return wsProxy(req, res);
  } else {
    return app.handle(req, res);
  }
});

const healthCheck = async () => {
  try {
    const response = await axios.get('http://localhost:8081/health');
    return response.status === 200;
  } catch (error) {
    console.error(error);
    return false;
  }
};

app.use('/health', (req, res) => {
  healthCheck().then((healthy) => {
    if (!healthy) {
      res.status(500).send({ message: 'Service Unavailable' });
    } else {
      res.send({ message: 'Healthy' });
    }
  });
});

const apiProxy = createProxyMiddleware({
  target: 'http://localhost:8082',
  changeOrigin: true,
  pathRewrite: { '^/api': '' },
  onProxyRes: (proxyRes, req) => {
    if (!proxyRes.statusCode || proxyRes.statusCode < 200 || proxyRes.statusCode >= 300) {
      return;
    }
    const timeout = Math.random() * 1000 + 500; // random delay between 500-1500ms
    setTimeout(() => {
      axios.get('http://localhost:8082/health').then((response) => {
        if (response.status === 200) {
          return;
        }
        proxyRes.destroy(new Error('Service Unavailable'));
      });
    }, timeout);
  }
});

app.use('/api', apiProxy);

const circuitBreaker = async (serviceName, serviceUrl) => {
  try {
    const response = await axios.get(serviceUrl);
    if (response.status >= 200 && response.status < 300) {
      return true;
    } else {
      throw new Error('Service Unavailable');
    }
  } catch (error) {
    console.error(error);
    return false;
  }
};

app.use('/api', (req, res, next) => {
  const serviceName = req.url.split('/')[2];
  if (!serviceName) {
    return next();
  }
  circuitBreaker(serviceName, `http://localhost:808${serviceName}/health`)
    .then((healthy) => {
      if (!healthy) {
        res.status(500).send({ message: 'Service Unavailable' });
      } else {
        return apiProxy(req, res);
      }
    })
    .catch((error) => {
      console.error(error);
      res.status(500).send({ message: 'Internal Server Error' });
    });
});

app.listen(8080, () => {
  console.log('API Gateway listening on port 8080');
});
