import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class DynamicCacheManager {
    private ConcurrentHashMap<String, CacheConfig> cacheConfigs;
    private ConcurrentHashMap<String, CacheData> cacheDatas;
    private CopyOnWriteArrayList<CacheListener> listeners;

    public DynamicCacheManager() {
        this.cacheConfigs = new ConcurrentHashMap<>();
        this.cacheDatas = new ConcurrentHashMap<>();
        this.listeners = new CopyOnWriteArrayList<>();
    }

    public void put(String key, String value) {
        CacheData data = getCacheData(key);
        if (data != null && data.getExpirationTime() > System.currentTimeMillis()) {
            // Update existing cache data
            data.setValue(value);
        } else {
            // Add new cache data
            CacheConfig config = getCacheConfig(key);
            if (config == null) {
                throw new CacheConfigurationException("No configuration found for key: " + key);
            }
            CacheData newData = new CacheData(value, System.currentTimeMillis() + config.getExpirationTime());
            putToExternalCache(key, value);
            cacheDatas.put(key, newData);
        }
    }

    public String get(String key) {
        CacheData data = getCacheData(key);
        if (data != null && data.getExpirationTime() > System.currentTimeMillis()) {
            return data.getValue();
        } else {
            return getFromExternalCache(key);
        }
    }

    public void remove(String key) {
        cacheDatas.remove(key);
        removeFromExternalCache(key);
    }

    private CacheData getCacheData(String key) {
        return cacheDatas.getOrDefault(key, null);
    }

    private CacheConfig getCacheConfig(String key) {
        return cacheConfigs.getOrDefault(key, null);
    }

