#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define the structure for NFAPI CRC indication PDU
typedef struct {
    uint32_t RNTI;
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate linked list of NFAPI CRC indications
NFAPI_CRC_INDICATION_PDU_T* generateNfaliteIndications(uint32_t N, extern uint32_t (*externalDataSource)(uint32_t)) {
    // Initialize the head and tail pointers for the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    // Initialize a counter to keep track of the number of elements generated
    uint32_t count = 0;

    // Loop until we have reached the desired number of elements (N)
    while (count < N) {
        // Get the next RNTI value from the external data source
        uint32_t rnti = externalDataSource(count);

        // Check if the generated RNTI is unique
        bool isUnique = true;
        NFAPI_CRC_INDICATION_PDU_T* current = head;
        while (current != NULL && isUnique) {
            if (current->RNTI == rnti) {
                isUnique = false;
                break;
            }
            current = current->next;
        }

        // If the generated RNTI is not unique, try again
        if (!isUnique) {
            count++;
            continue;
        }

        // Initialize a new NFAPI CRC indication PDU structure
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set the RNTI value of the PDU
        pdu->RNTI = rnti;

        // Initialize the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG fields
        pdu->RX_UE_INFORMATION_TAG = 0x0001;
        pdu->CRC_INDICATION_REL8_TAG = 0x8002;

        // Add the new PDU to the linked list
        if (head == NULL) {
            head = pdu;
            tail = pdu;
        } else {
            tail->next = pdu;
            tail = pdu;
        }

        count++;
    }

    return head;
}

// Serialization function to export the linked list to a binary format
int serializeNfaliteIndications(NFAPI_CRC_INDICATION_PDU_T* head, FILE* file) {
    // Write the number of elements in the linked list
    fwrite(&head->count, sizeof(uint32_t), 1, file);

    // Loop through the linked list and write each PDU structure to the file
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fwrite(&current->RNTI, sizeof(uint32_t), 1, file);
        fwrite(&current->RX_UE_INFORMATION_TAG, sizeof(uint16_t), 1, file);
        fwrite(&current->CRC_INDICATION_REL8_TAG, sizeof(uint16_t), 1, file);

        // Move to the next PDU in the linked list
        current = current->next;
    }

    return 0;
}
