public class SerializeAndExportToBinary(LinkedList<NFAPI_CRC_INDICATION_PDU_T> nfaIndications)
{
    using var ms = new MemoryStream();
    using var bw = new BinaryWriter(ms);

    // Serialize the linked list to binary format
    foreach (var indicationPduT in nfaIndications)
