    int cellIdentity;
    std::string frequencyBand;
    bool downlinkTransmissionConfigured;
    bool uplinkTransmissionConfigured;
};

// C-based system for managing dynamic array of TX_CELL_CONTEXT_T structures
class TX_Cell_Context_Manager {
public:
    void addCellContext(TX CELL_CONTEXT_T* cellContext) {
        std::lock_guard<std::mutex> lock(mutex_);
        cellContexts_.push_back(cellContext);
    }

    void removeCellContext(int cellIdentity) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = cellContexts_.begin(); it != cellContexts_.end();) {
            if ((*it)->cellIdentity == cellIdentity) {
                it = cellContexts_.erase(it);
                break;
            }
            ++it;
        }
    }

    TX_CELL_CONTEXT_T* getCellContext(int cellIdentity) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& cellContext : cellContexts_) {
            if (cellContext->cellIdentity == cellIdentity)
                return cellContext;
        }
        return nullptr;
    }

private:
    std::vector<TX_CELL_CONTEXT_T*> cellContexts_;
    mutable std::mutex mutex_;
};

