public class NFAPI_CRC_INDICATION_PDU_TController : ControllerBase
{
    private readonly LinkedList<NFAPI_CRC_INDICATION_PDU_T> _linkedList;

    public NFAPI_CRC_INDICATION_PDU_TController()
    {
        _linkedList = new LinkedList<NFAPI_CRC_INDICATION_PDU_T>();
    }

    [HttpPost]
    [Route("api/NFAPI_CRC_INDICATION_PDU_T")]
