angular.module('DynamicDialogService', []).factory('DynamicDialogService', ['$http', '$q', function($http, $q) {
  var cache = {};
  var refreshInterval = null;

  function refreshFields(resourceId, url, fields, priorityLevels, refreshIntervals) {
    return $q.all(fields.map(function(field) {
      if (!priorityLevels[field] || !refreshIntervals[field]) {
        return $http.get(`${url}/fields/${field}?resourceId=${resourceId}`)
          .then(function(response) {
            return response.data;
          });
      } else {
        var priority = priorityLevels[field];
        var interval = refreshIntervals[field];
        if (priority === 'high' && interval < 1000) {
          interval = 10000; // adjust for high-priority fields
        }
        return $q.when(null).delay(interval).then(function() {
          return $http.get(`${url}/fields/${field}?resourceId=${resourceid}`)
            .then(function(response) {
              return response.data;
            });
        });
      }
    }));
  }

  function cacheFields(fields, data) {
    fields.forEach(function(field) {
      cache[field] = data[field];
    });
  }

  function invalidateCache(resourceId, url) {
    for (var field in cache) {
      if (cache[field].resourceId === resourceId && cache[field].url === url) {
        delete cache[field];
      }
    }
  }

  function getFieldsFromCache(resourceId, url) {
    return Object.keys(cache).filter(function(field) {
      return cache[field].resourceId === resourceId && cache[field].url === url;
    }).map(function(field) {
      return { field: field, data: cache[field] };
    });
  }

  function getFieldsFromService(resourceId, url) {
    return $http.get(`${url}/fields?resourceId=${resourceId}`)
      .then(function(response) {
        return response.data;
      });
  }

  this.refresh = function(resourceId, url, fields, priorityLevels, refreshIntervals) {
    return refreshFields(resourceId, url, fields, priorityLevels, refreshIntervals).then(function(data) {
      cacheFields(fields, data);
      invalidateCache(resourceId, url);
      return getFieldsFromCache(resourceId, url);
    });
  };

  this.getFields = function(resourceId, url) {
    var cachedFields = getFieldsFromCache(resourceId, url);
    if (cachedFields.length > 0) {
      return $q.when(cachedFields);
    }
    return getFieldsFromService(resourceId, url).then(function(data) {
      cacheFields(Object.keys(data), data);
      invalidateCache(resourceId, url);
      return getFieldsFromCache(resourceId, url);
    });
  };
}]);
