struct SECURITY_CONTEXT_T {
    std::string symbol;
    double lastPrice;
    int quantity;
};

// Custom memory allocator for SECURTIY_CONTEXT_T array
class SecurityContextAllocator {
public:
    void* allocate(size_t size) {
        // Allocate memory and store it in the pool
        auto* mem = new char[size];
        memoryPool_.insert({mem, size});
        return mem;
    }

    void deallocate(void* ptr) {
        // Remove the allocated memory from the pool
        for (auto& entry : memoryPool_) {
            if (entry.first == ptr) {
                delete[] static_cast<char*>(ptr);
                memoryPool_.erase(entry);
                break;
            }
        }
    }

private:
    std::map<void*, size_t> memoryPool_;
};

// Function to manage the security context array
void* allocateSecurityContextArray(size_t capacity, SecurityContextAllocator& allocator) {
    // Allocate an array of SECURITY_CONTEXT_T structures using the custom allocator
    return allocator.allocate(capacity * sizeof(SECURITY_CONTEXT_T));
}

int main() {
    // Initialize the custom memory allocator
    SecurityContextAllocator allocator;

    // Allocate a security context array with 1000 elements
