class MessageBroker {
private:
    std::queue<MarketDataMessage> messages;

public:
    void produce(const MarketDataMessage& message) {
        std::unique_lock<std::mutex> lock(mutex_);
        messages.push(message);
        lock.unlock();
        condition_variable_.notify_one();
    }

    bool consume(MarketDataMessage& message) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (messages.empty()) {
            condition_variable_.wait(lock);
        }
        message = messages.front();
        messages.pop();
        return true;
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_variable_;
};

