// Function to create a new NFAPI_CRC_INDICATION_LIST_T
NFAPI_CRC_INDICATION_LIST_T *nfapi_crc_indication_list_create() {
    NFAPI_CRC_INDICATION_LIST_T *list = (NFAPI_CRC_INDICATION_LIST_T *)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->size = 0;
    list->capacity = 10; // Start with a default capacity
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add an element to the NFAPI_CRC_INDICATION_LIST_T
int nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI, char *data) {
    pthread_mutex_lock(&list->lock);

    // Check if we need to resize the array
    if (list->size == list->capacity) {
        list->capacity *= 2; // Double the capacity
        list->elements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    list->elements[list->size].RNTI = RNTI;
    list->elements[list->size].data = data;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to retrieve an element from the NFAPI_CRC_INDICATION_LIST_T
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return &list->elements[i];
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Function to remove an element from the NFAPI_CRC_INDICATION_LIST_T
int nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].RNTI == RNTI) {
            // Shift all elements after the removed element one position up
            memmove(&list->elements[i], &list->elements[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Element not found
}

// Function to free the NFAPI_CRC_INDICATION_LIST_T
void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST_T *list) {
    for (int i = 0; i < list->size; i++) {
        free(list->elements[i].data);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
