    // Initialize in-memory metrics storage and disk-based metrics storage
    in_memory_metrics.count = 0;
    in_memory_metrics.data = NULL;

    disk_file = fopen("metrics.txt", "wb");
    if(disk_file == NULL)
        printf("Failed to open disk file\n");

    while(1) {
        // Fetch new metrics from remote API or local storage
        Metric new_metric;
        fetch_metrics_from_remote_api();
        process_metric(new_metric);

        // Upload processed metrics to centralized monitoring dashboard
        upload_metrics_to_dashboard();

        // Wait for some time before processing next set of metrics
        sleep(10);
    }

    return 0;
}
```

