#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct for LTE PHY Measurement Reports
typedef struct {
    uint64_t timestamp;
    int16_t rssi;
    int16_t snr;
} measurement_report;

// Define a struct for the dynamic list of measurements
typedef struct {
    measurement_report* reports;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} measurement_list;

// Function to initialize the measurement list
measurement_list* init_measurement_list(size_t initial_capacity) {
    measurement_list* list = (measurement_list*)malloc(sizeof(measurement_list));
    list->reports = (measurement_report*)calloc(initial_capacity, sizeof(measurement_report));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a measurement report to the list
void add_measurement_report(measurement_list* list, uint64_t timestamp, int16_t rssi, int16_t snr) {
    if (list->size == list->capacity) {
        // Resize the array when it's full
        list->reports = (measurement_report*)realloc(list->reports, sizeof(measurement_report) * (list->capacity * 2));
        list->capacity *= 2;
    }
    pthread_mutex_lock(&list->mutex);
    measurement_report* report = &list->reports[list->size];
    report->timestamp = timestamp;
    report->rssi = rssi;
    report->snr = snr;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Function to update a measurement report by its unique identifier
void update_measurement_report(measurement_list* list, uint64_t id, int16_t rssi, int16_t snr) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->reports[i].timestamp == id) {
            list->reports[i].rssi = rssi;
            list->reports[i].snr = snr;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve a measurement report by its unique identifier
measurement_report* get_measurement_report(measurement_list* list, uint64_t id) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->reports[i].timestamp == id) {
            measurement_report* report = &list->reports[i];
            pthread_mutex_unlock(&list->mutex);
            return report;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to retrieve all measurement reports
measurement_report** get_all_measurement_reports(measurement_list* list) {
    pthread_mutex_lock(&list->mutex);
    measurement_report** reports = (measurement_report**)malloc(sizeof(measurement_report*) * list->size);
    for (int i = 0; i < list->size; i++) {
        reports[i] = &list->reports[i];
    }
    pthread_mutex_unlock(&list->mutex);
    return reports;
}

// Function to free the measurement list
void free_measurement_list(measurement_list* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->reports);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}
