package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"

	"github.com/gorilla/mux"
	"github.com/prometheus/client_golang/prometheus"
)

var (
	metrics = prometheus.NewRegistry()
	rateLimiter = NewRateLimiter(100, 1*time.Second)
	themeBitmapCache = map[string]*os.File{}
)

type App struct {
}

func (a *App) Run(ctx context.Context) {
	r := mux.NewRouter()

	r.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			log.Println("Received request:", r.URL.Path)
			next.ServeHTTP(w, r)
		})
	})

	r.HandleFunc("/api/v1", a.handleAPIv1).Methods("GET")
	r.HandleFunc("/api/v2", a.handleAPIv2).Methods("POST")

	http.Handle("/", r)

	go metrics.Register()

	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

func (a *App) handleAPIv1(w http.ResponseWriter, r *http.Request) {
	// API v1 handler
}

func (a *App) handleAPIv2(w http.ResponseWriter, r *http.Request) {
	// API v2 handler
}

type RateLimiter struct {
	maxRequests int
	resetTime time.Duration
	requests  uint64
	mu        sync.Mutex
}

func NewRateLimiter(max int, reset time.Duration) *RateLimiter {
	return &RateLimiter{max: max, resetTime: reset}
}

func (rl *RateLimiter) Allow(ctx context.Context) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	now := time.Now().UnixNano() / 1e6
	delta := now - rl.requests

	if delta < rl.resetTime.Seconds() {
		return false
	}

	rl.requests = now

	return true
}

func main() {
	app := &App{}
	ctx := context.Background()
	go app.Run(ctx)
	select {}
}
```']

