from typing import List
import redis
import memcached

class PaymentGatewayService:
    def __init__(self):
        self.redis_client = redis.Redis(host='localhost', port=6379, db=0)
        self.memcached_client = memcached.Client(('127.0.0.1', 11211))

    def process_payment(self, payment_info: dict) -> str:
        # Redis caching
        cached_payment_id = self.redis_client.get('payment_id')
        if cached_payment_id:
            return f'Payment ID {cached_payment_id} processed successfully'

        # Memcached caching
        memcached_payment_info = self.memcached_client.get('payment_info', 0, 300)
        if memcached_payment_info:
            return f'Memcached payment info: {memcached_payment_info}'

        # Process payment using a service mesh
        service_mesh_response = self.service_mesh_service(payment_info)

        # Save the processed payment ID in Redis and Memcached for caching
        self.redis_client.set('payment_id', payment_info['id'])
        self.memcached_client.set('payment_info', payment_info, 300)

        return f'Payment processed successfully: {service_mesh_response}'

    def service_mesh_service(self, payment_info: dict) -> str:
        # Implement service mesh logic here
