        self.read_replicas = {'us': 'read-replica-us-east-1', 'eu': 'read-replica-eu-west-1'}

    def read_from_replica(self, region: str) -> dict:
        # Read data from the read replica
        return {'data': self.read_replicas.get(region)}

class CachingService:
