```cpp
#include <iostream>
#include <map>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class Task {
public:
    std::string id;
    std::string service;
    int priority;
    // Add more task metadata as needed

    Task(const std::string& id, const std::string& service, int priority) 
        : id(id), service(service), priority(priority) {}
};

class Node {
public:
    std::string id;
    int load; // Server load metric
    bool isBusy = false;

    Node(const std::string& id, int load) 
        : id(id), load(load) {}

    void setBusy(bool busy) {
        isBusy = busy;
    }

    int getLoad() const {
        return load;
    }
};

class TaskMaster {
public:
    // Map of available nodes
    std::map<std::string, Node*> nodes;

    // Queue for incoming tasks
    std::queue<Task> taskQueue;

    // Condition variable for synchronization
    std::condition_variable cv;

    // Mutex for thread-safe access to shared state
    std::mutex mtx;

    TaskMaster() {}

    void addNode(const std::string& id, int load) {
        Node* node = new Node(id, load);
        nodes[id] = node;
    }

    void removeNode(const std::string& id) {
        nodes.erase(id);
    }

    bool scheduleTask(Task task) {
        // TO DO: Implement adaptive scheduling algorithm
        // ...
    }

    void run() {
        while (true) {
            Task task = taskQueue.front();
            taskQueue.pop();

            // TO DO: Handle failures and retries
            if (!scheduleTask(task)) {
                std::cerr << "Failed to schedule task: " << task.id << std::endl;
                continue;
            }

            // Release lock after processing the task
            cv.notify_all();
        }
    }
};

int main() {
    TaskMaster tm;

    // Add nodes to the cluster
    tm.addNode("node1", 50);
    tm.addNode("node2", 30);

    // Create tasks and submit them to the scheduler
    Task t1("task1", "serviceA", 3);
    Task t2("task2", "serviceB", 2);

    tm.taskQueue.push(t1);
    tm.taskQueue.push(t2);

    // Run the scheduler in a separate thread
    std::thread schedulerThread([&tm]() { tm.run(); });

    schedulerThread.join();

    return 0;
}
