    pthread_mutex_t mutex;
    int* integers;
    size_t size;
    size_t capacity;
} IntegerList;

// Function to validate an integer and store it in the list if valid
void add_integer(IntegerList* list, int integer) {
    // Validate the integer within the specified range
    if (integer >= INTEGER_RANGE_MIN && integer <= INTEGER_RANGE_MAX) {
        // Check if the list needs to be resized
        if (list->size == list->capacity) {
            // Resize the list with a new capacity
            list->capacity *= 2;
            list->integers = realloc(list->integers, sizeof(int) * list->capacity);
        }
        // Add the integer to the list
        list->integers[list->size++] = integer;
    }
}

// Function to retrieve and process integers from external APIs concurrently
void* api_thread(void* arg) {
    ApiResponse* response = (ApiResponse*)arg;
    int integer = response->data[0];
    // Process the integer, e.g., validate and store in the list
    add_integer(list, integer);
}

// Function to create a new API connection and process responses concurrently
void api_connect(IntegerList* list) {
    pthread_t threads[MAX_API_CONNECTIONS];
    for (int i = 0; i < MAX_API_CONNECTIONS; i++) {
        // Create a new thread for each API connection
        pthread_create(&threads[i], NULL, api_thread, response);
    }
    // Wait for all threads to complete
    for (int i = 0; i < MAX_API_CONNECTIONS; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Function to implement caching strategy and store valid integers in the list
void cache_integers(IntegerList* list) {
    // Check if the cache is full or needs to be resized
    if (list->size >= CACHE_SIZE / sizeof(int)) {
        // Resize the cache with a new capacity
        list->capacity *= 2;
        list->integers = realloc(list->integers, sizeof(int) * list->capacity);
    }
    // Store valid integers in the cache
    for (int i = 0; i < list->size; i++) {
        if (list->integers[i] >= INTEGER_RANGE_MIN && list->integers[i] <= INTEGER_RANGE_MAX) {
            // Update the cache with the valid integer
            list->integers[list->size++] = list->integers[i];
        }
    }
}

// Function to implement retry logic with exponential backoff for transient failures
void retry_api_request(ApiResponse* response, int attempts) {
    if (attempts < 3) {
        // Back off and retry the API request
        sleep(RETRY_INTERVAL * pow(BACKOFF_FACTOR, attempts));
        retry_api_request(response, attempts + 1);
    } else {
        // Log the failure and exit
        log_error("API request failed after retries");
    }
}

// Function to implement system logging
