    {
        public RX_UE_INFORMATION_TAG RxUeInformationTag { get; set; }
        public RNTI Rnti { get; set; }
        public CRC_INDICATION_REL8_TAG CrcIndicationRel8Tag { get; set; }
    }

    public class NFAPI_CRC_INDICATION_PDU_TLinkedList
    {
        private Node _head;
        private ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

        public void CreateAndPopulateNFAPICRCList()
        {
            for (int i = 0; i < 10; i++)
            {
                NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
                pdu.RxUeInformationTag = new RX_UE_INFORMATION_TAG { Tag1 = Guid.NewGuid(), Tag2 = DateTime.Now };
                pdu.Rnti = RNTI.RandomRnti();
                pdu.CrcIndicationRel8Tag = new CRC_INDICATION_REL8_TAG { CrcFlag = (ulong)new Random().Next(0, 100) };

                lock (_lock)
                {
                    Node newNode = new Node(pdu);
                    if (_head == null)
                        _head = newNode;
                    else
                    {
                        Node current = _head;
                        while (current.Next != null)
                            current = current.Next;
                        current.Next = newNode;
                    }
                }
            }
        }

        public class Node
        {
            public NFAPI_CRC_INDICATION_PDU_T Value { get; set; }
            public Node Next { get; set; }

            public Node(NFAPI_CRC_INDICATION_PDU_T value)
            {
                Value = value;
            }
        }
    }
