    class MemoryPool {
    public:
        MemoryPool(size_t size) : mem_(new char[size]), size_(size), allocated_(0) {}

        ~MemoryPool() { delete[] mem_; }

        void* allocate(size_t size) {
            if (allocated_ + size > size_) {
                return nullptr;
            }
            void* ptr = &mem_[allocated_];
            allocated_ += size;
            return ptr;
        }

        void deallocate(void* ptr, size_t size) { }

    private:
        char* mem_;
        size_t size_;
        size_t allocated_;
    };

