class MemoryAllocator {
public:
    MemoryAllocator() : memory_(nullptr), capacity_(0) {}

    void* allocate(size_t size) {
        if (memory_ == nullptr || capacity_ <= 0) {
            // Handle error case: out of memory
            return nullptr;
        }

        std::unique_lock<std::mutex> lock(mutex_);
        auto start = memory_;
        memory_ += size;
        capacity_ -= size;

        return start;
    }

    void deallocate(void* ptr, size_t size) {
        if (ptr == nullptr || size <= 0) {
            // Handle error case: invalid pointer or size
            return;
        }

        std::unique_lock<std::mutex> lock(mutex_);
        auto end = static_cast<void*>(ptr + size);
        memory_ = end;
        capacity_ += size;
    }

private:
    void* memory_;
    size_t capacity_;
    std::mutex mutex_;
};

