// CommentService.ts
import { WebSocket } from 'ws';
import { ServerSentEvent } from 'event-stream';
import * as Redis from 'ioredis';
import * as Cache from 'cache-manager';
import * as ModerationService from './moderation-service';

interface Comment {
  id: string;
  content: string;
  author: string;
}

class CommentService {
  private commentStore: any;
  private moderationService: ModerationService;
  private cache: Cache.Cache;
  private redis: Redis;

  constructor() {
    this.commentStore = require('./comment-store');
    this.moderationService = new ModerationService();
    this.cache = Cache({ store: 'memory' });
    this.redis = new Redis('localhost', 6379);
  }

  async createComment(comment: Comment) {
    try {
      // Real-time update using WebSocket
      const ws = new WebSocket('ws://comment-service:8080');
      ws.on('open', () => {
        // Send comment data to all connected clients
        ws.send(JSON.stringify({ type: 'new-comment', comment }));
      });

      // Store the comment in the database
      await this.commentStore.createComment(comment);

      // Cache the comment state for fast lookup
      this.cache.set(`comment:${comment.id}`, comment, 3600);
    } catch (error) {
      console.error('Error creating comment:', error);
    }
  }

  async getComments() {
    try {
      // Retrieve comments from database and cache
      const cachedComments = await this.cache.get('comments');
      if (!cachedComments) {
        cachedComments = await this.commentStore.getComments();
        this.cache.set('comments', cachedComments, 3600);
      }

      // Send comments to connected clients using WebSocket
      const ws = new WebSocket('ws://comment-service:8080');
      ws.on('open', () => {
        // Send comment data to all connected clients
        ws.send(JSON.stringify({ type: 'comment-list', comments: cachedComments }));
      });

      return cachedComments;
    } catch (error) {
      console.error('Error retrieving comments:', error);
    }
  }

  async updateComment(commentId: string, updatedComment: Comment) {
    try {
      // Optimize for concurrency using optimistic locking
      const storedComment = await this.commentStore.getComment(commentId);
      if (storedComment.version !== updatedComment.version) {
        throw new Error('Conflict detected - version mismatch');
      }

      // Update the comment in the database and cache
      await this.commentStore.updateComment(commentId, updatedComment);
      this.cache.set(`comment:${commentId}`, updatedComment, 3600);

      // Notify connected clients of the update using WebSocket
      const ws = new WebSocket('ws://comment-service:8080');
      ws.on('open', () => {
        // Send comment data to all connected clients
        ws.send(JSON.stringify({ type: 'updated-comment', comment: updatedComment }));
      });
    } catch (error) {
      console.error('Error updating comment:', error);
    }
  }

  async moderateComment(commentId: string) {
    try {
      // Integrate with external moderation service
      const moderationResult = await this.moderationService.moderateComment(commentId);

      // Cache the moderation result for fast lookup
      this.cache.set(`moderation:${commentId}`, moderationResult, 3600);
    } catch (error) {
      console.error('Error moderating comment:', error);
    }
  }

  async handleEvent(event: ServerSentEvent | WebSocket.Data) {
    switch (event.type) {
      case 'new-comment':
        // Handle new comment creation
        break;
      case 'comment-list':
        // Handle comment list request
        break;
      case 'updated-comment':
        // Handle updated comment notification
        break;
      default:
        console.error('Unknown event:', event);
    }
  }
}

// Start the CommentService
const commentService = new CommentService();
commentService.listen(8080);

// Define WebSocket and SSE endpoints
app.ws('/comments', (ws, request) => {
  commentService.handleEvent(request);
});

app.get('/comments', (request, response) => {
  const comments = await commentService.getComments();
  response.json(comments);
});

app.post('/comments', (request, response) => {
  const comment = request.body;
  try {
    await commentService.createComment(comment);
    response.status(201).json({ message: 'Comment created successfully' });
  } catch (error) {
    response.status(500).json({ message: 'Error creating comment' });
  }
});

app.put('/comments/:id', (request, response) => {
  const commentId = request.params.id;
  const updatedComment = request.body;
  try {
    await commentService.updateComment(commentId, updatedComment);
    response.status(200).json({ message: 'Comment updated successfully' });
  } catch (error) {
    response.status(500).json({ message: 'Error updating comment' });
  }
});

app.get('/moderation/:id', (request, response) => {
  const commentId = request.params.id;
  try {
    const moderationResult = await commentService.moderateComment(commentId);
    response.json(moderationResult);
  } catch (error) {
    response.status(500).json({ message: 'Error moderating comment' });
  }
});
