typedef struct item {
    char* name;
    double value;
    size_t id;
} item;

typedef struct list {
    size_t capacity;
    size_t size;
    item** items;
    pthread_mutex_t mutex;
} list;

list* list_create(size_t initial_capacity) {
    list* lst = malloc(sizeof(list));
    if (!lst) return NULL;
    lst->capacity = initial_capacity;
    lst->size = 0;
    lst->items = malloc(initial_capacity * sizeof(item*));
    pthread_mutex_init(&lst->mutex, NULL);
    return lst;
}

void list_destroy(list* lst) {
    for (size_t i = 0; i < lst->size; i++) {
        free(lst->items[i]->name);
        free(lst->items[i]);
    }
    free(lst->items);
    pthread_mutex_destroy(&lst->mutex);
    free(lst);
}

int list_add(list* lst, item* item) {
    if (lst->size == lst->capacity) {
        size_t new_capacity = lst->capacity * 2;
        item** new_items = realloc(lst->items, new_capacity * sizeof(item*));
        if (!new_items) return -1;
        lst->items = new_items;
        lst->capacity = new_capacity;
    }
    pthread_mutex_lock(&lst->mutex);
    lst->items[lst->size++] = item;
    pthread_mutex_unlock(&lst->mutex);
    return 0;
}

int list_get(list* lst, size_t id, item** result) {
    for (size_t i = 0; i < lst->size; i++) {
        if (lst->items[i]->id == id) {
            *result = lst->items[i];
            return 0;
        }
    }
    return -1;
}

int list_update(list* lst, size_t id, item* new_item) {
    for (size_t i = 0; i < lst->size; i++) {
        if (lst->items[i]->id == id) {
            pthread_mutex_lock(&lst->mutex);
            free(lst->items[i]->name);
            free(lst->items[i]);
            lst->items[i] = new_item;
            pthread_mutex_unlock(&lst->mutex);
            return 0;
        }
    }
    return -1;
}
