    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void *createAndPopulateNFAPICRCList(int num_elements) {
    // Initialize the linked list
    Node* head = (Node*)malloc(sizeof(Node));
    head->key = 0;
    head->child_nodes = NULL;
    head->child_node_count = 0;
    head->reference_count = 1;

    // Dynamically allocate memory for each NFAPI_CRC_INDICATION_PDU_T structure
    Node* current = head;
    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields
        strcpy(pdu->RX_UE_INFORMATION_TAG, "TAG");
        pdu->RNTI = i;
        strcpy(pdu->CRC_INDICATION_REL8_TAG, "REL8_TAG");
        pdu->CRCFLAG = rand() % 2;

        // Add the NFAPI_CRC_INDICATION_PDU_T structure to the linked list
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->key = i;
        new_node->child_nodes = NULL;
        new_node->child_node_count = 0;
        new_node->reference_count = 1;

        // Update the child_nodes and child_node_count fields of the current node
        current->child_nodes = (void**)realloc(current->child_nodes, sizeof(void*) * (current->child_node_count + 1));
        current->child_nodes[current->child_node_count++] = new_node;
        current = new_node;
    }

    return head;
}

// Function to traverse the graph using a depth-first search
void traverseGraph(Node* node) {
    // Traverse the child nodes of the current node
    for (int i = 0; i < node->child_node_count; i++) {
        Node* child_node = (Node*)node->child_nodes[i];
        printf("Key: %d, Child Key: %d\n", node->key, child_node->key);
        traverseGraph(child_node);
    }
}

