void insert_record(Collection* collection, Record* record) {
    if (collection->size == collection->capacity) {
        // Resize the array if it's full
        collection->capacity *= 2;
        collection->data = (Record*)realloc(collection->data, sizeof(Record) * collection->capacity);
    }
    collection->data[collection->size++] = *record;
}

