    for (int i = 0; i < collection->size; i++) {
        if (collection->data[i].key == key) {
            // Shift elements down to fill the gap
            for (int j = i + 1; j < collection->size; j++) {
                collection->data[j - 1] = collection->data[j];
            }
            collection->size--;
            break;
        }
    }
}

