// Cache manager
class CacheManager {
public:
    CacheManager(size_t capacity) : capacity_(capacity), packets_(capacity), images_(capacity) {}

    void addPacket(Packet packet) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (packets_.size() >= capacity_) {
            // Evict the oldest packet
            packets_.erase(packets_.begin());
        }
        packets_[packet.id] = packet;
    }

    Packet getPacket(int id) {
        std::shared_lock<std::shared_mutex> lock(mutex_);
        auto it = packets_.find(id);
        if (it != packets_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Packet not found");
        }
    }

    void addImage(Image image) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (images_.size() >= capacity_) {
            // Evict the oldest image
            images_.erase(images_.begin());
        }
        images_[image.id] = image;
    }

    Image getImage(int id) {
        std::shared_lock<std::shared_mutex> lock(mutex_);
        auto it = images_.find(id);
        if (it != images_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Image not found");
        }
    }

private:
    size_t capacity_;
    std::unordered_map<int, Packet> packets_;
    std::unordered_map<int, Image> images_;
