using Microsoft.Extensions.DependencyInjection;

namespace PaymentProcessingMicroservices
{
    public class Startup
    {
        public Startup(IConfiguration configuration)
        {
            Configuration = configuration;
        }

        public IConfiguration Configuration { get; }

        // This method gets called by the runtime. Use this method to add services to the container.
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();
            services.AddHealthChecks();

            services.AddTransient<PaymentProcessor>();

            // Register payment gateways
            foreach (var gateway in Enum.GetValues(typeof(PaymentGateway)))
            {
                services.AddTransient(gateway);
            }

            // Register CRM systems
            foreach (var crmSystem in Enum.GetValues(typeof(CrmSystem)))
            {
                services.AddTransient(crmSystem);
            }

            // Register accounting software
            foreach (var accountingSoftware in Enum.GetValues(typeof(AccountingSoftware)))
            {
                services.AddTransient(accountingSoftware);
            }
        }

        // This method gets called by the runtime. Use this method to configure the HTTP request pipeline.
        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
            }

            app.UseRouting();

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }

    public enum PaymentGateway
    {
        PayPal,
        Stripe,
        Visa,
        Mastercard
    }

    public enum CrmSystem
    {
        Salesforce,
        Dynamics,
        Zoho
    }

    public enum AccountingSoftware
    {
        QuickBooks,
        Xero,
        Wave
    }
}
