std::queue<std::string> message_queue;
std::mutex queue_mutex;
std::condition_variable queue_cv;

// Define an atomic variable to track the queue's size
std::atomic_size_t queue_size(0);

void enqueue_message(const std::string& message) {
    // Acquire the lock and ensure exclusive access
    std::unique_lock<std::mutex> lock(queue_mutex);

    // Signal a pending notification if the queue is not full
    if (queue_size < 10000) { // Adjust this limit as needed
        queue_size++;
    }
    message_queue.push(message);
    lock.unlock();
}

std::string dequeue_message() {
    std::unique_lock<std::mutex> lock(queue_mutex);

    while (message_queue.empty()) {
        // Wait if the queue is empty, ensuring fairness
        queue_cv.wait(lock);
    }

    // Dequeue and update the queue size
    std::string message = message_queue.front();
    message_queue.pop();
    queue_size--;
    return message;
}

void process_messages() {
    while (true) {
        // Acquire the lock and process the messages concurrently
        std::unique_lock<std::mutex> lock(queue_mutex);

        if (!message_queue.empty()) {
            // Process the first message in the queue
            std::string message = message_queue.front();
            message_queue.pop();
            // Your processing logic here...
            lock.unlock(); // Release the lock for other threads to access

            // Notify any waiting threads that a new message is available
            queue_cv.notify_one();
        }

        // Wait for messages, ensuring fairness under high-concurrency scenarios
        queue_cv.wait(lock);
    }
}

int main() {
    std::thread message_processor(process_messages);

    while (true) {
        // Enqueue a message to simulate incoming WebSocket traffic
        enqueue_message("Hello from C++!");

        // Test dequeueing and processing messages concurrently
