#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    void* data;
    size_t len;
    pthread_mutex_t lock;
} Message;

Message* create_message(void* data, size_t len) {
    Message* msg = (Message*) malloc(sizeof(Message));
    msg->data = data;
    msg->len = len;
    pthread_mutex_init(&msg->lock, NULL);
    return msg;
}

void destroy_message(Message* msg) {
    free(msg);
}

void push_queue(Message** queue, int* size, void* data, size_t len) {
    Message* msg = create_message(data, len);

    // Acquire read lock
    pthread_mutex_lock(&msg->lock);
    (*size)++;
    // Add message to the end of the queue
    queue[*size - 1] = msg;
    // Release read lock
    pthread_mutex_unlock(&msg->lock);
}

void pop_queue(Message** queue, int* size) {
    if (*size > 0) {
        Message* msg = queue[0];
        // Acquire write lock
        pthread_mutex_lock(&msg->lock);
        // Remove message from the start of the queue
        memmove(queue, &queue[1], *size * sizeof(Message));
        (*size)--;
        // Release write lock
        pthread_mutex_unlock(&msg->lock);
        destroy_message(msg);
    }
}

int is_queue_empty(Message** queue, int size) {
    return size == 0;
}
