class Gateway {
public:
    Gateway(int maxConcurrentConnections) : maxConcurrentConnections_(maxConcurrentConnections), 
                                               activeConnections_(0),
                                               connectionQueue_(),
                                               configurationMap_() {}

    void AddDeviceConfig(const std::string& deviceId, const std::string& protocol, int dataSamplingRate, const std::string& encryptionKey) {
        configurationMap_[deviceId] = {protocol, dataSamplingRate, encryptionKey};
    }

    void ProcessTelemetryData(const std::string& deviceId, const std::vector<uint8_t>& telemetryData) {
        if (activeConnections_ >= maxConcurrentConnections_) {
            connectionQueue_.push({deviceId, telemetryData});
        } else {
            ProcessTelemetryDataLocally(deviceId, telemetryData);
        }
    }

    void StartGateway() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this]{ return activeConnections_ < maxConcurrentConnections_; });

            if (!connectionQueue_.empty()) {
                auto connection = connectionQueue_.front();
                connectionQueue_.pop();

                ProcessTelemetryDataLocally(connection.first, connection.second);

                std::lock_guard<stdstd::mutex> lock(mutex_);
                --activeConnections_;
            }

            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

private:
    int maxConcurrentConnections_;
    int activeConnections_;
    std::queue<std::pair<std::string, std::vector<uint8_t>>> connectionQueue_;
    std::map<std::string, std::tuple<std::string, int, std::string>> configurationMap_;

    void ProcessTelemetryDataLocally(const std::string& deviceId, const std::vector<uint8_t>& telemetryData) {
        // local processing and data storage
    }
};

