#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structures
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a queue structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    int capacity;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PDU_QUEUE;

// Function to create a new queue
PDU_QUEUE* create_queue(int capacity) {
    PDU_QUEUE* queue = (PDU_QUEUE*)malloc(sizeof(PDU_QUEUE));
    queue->capacity = capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

// Function to add a pdu to the queue
void enqueue(PDU_QUEUE* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue->lock);
    if(queue->size < queue->capacity) {
        queue->pdus[queue->size] = pdu;
        queue->size++;
    } else {
        // Handle full queue
    }
    pthread_mutex_unlock(&queue->lock);
}

// Function to dequeue a pdu from the queue
NFAPI_CRC_INDICATION_PDU_T* dequeue(PDU_QUEUE* queue) {
    pthread_mutex_lock(&queue->lock);
    if(queue->size > 0) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = queue->pdus[0];
        for(int i = 1; i < queue->size; i++) {
            queue->pdus[i-1] = queue->pdus[i];
        }
        queue->size--;
    } else {
        // Handle empty queue
    }
    pthread_mutex_unlock(&queue->lock);
    return pdu;
}

// Function to process pdus in parallel
void* process_pdus(void* arg) {
    PDU_QUEUE* queue = (PDU_QUEUE*)arg;
    while(1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = dequeue(queue);
        if(pdu != NULL) {
            // Process the pdu
            printf("Processing pdu: %p\n", pdu);
        }
    }
}

// Function to create a new thread for processing pdus
void start_processing_thread(PDU_QUEUE* queue) {
    pthread_t thread;
    pthread_create(&thread, NULL, process_pdus, queue);
}

int main() {
    // Create a new queue with capacity 5
    PDU_QUEUE* queue = create_queue(5);

    // Start processing pdus in parallel
    for(int i = 0; i < 5; i++) {
        start_processing_thread(queue);
    }

    return 0;
}

