          break;
        } catch (error) {
          console.error(`Retry ${retryCount + 1} failed: ${error}`);
          currentBackoffTime *= 2;
          if (currentBackoffTime > 30000) { // 30 seconds
            throw error;
          }
          await new Promise((resolve) => setTimeout(resolve, currentBackoffTime));
        } finally {
          retryCount++;
        }
      }
    } else {
      console.error("Unknown error: ", error);
      throw error;
    }
