// Function to initialize and allocate memory for the dynamic list
DynamicList* init_dynamic_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (int*)malloc(initial_capacity * sizeof(int));
    list->len = 0;
    list->capacity = initial_capacity;
    return list;
}

// Function to resize the dynamic list
void resize_dynamic_list(DynamicList* list, size_t new_capacity) {
    int* temp = (int*)malloc(new_capacity * sizeof(int));
    memcpy(temp, list->data, list->len * sizeof(int));
    free(list->data);
    list->data = temp;
    list->capacity = new_capacity;
}

// Function to add an integer to the dynamic list
void add_to_dynamic_list(DynamicList* list, int value) {
    if (list->len == list->capacity) {
        resize_dynamic_list(list, list->capacity * 2);
    }
    list->data[list->len++] = value;
}

