        self.data_processor_manager = DataProcessorManager()
        self.database_connector = DatabaseConnector("")
        self.stream_processor = StreamProcessor("")
        self.json_rpc_client = JSONRPCClient("")

    def start(self) -> None:
        self.data_processor_manager.add_processor(SchemaValidator({}))
        self.data_processor_manager.add_processor(DataTransformer(lambda x: x))
        self.data_processor_manager.add_processor(DataMigrator({}, {}))

        while True:
            data = self.database_connector.get_data()
            for d in data:
                self.data_processor_manager.process_data(d)
            if self.stream_processor.process({}):
                break
            request = self.json_rpc_client.send_request({})
