// Recursive DOM Tree Traversal Function
function traverseDOM(node, selector, testFunction) {
  const result = [];
  (function recursiveTraversal(currentNode) {
    if (!currentNode) return;

    // Check if the current node matches the provided selector and passes the test function
    if (testFunction(currentNode)) {
      result.push(currentNode);
    }

    // Recursively traverse child nodes
    Array.from(currentNode.children).forEach(recursiveTraversal);
  })(node);

  return result;
}

