            async with websockets.connect(self.source_url) as ws:
                events = await ws.recv()
                return json.loads(events)
        except Exception as e:
            logging.error(f"Error fetching events from {self.name}: {e}")
            return {}

class EventProcessor:
    def __init__(self, event_sources: List[EventSource]):
        self.event_sources = event_sources
        self.schema_registry = SchemaRegistry()

    async def process_events(self) -> None:
        for source in self.event_sources:
            try:
                events = await source.fetch_events()
                if events:
                    await self.process_events_from_source(source, events)
            except Exception as e:
                logging.error(f"Error processing events from {source.name}: {e}")

