        self.schemas[name] = schema_version

    def get_schema(self, source_name: str) -> float:
        return self.schemas.get(source_name, 1.0)

# Performance and Scalability
async def process_events_in_parallel(event_processor: EventProcessor) -> None:
    tasks = []
    for source in event_processor.event_sources:
        task = asyncio.create_task(process_events_from_source(source))
        tasks.append(task)
    await asyncio.gather(*tasks)

class DistributedEventProcessor:
    def __init__(self, worker_count: int):
        self.worker_count = worker_count

    async def process_events(self, event_processor: EventProcessor) -> None:
        tasks = []
        for _ in range(self.worker_count):
