#include <iostream>
#include <string>
#include <vector>
#include <map>

class SerializedObject {
public:
    int id;
    std::string name;

    void serialize() {
        // Serialize object to byte array
        std::vector<char> buffer;
        buffer.resize(16);
        // Set serialization format
        for (int i = 0; i < buffer.size(); ++i) {
            buffer[i] = static_cast<char>(id + i);
        }
    }

    void deserialize(std::vector<char>& buffer) {
        // Deserialize byte array to object
        id = 0;
        name.clear();
        for (int i = 0; i < buffer.size(); ++i) {
            id += buffer[i];
            name.push_back(buffer[i]);
        }
    }
};

SerializedObject deserializeFromByteArray(std::vector<char>& bytearray) {
    SerializedObject obj;
    obj.deserialize(bytearray);
    return obj;
}

int main() {
    std::vector<char> bytearray = std::vector<char>(16);

    // Initialize serialized object
    SerializedObject obj;
    obj.id = 5;
    obj.name = "John";

    // Serialize the object to byte array
    obj.serialize();

    // Copy the serialized bytes into another buffer
    std::vector<char> deserializedBytes(obj.serialize());

    // Deserialize the bytes back into an object
    SerializedObject deserializedObj = deserializeFromByteArray(deserializedBytes);

    // Print the results
    std::cout << "Deserialized Object ID: " << deserializedObj.id << "\n";
    std::cout << "Deserialized Object Name: " << deserializedObj.name << "\n";

    return 0;
}

```

