import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

public class DeserializeByteArray {
    public static SerializedObject deserializeFromByteArray(byte[] bytearray) throws Exception {
        SerializedObject obj = null;

        try (ByteArrayInputStream bis = new ByteArrayInputStream(bytearray);
             ObjectInputStream ois = new ObjectInputStream(bis)) {

            // Deserialize the bytes back into an object
            obj = (SerializedObject) ois.readObject();

        } catch (Exception e) {
            throw e;
        }

        return obj;
    }
}
