class ResourceBundle {
public:
    int insertBundleItem(const std::string& filePath, const std::string& target, const std::string& insert, 
                           std::shared_ptr<std::forward_list<std::string>> bundle) {
        // Load file content into a local forward list
        std::ifstream file(filePath);
        if (!file.is_open()) {
            std::cerr << "Error: Unable to open file " << filePath << ".\n";
            return -1;  // File not found or error while opening
        }

        std::forward_list<std::string> bundleList;
        std::string line;
        for (std::getline(file, line); !file.eof(); std::getline(file, line)) {
            bundleList.emplace_back(line);
        }
        file.close();

        // Insert 'insert' after the first occurrence of 'target'
        auto it = bundleList.begin();
        for (; it != bundleList.end(); ++it) {
            if (*it == target) {
                bundleList.insert_after(it, insert);
                break;
            }
        }

        // Update the shared pointer to the forward list
        *bundle = bundleList;

        return 0;  // Success
    }
};

