    Operation(int priority, std::string sqlCommand, void* connectionPoolPtr)
        : priority(priority), sqlCommand(sqlCommand), connectionPoolPtr(connectionPoolPtr) {}
};

class ExecuteBatchUpdate {
public:
    ExecuteBatchUpdate(size_t threadPoolSize);

    void execute(std::vector<Operation> operations);

private:
    std::queue<Operation> operationQueue;
    std::vector<std::thread> threadPool;
    std::mutex queueMutex;
    std::condition_variable queueCondition;

    void executeOperations();
};

ExecuteBatchUpdate::ExecuteBatchUpdate(size_t threadPoolSize)
    : threadPool(threadPoolSize) {}

void ExecuteBatchUpdate::execute(std::vector<Operation> operations) {
    for (const auto& operation : operations) {
        operationQueue.push(operation);
    }

    for (auto& thread : threadPool) {
        thread.join();
    }
}

void ExecuteBatchUpdate::executeOperations() {
    while (true) {
        std::unique_lock<std::mutex> lock(queueMutex);

        if (operationQueue.empty()) {
            queueCondition.wait(lock);
        }

        Operation operation = operationQueue.front();
        operationQueue.pop();

