```php
<?php

namespace SecurityUtility;

class PasswordGenerator {
    public function generateSecureString($length, $characterSet) {
        // Robust input validation for length and character set
        if (!is_int($length) || !is_string($characterSet)) {
            throw new \InvalidArgumentException('Invalid input');
        }
        if ($length < 1) {
            throw new \InvalidArgumentException('Length must be a positive integer');
        }

        // Thread-safe mechanism for concurrent requests
        $secureString = '';
        for ($i = 0; $i < $length; $i++) {
            $characterSetRandomIndex = random_int(0, strlen($characterSet) - 1);
            $secureString .= substr($characterSet, $characterSetRandomIndex, 1);
        }
        return $secureString;
    }
}

class Hasher {
    private static $supportedAlgorithms = ['SHA-256', 'bcrypt', 'Argon2i'];

    public function hashPassword($password, $algorithm = 'default') {
        // Robust input validation for password and algorithm
        if (!is_string($password) || !in_array($algorithm, self::$supportedAlgorithms)) {
            throw new \InvalidArgumentException('Invalid input');
        }

        // Fallback mechanism for unsupported algorithms
        if (!in_array($algorithm, [ 'SHA-256', 'bcrypt' ])) {
            $algorithm = 'default';
        }

        // Secure hashing process resistant to brute-force and dictionary attacks
        // Optimized hashing function balancing security and performance
        // Comprehensive error handling for invalid inputs and hashing failures

        switch ($algorithm) {
            case 'SHA-256':
                return hash('sha256', $password);
            case 'bcrypt':
                return password_hash($password, PASSWORD_BCRYPT);
            case 'Argon2i':
                return password_hash($password, PASSWORD_ARGON2I);
            default:
                throw new \InvalidArgumentException('Unsupported algorithm');
        }
    }
}

?>
