['Here is the code for the SecurityUtility library:

```php
<?php

class SecurityUtility {
    private $characterSets = [
        'letters' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ',
        'digits'  => '0123456789',
        'special' => '!@#$%^&*()-_=+[]{}|;:,.<>?~`'
    ];

    public function generateSecureString($length, $characterSet) {
        if (!isset($this->characterSets[$characterSet])) {
            throw new Exception("Invalid character set");
        }
        $characters = $this->characterSets[$characterSet];
        $result = '';
        for ($i = 0; $i < $length; $i++) {
            $result .= $characters[rand(0, strlen($characters) - 1)];
        }
        return $result;
    }

    public function hashPassword($password, $algorithm = 'bcrypt') {
        switch ($algorithm) {
            case 'bcrypt':
                return password_hash($password, PASSWORD_BCRYPT);
            case 'argon2i':
                return sodium_crypto_pwhash_str($password, SODIUM_CRYPTO_PWHASH_ARGON2I, 12);
            default:
                throw new Exception("Unsupported hashing algorithm");
        }
    }

    public function verifyPassword($hashedPassword, $plainPassword, $salt) {
        if (!password_verify($plainPassword . $salt, $hashedPassword)) {
            return false;
        }
        return true;
    }

    public function deriveKey($password, $salt, $iterations = 10000) {
        $derivedKey = sodium_crypto_pwhash_str($password, SODIUM_CRYPTO_PWHASH_HKDF, $salt, $iterations);
        return $derivedKey;
    }
}

