// Refactored JavaScript function for recursively traversing a DOM tree
function traverseDOM(selector, callback) {
  const elements = document.querySelectorAll(selector);
  elements.forEach((element) => {
    if (callback(element)) {
      // Recursively traverse child nodes
      traverseDOM(selector, callback);
    }
  });
}

// Code Optimizations and Refactoring
const optimizedFunction = function* traverseDOMRecursively(
  selector,
  callback,
  node = document.body
) {
  for (let element of node.querySelectorAll(selector)) {
    if (!callback(element)) continue;
    yield element;
    for (let child of element.children) {
      yield* traverseDOMRecursively(selector, callback, child);
    }
  }
};
