#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Dynamic Logger Structure
typedef struct {
    pthread_mutex_t lock;
    char* log_buffer;
    size_t buffer_size;
    int log_count;
} DynamicLogger;

// Function to initialize the dynamic logger
int init_dynamic_logger(DynamicLogger* logger, size_t initial_buffer_size) {
    if ((logger->log_buffer = (char*)malloc(initial_buffer_size)) == NULL) {
        return -1; // Out of memory error
    }
    logger->buffer_size = initial_buffer_size;
    logger->log_count = 0;
    pthread_mutex_init(&logger->lock, NULL);
    return 0; // Successful initialization
}

// Function to log a message
int dynamic_log(DynamicLogger* logger, char* message) {
    pthread_mutex_lock(&logger->lock); // Lock the logger

    // Check if the buffer needs to be resized
    if (logger->log_count >= logger->buffer_size - 100) {
        size_t new_buffer_size = logger->buffer_size * 2;
        char* new_log_buffer = (char*)realloc(logger->log_buffer, new_buffer_size);
        if (new_log_buffer == NULL) {
            return -1; // Out of memory error
        }
        logger->log_buffer = new_log_buffer;
        logger->buffer_size = new_buffer_size;
    }

    // Append the message to the log buffer
    size_t len = strlen(message);
    memcpy(logger->log_buffer + logger->log_count, message, len);
    logger->log_count += len;

    pthread_mutex_unlock(&logger->lock); // Unlock the logger

    return 0; // Successful logging
}

// Function to clean up the dynamic logger
void cleanup_dynamic_logger(DynamicLogger* logger) {
    free(logger->log_buffer);
    pthread_mutex_destroy(&logger->lock);
}
```

