class BufferSystem {
public:
    BufferSystem(int buffer_size) : buffer_size_(buffer_size), buffer_() {}

    void add_frame(const unsigned char* frame_data, int frame_size) {
        std::unique_lock<std::mutex> lock(mutex_);
        buffer_.push({frame_data, frame_size});
        lock.unlock();
        cv_.notify_one();
    }

    bool get_frame(std::function<void(const unsigned char*, int)> callback) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (buffer_.empty()) {
            if (!cv_.wait_for(lock, std::chrono::microseconds(100))) {
                return false;
            }
        }
        auto frame = buffer_.front();
        buffer_.pop();
        callback(frame.first, frame.second);
        return true;
    }

private:
    int buffer_size_;
    std::queue<std::tuple<const unsigned char*, int>> buffer_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

