using System.Threading.Tasks;

namespace DistributedDesktopApp
{
    public class FileConverter
    {
        private readonly Dictionary<string, IFileFormatConverter> _formatConverters = new();
        private readonly ConcurrentQueue<FileConversionTask> _taskQueue = new();

        public void Start()
        {
            // Initialize format converters and task queue
            _formatConverters.Add("pdf", new PdfToJpgConverter());
            _formatConverters.Add("docx", new DocxToPdfConverter());

            Task.Run(() => RunTaskLoop());
        }

        private void RunTaskLoop()
        {
            while (true)
            {
                if (_taskQueue.TryDequeue(out FileConversionTask task))
                {
                    // Process file conversion task
                    ConvertFile(task.FilePath, task.Format);
                }
                else
                {
                    // No tasks to process, wait for a short period
                    Thread.Sleep(1000);
                }
            }
        }

        public void EnqueueFileConversionTask(string filePath, string format)
        {
            _taskQueue.Enqueue(new FileConversionTask(filePath, format));
        }

        private void ConvertFile(string filePath, string format)
        {
            // Use the correct file format converter
            IFileFormatConverter converter = _formatConverters[format];
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open))
            {
                using (MemoryStream memoryStream = new MemoryStream())
                {
                    converter.Convert(fileStream, memoryStream);
                    // Write converted file to disk or send to server
                }
            }
        }

        public class FileConversionTask
        {
            public string FilePath { get; set; }
            public string Format { get; set; }

            public FileConversionTask(string filePath, string format)
            {
                FilePath = filePath;
                Format = format;
            }
        }
    }

    public interface IFileFormatConverter
    {
        void Convert(Stream inputStream, Stream outputStream);
