    char* rule;
    int threshold;
} Rule;

void process_file(char* input_filename, char* output_filename, char* rules) {
    FILE* file = fopen(input_filename, "rb");
    if (!file) {
        printf("Error opening file %s\n", input_filename);
        return;
    }

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    rewind(file);

    char* buffer = malloc(size);
    fread(buffer, 1, size, file);
    fclose(file);

    // Parse rules
    Rule* rule_array = NULL;
    int num_rules = 0;

    char** tokens = strtok_r(rules, ",", &rule_array);
    while (tokens) {
        Rule rule;
        rule.rule = strdup(tokens);
        rule.threshold = atoi(strtok(NULL, ","));
        if (!rule_array) {
            rule_array = malloc(sizeof(Rule));
            num_rules = 1;
        } else {
            rule_array = realloc(rule_array, sizeof(Rule) * (num_rules + 1));
            num_rules++;
        }
        tokens = strtok(NULL, ",");
    }

    // Process file contents
    for (int i = 0; i < size; i++) {
        char c = buffer[i];
        for (int j = 0; j < num_rules; j++) {
            if (strstr(buffer + i, rule_array[j].rule) && strlen(buffer + i) > rule_array[j].threshold) {
                // Apply transformation based on rule
                printf("Applying transformation %s to byte %d\n", rule_array[j].rule, i);
                // ...
            }
        }
    }

    free(buffer);
    for (int j = 0; j < num_rules; j++) {
        free(rule_array[j].rule);
    }
    free(rule_array);

    FILE* output_file = fopen(output_filename, "wb");
    if (!output_file) {
        printf("Error opening output file %s\n", output_filename);
        return;
