public class ExponentialBackoffRetryStrategy {
    private final Sleeper sleeper;

    public ExponentialBackoffRetryStrategy(Sleeper sleeper) {
        this.sleeper = sleeper;
    }

    public void execute(Runnable task, int maxAttempts) {
        for (int attempt = 0; attempt < maxAttempts; attempt++) {
            try {
                task.run();
                return;
            } catch (Exception e) {
                // retry after some time
                sleeper.sleep(2 * (1 << attempt));
            }
        }
    }
}

