```rust
use actix::prelude::*;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;

struct MessageQueue {
    messages: Arc<Mutex<HashMap<String, Vec<String>>>>,
}

impl MessageQueue {
    fn new() -> Self {
        MessageQueue { messages: Arc::new(Mutex::new(HashMap::new())) }
    }

    fn consume_messages(&self) {
        let mut queue = self.messages.lock().unwrap();
        for (key, values) in &queue {
            println!("Consuming messages for key {}", key);
            for value in values {
                println!("Consumed message: {}", value);
            }
        }
    }
}

struct Consumer {
    message_queue: MessageQueue,
}

impl Actor for Consumer {
    type Context = Box<dyn std::any::Any + 'static>;

    fn started(&mut self, ctx: &mut Self::Context) {
        let queue = self.message_queue.clone();
        thread::spawn(move || {
            loop {
                queue.consume_messages();
                thread::sleep(std::time::Duration::from_millis(100));
            }
        });
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let sys = actix::System::new("consumer");
    let message_queue = MessageQueue::new();
    let consumer = Consumer { message_queue };

    sys.run(|ctx, _| async move {
        ctx.run(consumer);
    })
}
