#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Transaction {
    time_t timestamp;
    double weighted_sum;
} Transaction;

double filter_transactions(Transaction* transactions, int count) {
    double max_weighted_sum = 0.0;
    int max_index = -1;

    for (int i = 0; i < count; i++) {
        if (transactions[i].timestamp > (time(NULL) - 3)) { // within the last 3 seconds
            if (transactions[i].weighted_sum > max_weighted_sum) {
                max_weighted_sum = transactions[i].weighted_sum;
                max_index = i;
            }
        }
    }

    return max_weighted_sum;
}

int main() {
    Transaction* transactions = malloc(sizeof(Transaction) * 100);
    int count = 50;

    double result = filter_transactions(transactions, count);

    printf("Maximum weighted sum: %f\n", result);
    printf("Corresponding transaction ID: %d\n", max_index);

    free(transactions);
}

