void* asyncReduceCRCIndications(int* nums, int n, int initialValue, void (*callback)(void*, int), void** ctx) {
    // Initialize reduction value
    int reduction = initialValue;

    // Create an array of structures to store CRC indications
    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

