    for (int i = 0; i < n; i++) {
        int num = nums[i];
        reduction += num;
        // Create a structure and store CRC indication
        indications[i].crc = reduction % 256;

        // Call callback with progress status
        callback(ctx, i);
    }

    // Return the populated array of structures along with the count of successfully created elements
    return (void*)indications;
}

