enum class DataState { NEW, PROCESSED, FAILED };

class Node {
public:
    std::string id;
    std::queue<std::pair<DataState, int>> dataQueue;

    Node(std::string id) : id(id) {}

    void process() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !dataQueue.empty(); });
            if (!dataQueue.empty()) {
                auto [state, data] = dataQueue.front();
                dataQueue.pop();

                // Process the data
                switch (state) {
                    case DataState::NEW:
                        std::cout << "Processing new data: " << data << std::endl;
                        break;
                    case DataState::PROCESSED:
                        std::cout << "Data already processed: " << data << std::endl;
                        break;
                    case DataState::FAILED:
                        std::cout << "Failed to process data: " << data << std::endl;
                        break;
                }
            }
        }
    }

private:
