**Insert String after First Occurrence**

```cpp
#include <forward_list>
#include <string>

void insertStringAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& search, const std::string& insertion) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == search) {
            list.insert_after(it++, insertion);
            return;
        }
        ++it;
    }
    list.push_back(insertion);
}
