import java.util.function.Supplier;

public class DeserializationComponent {

    private final ExecutorService executor = Executors.newFixedThreadPool(5);
    private final ConcurrentHashMap<Class<?>, Constructor<?>> deserializers = new ConcurrentHashMap<>();
    private final ObjectMapper jsonMapper = new ObjectMapper();
    private final DescriptorUtil protobufDescriptorUtil = new DescriptorUtil();

    public void registerDeserializer(Class<?> clazz, Supplier<Constructor<?>> supplier) {
        deserializers.put(clazz, supplier.get());
    }

    public void deserialize(byte[] data) throws IOException, TException {
        try {
            if (data.length == 0) return; // ignore empty byte arrays

            ByteArrayInputStream inputStream = new ByteArrayInputStream(data);
            TProtocol protocol = getProtocol(inputStream);

            // determine the serialization format
            int magicNumber = readMagicNumber(inputStream);
            switch (magicNumber) {
                case JSON_MAGIC_NUMBER:
                    deserializeJSON(protocol);
                    break;
                case PROTOBUF_MAGIC_NUMBER:
                    deserializeProtobuf(protocol);
                    break;
                default:
                    throw new IOException("Unknown serialization format");
            }
        } catch (Exception e) {
            // handle deserialization failures
            logError(e);
            throw e;
        }
    }

    private TProtocol getProtocol(ByteArrayInputStream inputStream) throws IOException, TException {
        // determine the protocol type based on the magic number
        int magicNumber = readMagicNumber(inputStream);
        switch (magicNumber) {
            case THIRFT_MAGIC_NUMBER:
                return new TProtocol(inputStream);
            default:
                throw new IOException("Unknown protocol");
        }
