import logging
from abc import ABC, abstractmethod
from typing import Dict, List

class CloudProvider(ABC):
    @abstractmethod
    def deploy(self, app_name: str) -> None:
        pass

    @abstractmethod
    def scale(self, app_name: str, replicas: int) -> None:
        pass

    @abstractmethod
    def get_metrics(self, app_name: str) -> Dict:
        pass

class AWSECSProvider(CloudProvider):
    # AWS ECS implementation

class GCPKubernetesProvider(CloudProvider):
    # GCP Kubernetes implementation

class AzureAKSProvider(CloudProvider):
    # Azure AKS implementation

class ApplicationDeployer:
    def __init__(self, cloud_providers: List[CloudProvider]) -> None:
        self.cloud_providers = cloud_providers
        self.logger = logging.getLogger(__name__)

    def deploy(self, app_name: str) -> None:
        for provider in self.cloud_providers:
            try:
                provider.deploy(app_name)
                break
            except Exception as e:
                self.logger.error(f"Deployment failed on {provider}: {str(e)}")

    def scale(self, app_name: str, replicas: int) -> None:
        for provider in self.cloud_providers:
            try:
                provider.scale(app_name, replicas)
                break
            except Exception as e:
                self.logger.error(f"Scaling failed on {provider}: {str(e)}")

    def get_metrics(self, app_name: str) -> Dict:
        metrics = {}
        for provider in self.cloud_providers:
            try:
                metrics.update(provider.get_metrics(app_name))
            except Exception as e:
                self.logger.error(f"Failed to retrieve metrics from {provider}: {str(e)}")
        return metrics

class ContainerizedApplication:
    def __init__(self, app_name: str) -> None:
        self.app_name = app_name
        self.deployer = ApplicationDeployer([AWSECSProvider(), GCPKubernetesProvider(), AzureAKSProvider()])

    def deploy(self) -> None:
        self.deployer.deploy(self.app_name)

    def scale(self, replicas: int) -> None:
        self.deployer.scale(self.app_name, replicas)

    def get_metrics(self) -> Dict:
        return self.deployer.get_metrics(self.app_name)
