// Define a struct to represent an integer in the dynamic list
typedef struct {
    int value;
    pthread_mutex_t mutex;
} Integer;

// Define a struct to represent the dynamic list of integers
typedef struct {
    int size;
    Integer* data;
} DynamicList;

// Function to initialize and return a new dynamic list
DynamicList* createDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->size = 0;
    list->data = NULL;
    return list;
}

// Function to add an integer to the dynamic list
void addInteger(DynamicList* list, int value) {
    pthread_mutex_lock(&list->data[list->size].mutex);
    list->data = (Integer*)realloc(list->data, (list->size + 1) * sizeof(Integer));
    list->data[list->size].value = value;
    list->size++;
    pthread_mutex_unlock(&list->data[list->size-1].mutex);
}

// Function to remove an integer from the dynamic list
void removeInteger(DynamicList* list, int index) {
    if (index >= list->size || index < 0) return;
    pthread_mutex_lock(&list->data[index].mutex);
    memmove(&list->data[index], &list->data[index + 1], (list->size - index - 1) * sizeof(Integer));
    free(list->data[list->size-1].value);
    list->size--;
    pthread_mutex_unlock(&list->data[index].mutex);
}

// Function to iterate over the dynamic list
void iterateDynamicList(DynamicList* list, void (*callback)(int)) {
    for (int i = 0; i < list->size; i++) {
        callback(list->data[i].value);
    }
}

// Function to validate an integer and store it in the dynamic list
