    // Register logging services
    LoggingService services[] = {
        {"console", writeConsole},
        {"file", (void(*)(const LogEvent*))writeFile},
        {"remote_server", (void(*)(const LogEvent*, const char*, int))writeRemoteServer}
    };
    // Initialize the logging services
}

// Write log to console
