using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureFileGenerator
{
    public async Task<string> GenerateAndDecryptFilenameAsync(byte[] ciphertext, string encryptionKey, byte[] initializationVector)
    {
        // Input validation
        if (ciphertext.Length == 0 || encryptionKey.Length == 0 || initializationVector.Length == 0)
            throw new ArgumentException("Input parameters cannot be empty.");

        using var aescrypto = Aes.Create();
        aescrypto.Key = Encoding.UTF8.GetBytes(encryptionKey);
        aescrypto.IV = initializationVector;

        // Decrypt ciphertext
        using var ms = new MemoryStream(ciphertext);
        using var cs = new CryptoStream(ms, aescrypto.CreateDecryptor(), CryptoStreamMode.Read);
        byte[] decryptedBytes;
        try
        {
            decryptedBytes = new byte[cs.Length];
            await cs.ReadAsync(decryptedBytes.AsMemory(0, decryptedBytes.Length), 0, decryptedBytes.Length);
        }
        catch (Exception ex)
        {
            // Log error and return failure status
            throw new Exception("Decryption failed: " + ex.Message);
        }

        // Serialize plaintext to custom data structure using BinaryFormatter
        using var formatter = new BinaryFormatter();
        try
        {
            using var ms2 = new MemoryStream();
            formatter.Serialize(ms2, decryptedBytes);
            byte[] serializedData;
            await ms2.ReadAsync(serializedData.AsMemory(0, serializedData.Length), 0, serializedData.Length);

            // Generate filename prefix from first five characters of original filename
            int sum = 0;
            for (int i = 0; i < 5; i++)
                sum += (int)decryptedBytes[i];

            // Use the first ten digits of this sum as part of the new filename
            string filenamePrefix = sum.ToString("0000000000").Substring(0, 10);

            // Fetch latest version number from external API and incorporate it into filename
            int latestVersion;
            try
            {
                using var httpClient = new HttpClient();
                var response = await httpClient.GetAsync("https://example.com/latest-version");
                response.EnsureSuccessStatusCode();
                using var stream = await response.Content.ReadAsStreamAsync();
                using var sr = new StreamReader(stream);
                latestVersion = Convert.ToInt32(sr.ReadLine());
            }
            catch (Exception ex)
            {
                // Log error and return failure status
                throw new Exception("Failed to fetch version number: " + ex.Message);
            }

            // Generate unique filename combining prefix, version number, and IV
            string filename = $"{filenamePrefix}-{latestVersion}-{BitConverter.ToString(initializationVector).Replace("-", "")}.bin";

            return filename;
        }
        catch (Exception ex)
        {
            // Log error and return failure status
            throw new Exception("Deserialization failed: " + ex.Message);
        }
    }
}
