// KafkaErrorHandler.java
package com.example.tenantmicroservice;

import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;

@Component
public class KafkaErrorHandler implements ErrorHandler {

    private final KafkaTemplate<String, String> kafkaTemplate;

    public KafkaErrorHandler(KafkaTemplate<String, String> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    @Override
    public void handle(Exception ex) {
        // log the error and re-try sending the message to the topic
        try {
            kafkaTemplate.send("orders", ex.getMessage());
        } catch (Exception e) {
            // log the retry failure and re-try if necessary
        }
    }
}
