from aiohttp import ClientSession
from tenacity import retry, stop_after_attempt, wait_fixed

class DataIngestion:
    def __init__(self):
        self.config = {}
        self.connections = {}

    async def connect_to_db(self, db_config):
        conn_pool = await aiomysql.create_pool(**db_config)
        return conn_pool

    async def execute_query(self, query, params=None):
        for connection_name, conn in self.connections.items():
            if conn_name.startswith('db'):
                conn.execute(query, params)

    async def send_request(self, url, method='GET', data={}):
        async with ClientSession() as session:
            async with session.request(method, url, json=data) as response:
                return await response.text()

    @retry(stop=stop_after_attempt(3), wait=wait_fixed(1))
    async def process_data(self, data):
        try:
            # Process data here
            pass
        except Exception as e:
            print(f"Error processing data: {e}")
            raise

    async def ingest_data(self, data_source):
        if data_source.type == 'db':
            conn = await self.connect_to_db(data_source.config)
            await self.execute_query("SELECT * FROM table_name")
        elif data_source.type == 'api':
            response = await self.send_request(data_source.url)
            await self.process_data(response)

    async def run(self):
        data_sources = [
            {'type': 'db', 'config': {'host': 'localhost', 'port': 3306, 'user': 'root', 'password': 'password'}},
            {'type': 'api', 'url': 'https://example.com/api'},
            # Add more data sources here
        ]

        for data_source in data_sources:
            await self.ingest_data(data_source)

if __name__ == '__main__':
    asyncio.run(DataIngestion().run())
