    public class EncryptionService : IEncryptionService
    {
        private readonly IExternalEncryptionApi _externalApi;
        private readonly ICryptoProvider _cryptoProvider;
        private readonly IKeyManager _keyManager;

        public EncryptionService(IExternalEncryptionApi externalApi, ICryptoProvider cryptoProvider, IKeyManager keyManager)
        {
            _externalApi = externalApi;
            _cryptoProvider = cryptoProvider;
            _keyManager = keyManager;
        }

        public async Task<string> DecryptAsync(string encryptedMessage)
        {
            try
            {
                var decryptedBytes = await DecryptBytesAsync(encryptedMessage);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
            catch (Exception ex)
            {
                Log.DecryptionError(ex);
                throw;
            }
        }

        private async Task<byte[]> DecryptBytesAsync(string encryptedMessage)
        {
            // Use circuit breaker pattern to handle API throttling and errors
            if (_keyManager.KeyStatus == KeyStatus.Available)
            {
                var decryptedBytes = await _cryptoProvider.DecryptAsync(encryptedMessage);
                return decryptedBytes;
            }
            else
            {
                try
                {
                    // Fallback to external decryption service if local decryption fails
                    var decryptedBytes = await _externalApi.DecryptAsync(encryptedMessage);
                    return decryptedBytes;
                }
                catch (Exception ex)
                {
                    Log.FallbackDecryptionError(ex);
                    throw new Exception("Decryption failed. Please try again.");
                }
            }
        }

        public async Task StartServiceAsync()
        {
            // Initialize cache for frequently used encryption keys and IVs
            _keyManager.InitializeCache();

            // Optimize for concurrent access by ensuring thread safety
            await Task.Run(() => { });
        }
    }
}
