struct WebSocketMessage {
    std::string message;
    bool isValid = false; // Flag for sanitization result
};

class DynamicQueue {
public:
    void enqueue(const WebSocketMessage& message) {
        lock_guard<mutex> lock(queueMutex);
        queue_.push(message);
    }

    WebSocketMessage dequeue() {
        lock_guard<mutex> lock(queueMutex);
        if (queue_.empty()) {
            // Handle empty queue
            return {};
        }
        WebSocketMessage msg = queue_.front();
        queue_.pop();
        return msg;
    }

    bool isEmpty() {
        lock_guard<mutex> lock(queueMutex);
        return queue_.empty();
    }

private:
    std::queue<WebSocketMessage> queue_;
    mutable mutex queueMutex;
    condition_variable queueCV;
};

class WebSocketSanitizer {
public:
    std::string sanitize(const std::string& message) {
        // Implement HTML sanitization logic
        // ...
    }
};

class WebSocketHandler {
public:
    void handleWebSocketMessage(const WebSocketMessage& message, DynamicQueue* queue, WebSocketSanitizer* sanitizer) {
        if (!message.isValid) {
            return; // Ignore invalid messages
        }

        // Process sanitized message
        // ...

        // Push processed message to the dynamic queue
        queue->enqueue(message);
    }
};

// Example usage:
int main() {
    DynamicQueue queue;
    WebSocketSanitizer sanitizer;
    WebSocketHandler handler;

    // Enqueue a message
    WebSocketMessage msg1 = {"<p>Hello!</p>", true};
    handler.handleWebSocketMessage(msg1, &queue, &sanitizer);

    // Dequeue and process messages
    while (!queue.isEmpty()) {
        WebSocketMessage msg = queue.dequeue();
        if (msg.isValid) {
            handler.handleWebSocketMessage(msg, &queue, &sanitizer);
        }
    }

    return 0;
}
